// One-off corpus measurement: result sizes per tool/action, notice and member-context injection sizes,
// and what the model does right after unread_required / stale_revision.
import { readdirSync } from 'node:fs'
import { join } from 'node:path'
import { spawnSync } from 'node:child_process'
const ROOT = `${process.env.HOME}/.dsh/sessions`
function* walk(d) { for (const e of readdirSync(d, { withFileTypes: true })) { const p = join(d, e.name); if (e.isDirectory()) yield* walk(p); else if (e.name.endsWith('.jsonl.zstd')) yield p } }
const sizes = new Map(), injections = new Map(), after = new Map()
const add = (m, k, v) => { if (!m.has(k)) m.set(k, []); m.get(k).push(v) }
let files = 0
for (const f of walk(ROOT)) {
  files++
  const r = spawnSync('zstd', ['-dc', f], { maxBuffer: 1024 * 1024 * 1024 })
  if (r.status !== 0) continue
  const pending = new Map(); const seq = []  // per-file ordered team calls with outcome
  for (const line of r.stdout.toString('utf8').split('\n')) {
    if (!line) continue
    let ev; try { ev = JSON.parse(line) } catch { continue }
    const d = ev.data; if (!d) continue
    if (ev.type === 'tool/call' && typeof d.name === 'string' && d.name.startsWith('team_')) {
      let a = {}; try { a = JSON.parse(d.arguments) } catch {}
      pending.set(d.callId, { tool: d.name, action: a.action ?? '-', args: a })
    } else if (ev.type === 'tool/result' && d.message?.toolCallId && pending.has(d.message.toolCallId)) {
      const c = pending.get(d.message.toolCallId); pending.delete(d.message.toolCallId)
      const text = (d.message.content || []).filter(x => x?.type === 'text').map(x => x.text).join('\n')
      const cls = d.message.isError ? 'thrown' : /^Not committed — (unread_required|main_unread_required)/.test(text) ? RegExp.$1 : /^Not committed — .*stale_revision/.test(text) ? 'stale_revision' : /^Not committed/.test(text) ? 'reject-other' : 'ok'
      const scope = c.args.projectRef && c.tool === 'team_thread' ? ':main' : ''
      add(sizes, `${c.tool} ${c.action}${scope} ${cls === 'ok' ? '' : cls}`.trim(), text.length)
      seq.push({ ...c, cls, base: c.args.baseRevision, text })
    } else if (ev.type === 'user/message' && d.source && typeof d.source.kind === 'string') {
      const k = d.source.kind
      if (!/agent-team/.test(k)) continue
      const text = (d.content || []).filter(x => x?.type === 'text').map(x => x.text).join('\n')
      const label = /member-context/.test(k) ? 'member-context block' : /time-context/.test(k) ? 'time-context' : `${k.replace(/.*agent-team/, 'team')} ${d.source.form ?? ''} ${(d.source.summary ?? '').slice(0, 30)}`
      add(injections, label, text.length)
    }
  }
  for (let i = 0; i < seq.length; i++) {
    const s = seq[i]; if (!['unread_required', 'stale_revision'].includes(s.cls)) continue
    const n = seq[i + 1]
    let next = 'none'
    if (n) {
      if (n.tool === 'team_thread' && n.action === 'read') next = 'read'
      else if (n.tool === s.tool && n.action === s.action) {
        const m = /baseRevision: (\d+)/.exec(s.text); const offered = m ? Number(m[1]) : undefined
        next = `same-write retry (${n.base === offered ? 'with offered token' : 'other token'}) -> ${n.cls}`
      } else next = `${n.tool} ${n.action}`
    }
    add(after, `${s.cls}: ${next}`, 1)
  }
}
const q = (a, p) => { const s = [...a].sort((x, y) => x - y); return s[Math.min(s.length - 1, Math.floor(p * s.length))] }
console.log('files', files)
console.log('\n== tool result chars (n, p50, p90, max, total) ==')
for (const [k, v] of [...sizes].sort((a, b) => b[1].reduce((x, y) => x + y, 0) - a[1].reduce((x, y) => x + y, 0))) if (v.length >= 3) console.log(k.padEnd(48), v.length, q(v, .5), q(v, .9), Math.max(...v), v.reduce((x, y) => x + y, 0))
console.log('\n== injected team user messages (n, p50, p90, max, total) ==')
for (const [k, v] of [...injections].sort((a, b) => b[1].length - a[1].length)) console.log(k.padEnd(60), v.length, q(v, .5), q(v, .9), Math.max(...v), v.reduce((x, y) => x + y, 0))
console.log('\n== next call after a deferred write ==')
for (const [k, v] of [...after].sort((a, b) => b[1].length - a[1].length)) console.log(String(v.length).padStart(5), k)

