import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { isAgentTeamSource } from './context-source.ts'
import type { AgentTeamMemberId, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types.ts'

/**
 * Whether one unread Thread Message is already on its Member's model-visible surface, in full.
 *
 * The write gate refuses writes while unread work exists, but a complete notification or a complete tool result delivers the Message; refusing only costs a round-trip. The probe is narrow because a false positive lets through a write the model was never ready to make: it binds the exact Thread and Message refs, then requires the body itself to be present. Count-only notices, summaries, model-authored text, same text from another Thread, and bodies kept only in `meta` after the content was pruned never match. Reads a live Session only; no ledger state.
 */

/** The notice's own truncation marker, which means the body was cut. */
export const NOTIFICATION_TRUNCATION_MARKER = '[Message body truncated; use team_thread read for the full Message.]'

/** Body budget of one notice before it is cut and marked; the writer and the full-delivery check must agree on it and on the mark. */
export const NOTIFICATION_BODY_MAX_CHARACTERS = 8 * 1024

/** The private `tool/result` meta field that binds a rendered result to the Thread facts it shows. Written by the Team tools only; content still has to carry the body. */
const FACT_SURFACE_META = 'agent-team/thread-facts'

/** One model-visible surface entry that can attest a Thread Message. */
type VisibleTeamSurfaceEntry =
  | { readonly kind: 'notice'; readonly text: string }
  | { readonly kind: 'tool-result'; readonly text: string; readonly surface: RenderedFactSurface }

/** One Message identity a Team tool result claims to have rendered. */
interface RenderedMessageIdentity {
  readonly messageRef: string
  readonly bodyLength: number
}

interface RenderedFactSurface {
  readonly threadRef: string
  readonly messages: readonly RenderedMessageIdentity[]
}

/**
 * The projected text of every Team-authored notice and every Team tool result on this agent's surface, newest first.
 *
 * `surface.nodes` holds SessionSeq values while `snapshotEvents` takes SessionLogOffsets; they line up only through the seq = log.length contiguity contract, so the conversion goes through the validating constructor. The content comes from `deriveEventMessage`, which applies message projections (compaction and pruning); reading the raw event would miss a rewrite that removed the body.
 */
export function visibleTeamSurface(agent: Agent): readonly VisibleTeamSurfaceEntry[] {
  const entries: VisibleTeamSurfaceEntry[] = []
  for (const sequence of agent.session.surface.nodes.toReversed()) {
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event === undefined) continue
    const message = agent.session.deriveEventMessage(event)
    if (message === null) continue
    if (event.type === 'user/message') {
      const source = message.source
      if (!isAgentTeamSource(source)) continue
      if (source.form !== 'notice') continue
      entries.push({ kind: 'notice', text: textOf(message.content) })
      continue
    }
    if (event.type !== 'tool/result') continue
    const surface = renderedFactSurfaceOf((event.data as { readonly meta?: unknown }).meta)
    if (surface === undefined) continue
    entries.push({ kind: 'tool-result', text: textOf(message.content), surface })
  }
  return entries
}

/** The text blocks of one message, in order; a rendered body always lives inside one block. */
function textOf(content: readonly { readonly type: string; readonly text?: string }[]): string {
  return content.flatMap(part => part.type === 'text' && part.text !== undefined ? [part.text] : []).join('\n')
}

/**
 * Whether one unread fact's body is on the surface in full, bound to this Thread and Message.
 *
 * Notification text carries explicit `Thread:` and `Message ref:` lines beside the body. A Team tool result carries the same identity in its private meta, while the body must still be in the projected content; that is what separates a complete result from one whose content a pruner replaced while leaving meta intact.
 */
export function isFactOnSurface(entries: readonly VisibleTeamSurfaceEntry[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
  if (fact.fact.kind !== 'message') return false
  const body = fact.fact.message.body
  if (body === '') return false
  const messageRef = fact.fact.message.messageRef
  return entries.some(entry => entry.kind === 'notice'
    ? noticeAttests(entry.text, threadRef, messageRef, body)
    : toolResultAttests(entry.text, entry.surface, threadRef, messageRef, body))
}

/** Whether one direct-mention block names both refs and then carries the body at its own `Message:` position, uncut. */
function noticeAttests(text: string, threadRef: string, messageRef: string, body: string): boolean {
  const marker = 'Direct Team mention\n'
  for (let start = text.indexOf(marker); start !== -1; start = text.indexOf(marker, start + 1)) {
    const headerEnd = text.indexOf('\nMessage: ', start)
    if (headerEnd === -1) continue
    const header = text.slice(start, headerEnd)
    if (!hasLine(header, 'Thread', threadRef) || !hasLine(header, 'Message ref', messageRef)) continue
    const bodyStart = headerEnd + '\nMessage: '.length
    if (!text.startsWith(body, bodyStart)) continue
    const rest = text.slice(bodyStart + body.length)
    if (rest.startsWith(`\n${NOTIFICATION_TRUNCATION_MARKER}`)) continue
    if (rest !== '' && !rest.startsWith('\n')) continue
    return true
  }
  return false
}

function hasLine(block: string, label: string, value: string): boolean {
  return block.split('\n').includes(`${label}: ${value}`)
}

/** A tool result attests only when its meta names this Thread and Message and the projected content still carries the full body. */
function toolResultAttests(text: string, surface: RenderedFactSurface, threadRef: string, messageRef: string, body: string): boolean {
  if (surface.threadRef !== threadRef) return false
  const identity = surface.messages.find(message => message.messageRef === messageRef)
  if (identity === undefined || identity.bodyLength !== body.length) return false
  return bodyAtLineBoundary(text, body)
}

/** Whether the body is present as a whole rendered segment, not as a prefix of a longer body or a fragment inside one. */
function bodyAtLineBoundary(text: string, body: string): boolean {
  for (let at = text.indexOf(body); at !== -1; at = text.indexOf(body, at + 1)) {
    const before = at === 0 ? '\n' : text[at - 1]!
    const afterIndex = at + body.length
    const after = afterIndex === text.length ? '\n' : text[afterIndex]!
    if ((before === '\n' || before === ' ') && after === '\n') return true
  }
  return false
}

/** Parse and validate one tool result's private fact binding; malformed or foreign meta binds nothing. */
function renderedFactSurfaceOf(meta: unknown): RenderedFactSurface | undefined {
  if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) return undefined
  const record = meta as Record<string, unknown>
  if (record['surface'] !== FACT_SURFACE_META || typeof record['threadRef'] !== 'string' || typeof record['messages'] !== 'string') return undefined
  let parsed: unknown
  try {
    parsed = JSON.parse(record['messages'])
  } catch {
    return undefined
  }
  if (!Array.isArray(parsed)) return undefined
  const messages: RenderedMessageIdentity[] = []
  for (const entry of parsed) {
    if (typeof entry !== 'object' || entry === null) return undefined
    const message = entry as Record<string, unknown>
    if (typeof message['messageRef'] !== 'string' || typeof message['bodyLength'] !== 'number') return undefined
    messages.push({ messageRef: message['messageRef'], bodyLength: message['bodyLength'] })
  }
  return { threadRef: record['threadRef'], messages }
}

export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
  return (memberId: AgentTeamMemberId, fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean => {
    const agent = agentFor(memberId)
    if (agent === undefined) return false
    return isFactOnSurface(visibleTeamSurface(agent), fact, threadRef)
  }
}

