import { afterEach, describe, expect, it, vi } from 'vitest'
import { cleanups, realHarness, ScriptedAdapter, textResponse, toolCallResponse, requestId, waitFor } from './helpers/member-harness.ts'
import type { AgentTeamRequestId, AgentTeamThreadRef } from '../src/types.ts'
vi.setConfig({ testTimeout: 60_000 })

afterEach(async () => { await Promise.all(cleanups.splice(0).map(cleanup => cleanup())) })

/** One real Member and a Thread they follow, with one ordinary Human reply waiting unread. */
async function waitingThread(body: string) {
  const adapter = new ScriptedAdapter()
  const test = await realHarness(adapter)
  const member = await test.ctx.agentTeam.addMember({ requestId: requestId('member') as AgentTeamRequestId, workspaceId: test.workspaceId,
    handle: 'builder', description: 'Builds changes', presetId: 'team-member', projectRefs: [project.project.projectRef] })
  const agent = test.ctx.agents.get(member.status.member.sessionId)!
  const started = await test.ctx.agentTeam.startThread({ kind: 'discussion', requestId: requestId('thread') as AgentTeamRequestId,
    workspaceId: test.workspaceId, projectRef: project.project.projectRef, body: 'Release plan' })
  if (started.kind !== 'committed') throw new Error('setup failed')
  await test.ctx.agentTeam.changeAttentionForAgent(agent, { requestId: requestId('follow') as AgentTeamRequestId,
    workspaceId: test.workspaceId, threadRef: started.thread.threadRef, action: 'follow' })
  const update = await test.ctx.agentTeam.reply({ requestId: requestId('update') as AgentTeamRequestId, workspaceId: test.workspaceId,
    threadRef: started.thread.threadRef, body, baseRevision: started.thread.revision })
  if (update.kind !== 'committed') throw new Error('setup failed')
  return { ...test, adapter, agent, memberId: member.status.member.memberId, threadRef: started.thread.threadRef as AgentTeamThreadRef,
    oldRevision: started.thread.revision, currentRevision: update.thread.revision }
}

function toolResultTexts(agent: { readonly session: { ownEvents: () => readonly { type: string; data: never }[] } }): string[] {
  return agent.session.ownEvents().filter(event => event.type === 'tool/result').map(event => {
    const content = (event.data as unknown as { message: { content: readonly { type: string; text?: string }[] } }).message.content
    return content.flatMap(part => part.type === 'text' && part.text !== undefined ? [part.text] : []).join('\n')
  })
}

describe('a complete rejection lets the writer reconsider without re-reading', () => {
  it('shows the whole change and current token, then commits the modified reply without a read', async () => {
    const change = 'Windows install failed — hold the release until it is reproduced.'
    const { ctx, adapter, agent, memberId, threadRef, oldRevision, currentRevision } = await waitingThread(change)

    adapter.enqueue(toolCallResponse('old-token', 'team_message', { action: 'reply', threadRef, body: 'Publish it', baseRevision: oldRevision }))
    adapter.enqueue(toolCallResponse('new-token', 'team_message', { action: 'reply', threadRef,
      body: 'Paused the release; reproducing the Windows install failure.', baseRevision: currentRevision }))
    adapter.enqueue(textResponse('Paused and investigating.'))

    await waitFor(() => adapter.requests.length === 3 ? true : undefined)
    await agent.whenIdle()

    const results = toolResultTexts(agent)
    expect(results).toHaveLength(2)
    // 1. The old token is refused, but nothing is hidden: the complete change
    // and the current revision arrive in the same tool result.
    expect(results[0]).toContain('Not committed — unread_required.')
    expect(results[0]).toContain(change)
    expect(results[0]).toContain(`Next write — baseRevision: ${currentRevision}`)
    // 2. The next model step sees that result as ordinary context.
    expect(JSON.stringify(adapter.requests[1]!.messages)).toContain(change)
    expect(JSON.stringify(adapter.requests[1]!.messages)).toContain('Next write — baseRevision')
    // 3. The modified reply commits even though the change was never read and
    // remains unread: the exemption is the surface, not a durable read.
    expect(results[1]).toContain('Committed — reply added.')
    expect(results[1]).not.toContain('unread_required')

    const unread = ctx.agentTeam['ledger']!.notificationFacts(memberId).flatMap(entry => entry.facts)
    expect(unread.some(entry => entry.fact.kind === 'message' && entry.fact.message.body === change)).toBe(true)
  })
})

describe('an incomplete rejection never implies a direct write', () => {
  it('bounds an oversized change and keeps the next write refused until the Thread is read', async () => {
    const change = 'Windows install failed. '.repeat(500)
    const { ctx, adapter, agent, memberId, threadRef, oldRevision, currentRevision } = await waitingThread(change)

    adapter.enqueue(toolCallResponse('old-token', 'team_message', { action: 'reply', threadRef, body: 'Publish it', baseRevision: oldRevision }))
    adapter.enqueue(toolCallResponse('current-token', 'team_message', { action: 'reply', threadRef,
      body: 'Publish after the failure', baseRevision: currentRevision }))
    adapter.enqueue(textResponse('Reading the Thread instead.'))

    await waitFor(() => adapter.requests.length === 3 ? true : undefined)
    await agent.whenIdle()

    const results = toolResultTexts(agent)
    expect(results[0]).toContain('Not committed — unread_required.')
    expect(results[0]).toContain('Only 1 of 1 new fact(s)')
    expect(results[0]).toContain('the full change is not shown')
    expect(results[0]).not.toContain('Next write — baseRevision')
    expect(results[0]).toContain('No write token is provided')
    // The current token alone does not pass: the body is still not fully on the
    // surface, so the gate refuses again.
    expect(results[1]).toContain('Not committed — unread_required.')

    const unread = ctx.agentTeam['ledger']!.notificationFacts(memberId).flatMap(entry => entry.facts)
    // Two refusals wrote no read state: the gated change is still durable unread.
    expect(unread.some(entry => entry.fact.kind === 'message')).toBe(true)
  })
})

import { describe, expect, it } from 'vitest'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { AGENT_TEAM_PLUGIN_ID } from '../src/context-source.ts'
import { isFactOnSurface, NOTIFICATION_TRUNCATION_MARKER, visibleTeamSurface } from '../src/surface-visibility.ts'
import type { AgentTeamThreadReadFact, AgentTeamThreadRef } from '../src/types.ts'

interface FakeEvent {
  readonly type: 'user/message' | 'tool/result' | 'assistant/message'
  readonly data: Record<string, unknown>
}

const THREAD = 'thread:alpha' as AgentTeamThreadRef
const OTHER_THREAD = 'thread:beta' as AgentTeamThreadRef

function fakeAgent(events: readonly FakeEvent[]): Agent {
  const nodes = events.map((_, index) => index)
  return {
    session: {
      surface: { nodes },
      snapshotEvents: (from: unknown, to: unknown) => {
        const start = from as number
        const end = to as number
        return events.slice(start, end)
      },
      deriveEventMessage: (event: FakeEvent) => {
        if (event.type === 'user/message') return event.data
        if (event.type === 'tool/result') return event.data['message']
        if (event.type === 'assistant/message') return event.data['message']
        return null
      },
    },
  } as never
}

function noticeEvent(text: string, form = 'notice'): FakeEvent {
  return { type: 'user/message', data: { role: 'user', source: { kind: AGENT_TEAM_PLUGIN_ID, form }, content: [{ type: 'text', text }] } }
}

function toolEvent(text: string, meta: unknown): FakeEvent {
  return { type: 'tool/result', data: { message: { role: 'tool', source: { kind: 'tool', callId: 'call:1' }, content: [{ type: 'text', text }] }, meta } }
}

function factSurfaceMeta(threadRef: string, messages: readonly { readonly messageRef: string; readonly bodyLength: number }[]): Record<string, string> {
  return { surface: 'agent-team/thread-facts', threadRef, messages: JSON.stringify(messages) }
}

function factOf(body: string, messageRef = 'message:a', sequence = 12): AgentTeamThreadReadFact {
  return { fact: { kind: 'message', sequence, message: { messageRef, body } as never, mentions: [], occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: true } as never
}

function noticeOf(body: string, threadRef = THREAD, messageRef = 'message:a'): string {
  return ['Direct Team mention', 'Occurred at: 2026-10-14T00:00:00.000Z', 'From: reviewer', 'Project: project:alpha',
    `Thread: ${threadRef}`, `Message ref: ${messageRef}`, `Message: ${body}`].join('\n')
}

describe('the surface probe reads only this plugin own projected messages', () => {
  it('collects Team notices and Team tool results, ignoring other producers and forms', () => {
    const agent = fakeAgent([
      noticeEvent('Team notice body'),
      noticeEvent('relay body', 'relay'),
      { type: 'user/message', data: { role: 'user', source: { kind: 'plugin:someone-else' }, content: [{ type: 'text', text: 'foreign' }] } },
      toolEvent('tool body', factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 9 }])),
      toolEvent('foreign tool body', { anything: true }),
    ])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['tool body', 'Team notice body'])
  })

  it('reads the projected message, not the raw event content', () => {
    // A projection can rewrite the content a pruner owns while the raw event
    // still appears in the log.
    const event = { type: 'tool/result', data: { message: { role: 'tool', content: [{ type: 'text', text: '[pruned]' }] }, meta: factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 4 }]) } } as FakeEvent
    const agent = fakeAgent([event])
    expect(visibleTeamSurface(agent)[0]?.text).toBe('[pruned]')
    expect(isFactOnSurface(visibleTeamSurface(agent), factOf('body'), THREAD)).toBe(false)
  })

  it('ignores non-message events and non-text content parts', () => {
    const agent = fakeAgent([
      { type: 'tool/result', data: { message: { role: 'tool', content: [{ type: 'image' }] }, meta: factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 4 }]) } },
      noticeEvent(''),
    ])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['', ''])
  })

  it('reads newest first, so a later notice is examined before an older one', () => {
    const agent = fakeAgent([noticeEvent('older'), noticeEvent('newer')])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['newer', 'older'])
  })
})

describe('the probe answers true only for a body bound to this Thread and Message, seen in full', () => {
  it('matches a direct mention notice that names the Thread and Message and carries the body verbatim', () => {
    expect(isFactOnSurface(visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))])), factOf('please review this'), THREAD)).toBe(true)
  })

  it('never matches the same short body under another Thread or Message ref', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('ok', OTHER_THREAD, 'message:b'))]))
    expect(isFactOnSurface(entries, factOf('ok'), THREAD)).toBe(false)
    expect(isFactOnSurface(entries, factOf('ok', 'message:a'), OTHER_THREAD)).toBe(false)
  })

  it('never matches a plain body without the identity lines', () => {
    const text = 'Message: please review this'
    expect(isFactOnSurface([{ kind: 'notice', text }], factOf('please review this'), THREAD)).toBe(false)
  })

  it('never matches a truncation prefix or a body cut after it', () => {
    const long = 'y'.repeat(12 * 1024)
    const truncated = `Direct Team mention\nThread: ${THREAD}\nMessage ref: message:a\nMessage: ${long.slice(0, 8 * 1024)}\n${NOTIFICATION_TRUNCATION_MARKER}`
    expect(isFactOnSurface([{ kind: 'notice', text: truncated }], factOf(long), THREAD)).toBe(false)
  })

  it('never matches a body that is only a prefix of the rendered body', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))]))
    expect(isFactOnSurface(entries, factOf('please'), THREAD)).toBe(false)
  })

  it('never matches a body that differs in any character', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))]))
    expect(isFactOnSurface(entries, factOf('please review this '), THREAD)).toBe(false)
    expect(isFactOnSurface(entries, factOf('please review THIS'), THREAD)).toBe(false)
  })

  it('never matches an empty body, an activity fact, or an empty surface', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('ok'))]))
    expect(isFactOnSurface(entries, factOf(''), THREAD)).toBe(false)
    const activity = { fact: { kind: 'activity', sequence: 12, activity: { kind: 'claim-changed' }, occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: false } as never
    expect(isFactOnSurface(entries, activity, THREAD)).toBe(false)
    expect(isFactOnSurface([], factOf('ok'), THREAD)).toBe(false)
  })
})

describe('a tool result attests only when meta names the fact and the projected content keeps the body', () => {
  it('matches a tool result whose meta binds the Thread and Message and whose content carries the body', () => {
    const text = ['Facts', '12 [reviewer] please review this', '13 [reviewer] another change'].join('\n')
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [
      { messageRef: 'message:a', bodyLength: 'please review this'.length },
      { messageRef: 'message:b', bodyLength: 'another change'.length },
    ]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(true)
  })

  it('does not accept retained meta when the projected content no longer carries the body', () => {
    const entries = visibleTeamSurface(fakeAgent([toolEvent('[tool result pruned]', factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 'please review this'.length }]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })

  it('does not accept a matching body without the fact identity in meta', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([
      toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:other', bodyLength: 'please review this'.length }])),
      toolEvent(text, factSurfaceMeta(OTHER_THREAD, [{ messageRef: 'message:a', bodyLength: 'please review this'.length }])),
      toolEvent(text, { surface: 'agent-team/thread-facts', messages: '[]' }),
    ]))
    expect(entries).toHaveLength(2)
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })

  it('does not accept a body that is only a prefix of a longer rendered body', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 'please'.length }]))]))
    expect(isFactOnSurface(entries, factOf('please'), THREAD)).toBe(false)
  })

  it('does not accept a body length that does not match the fact', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 1 }]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })
})

import type { Context } from '@deepseek-ai/cordis'
import AgentTeam, { AGENT_TEAM_HUMAN_MEMBER_ID, AgentTeamDmDeliveryError, markAgentTeamPreset } from '@contexera/dsh-agent-team/host'
import { formatTeamTimestamp } from '@contexera/dsh-agent-team/time-format'
import { projectRefOf, service, workspaceOf, workspaceParam } from './host-access.ts'
import { recoveryFor } from '@contexera/dsh-agent-team/recovery-hints'
import type {
  AgentTeamAttentionSource,
  AgentTeamClaimRef,
  AgentTeamInboxReminder,
  AgentTeamMemberId,
  AgentTeamRequestId,
  AgentTeamMessageRef,
  AgentTeamProjectRef,
  AgentTeamTaskRef,
  AgentTeamTaskBoardItem,
  AgentTeamThreadFact,
  AgentTeamThreadRef,
  AgentTeamThreadTaskCard,
} from '@contexera/dsh-agent-team/types'
import { defineTool } from '@deepseek-ai/dsh-tools'
import { MAIN_ENTRY_SCHEMA, MAIN_STANDING_SCHEMA, mainEntryLine, mainEntryView, standingView } from './main-stream.ts'
import type { MainEntryView } from './main-stream.ts'

export const name = 'wowyuarm-agent-team-tools'
export const inject = ['tools']

/** One shared bound for every bounded anchor subject a render shows. */
const SUBJECT_BOUND = 80

/** Model-facing view of one structured Thread activity fact, shared by read and history. */
interface ActivityFactView {
  readonly sequence: number
  readonly kind: 'activity'
  readonly activity: string
  readonly actor: string
  readonly taskRef: string
  readonly occurredAt?: string
  readonly claimRef?: string
  readonly claimRefs?: string[]
  readonly completedClaimRefs?: string[]
  readonly acceptedClaimRefs?: string[]
  readonly releasedClaimRefs?: string[]
  readonly unread?: boolean
  readonly direct?: boolean
}

/** Model-facing view of one message fact. */
interface MessageFactView {
  readonly sequence: number
  readonly kind: 'message'
  readonly messageRef: string
  readonly body: string
  readonly sender: string
  readonly occurredAt?: string
  readonly mentions: string[]
  readonly unread?: boolean
  readonly direct?: boolean
  /** The Message this one answers, when it is a reply. */
  readonly replyToMessageRef?: string
  /** The same target resolved for reading: who wrote it and its first line. Separate from `replyToMessageRef` (the ref you pass back to `team_message.reply`) because one field carrying both meanings would be wrong half the time. */
  readonly replyTo?: ReplyContextView
}

/** One Message's answer target, as the Agent surfaces print it. */
interface ReplyContextView {
  readonly sender: string
  readonly excerpt: string
}

type FactView = MessageFactView | ActivityFactView

/** Model-facing view of one Claim, shared by the read collision surface and claim outcomes. */
interface ClaimView {
  readonly claimRef: string
  readonly direction: string
  readonly state: string
  readonly owner: string
}

function claimView(claim: { readonly claimRef: AgentTeamClaimRef; readonly direction: string; readonly state: string; readonly owner: string }): ClaimView {
  return { claimRef: claim.claimRef, direction: claim.direction, state: claim.state, owner: claim.owner }
}

function activityFactView(
  sequence: number,
  activity: { readonly kind: string; readonly actor: string; readonly taskRef: AgentTeamTaskRef
    readonly claimRef?: AgentTeamClaimRef | undefined; readonly claimRefs?: readonly AgentTeamClaimRef[] | undefined
    readonly completedClaimRefs?: readonly AgentTeamClaimRef[] | undefined; readonly acceptedClaimRefs?: readonly AgentTeamClaimRef[] | undefined
    readonly releasedClaimRefs?: readonly AgentTeamClaimRef[] | undefined },
  markers?: { readonly unread: boolean; readonly direct: boolean } | undefined,
  occurredAt?: string | undefined,
): ActivityFactView {
  return {
    sequence, kind: 'activity', activity: activity.kind, actor: activity.actor, taskRef: activity.taskRef,
    ...(occurredAt === undefined ? {} : { occurredAt }),
    ...(activity.claimRef === undefined ? {} : { claimRef: activity.claimRef }),
    ...(activity.claimRefs === undefined || activity.claimRefs.length === 0 ? {} : { claimRefs: [...activity.claimRefs] }),
    ...(activity.completedClaimRefs === undefined || activity.completedClaimRefs.length === 0 ? {} : { completedClaimRefs: [...activity.completedClaimRefs] }),
    ...(activity.acceptedClaimRefs === undefined || activity.acceptedClaimRefs.length === 0 ? {} : { acceptedClaimRefs: [...activity.acceptedClaimRefs] }),
    ...(activity.releasedClaimRefs === undefined || activity.releasedClaimRefs.length === 0 ? {} : { releasedClaimRefs: [...activity.releasedClaimRefs] }),
    ...(markers === undefined ? {} : { unread: markers.unread, direct: markers.direct }),
  }
}

/** The one deterministic bounded subject for directory rows and Thread orientation: whitespace collapses to one line, then one bounded cut with an explicit truncation mark, so surfaces never disagree about what a Thread is about. */
function boundedSubject(body: string): string {
  const collapsed = body.replaceAll(/\s+/gu, ' ').trim()
  return collapsed.length <= SUBJECT_BOUND ? collapsed : `${collapsed.slice(0, SUBJECT_BOUND - 1)}…`
}

/** Unread/direct markers sit on the fact line itself; a fact carrying neither renders neither. */
function factMarkers(fact: FactView): string {
  if (fact.unread === undefined) return ''
  if (fact.direct === true) return ' [direct]'
  if (fact.unread === true) return ' [unread]'
  return ''
}

/** Render one structured activity fact as a self-describing decision-surface line. */
function activityLine(fact: ActivityFactView): string {
  const segments = [`${fact.sequence}`, fact.actor, fact.activity]
  segments.push(`Task ${fact.taskRef}`)
  if (fact.claimRef !== undefined) segments.push(`Claim ${fact.claimRef}`)
  if (fact.claimRefs !== undefined) segments.push(`claims released ${fact.claimRefs.join(', ')}`)
  if (fact.completedClaimRefs !== undefined) segments.push(`completed claims ${fact.completedClaimRefs.join(', ')}`)
  if (fact.acceptedClaimRefs !== undefined) segments.push(`accepted claims ${fact.acceptedClaimRefs.join(', ')}`)
  if (fact.releasedClaimRefs !== undefined) segments.push(`released claims ${fact.releasedClaimRefs.join(', ')}`)
  return segments.join(' ')
}

/** The one hand-off line a fully drained read or a committed public mutation may render. */
function nextWriteLine(revision: number): string {
  return `Next write — baseRevision: ${revision} (copy exactly; never derive or cite).`
}

/** Task standing inline on a Thread identity line; absent on taskless Threads. Accountability rides along whenever the result carries it, because who is responsible for the Task changes what the reader may do next. */
function taskStanding(value: { taskRef?: string; status?: string; resolution?: string; taskNumber?: number; accountable?: string }): string {
  if (value.taskRef === undefined) return ''
  return `${value.taskRef}${value.taskNumber === undefined ? '' : ` (#${value.taskNumber})`}${value.status === undefined ? '' : `, ${value.status}${value.resolution === undefined ? '' : `/${value.resolution}`}`}${value.accountable === undefined ? '' : ` · accountable ${value.accountable}`}`
}

/** One Task a discussion spawned, as the card its Thread renders at the creation point: current state, never a fact, never unread. */
interface TaskCardView {
  readonly taskRef: string
  readonly taskNumber: number
  readonly threadRef: string
  readonly sequence: number
  readonly occurredAt: string
  readonly subject: string
  readonly status: string
  readonly resolution: string
  readonly accountable: string
}

const TASK_CARD_SCHEMA = {
  type: 'object', additionalProperties: false, properties: {
    taskRef: { type: 'string', required: true }, taskNumber: { type: 'number', required: true }, threadRef: { type: 'string', required: true },
    sequence: { type: 'number', required: true }, occurredAt: { type: 'string', required: true }, subject: { type: 'string', required: true },
    status: { type: 'string', required: true }, resolution: { type: 'string', required: true }, accountable: { type: 'string', required: true },
  },
} as const

function taskCardView(entry: AgentTeamThreadTaskCard): TaskCardView {
  // Flattened from the shared card: the model-facing view keeps its own stable field set, so the Host projection can
  // grow without changing what a tool result declares.
  const card = entry.card
  return { taskRef: card.task.taskRef, taskNumber: card.task.taskNumber, threadRef: card.threadRef, sequence: entry.sequence,
    occurredAt: card.anchor.occurredAt, subject: card.anchor.preview, status: card.task.status, resolution: card.task.resolution,
    accountable: card.task.accountable }
}

import { Context } from '@deepseek-ai/cordis'
import Storage from '@deepseek-ai/dsh-storage'
import SessionProjectionRegistry from '@deepseek-ai/dsh-session-projection'
import { DomainFacility } from '@deepseek-ai/dsh-storage-domain'
import { WorkspaceId } from '@deepseek-ai/dsh-workspace'
import { MemoryMediaPool, MemoryStorageBackend } from './memory-backend.ts'
import { provideQuietTokenMeter } from './team-host-fixture.ts'
import AgentTeam from '../../src/index.ts'

export interface TeamHarness {
  readonly ctx: Context
  readonly fiber: Awaited<ReturnType<Context['plugin']>>
  readonly facility: DomainFacility
  readonly workspaceId: WorkspaceId
}

export async function harness(): Promise<TeamHarness> {
  const pool = new MemoryMediaPool()
  const ctx = new Context()
  await ctx.plugin(Storage)
  ctx.storage.backend.register('memory', new MemoryStorageBackend(pool))
  const facility = new DomainFacility(ctx, { backend: 'memory', routes: {} })
  ctx.storage.mount('domain', facility)
  ctx.provide('storageDomain', facility)
  const workspaceId = WorkspaceId('workspace:alpha')
  ctx.provide('workspaceRegistry', {
    get: (id: WorkspaceId) => id === workspaceId ? { id, path: process.cwd(), attachSession: async () => {}, archiveSession: async () => {} } : undefined,
    list: () => [{ id: workspaceId, path: process.cwd() }],
  })
  ctx.provide('agents', { create: async () => { throw new Error('unused') }, resume: async () => { throw new Error('unused') } })
  ctx.provide('agentDefaultModel', { currentSelection: () => ({ provider: 'mock', model: 'mock' }) })
  ctx.provide('agentPresets', { mount: async () => { throw new Error('unused') } })
  ctx.provide('tools', { schemas: () => [] })
  ctx.provide('sessionPersistence', { list: async () => [] })
  // The Host reads context pressure through the token meter at its wake
  // boundary; a zero-usage meter keeps pressure out of every surface assertion.
  provideQuietTokenMeter(ctx)
  await ctx.plugin(SessionProjectionRegistry)
  const fiber = await ctx.plugin(AgentTeam)
  return { ctx, fiber, facility, workspaceId }
}

