/** The private `tool/result` meta marker that binds a rendered result to its Thread facts. The Host probe reads it together with the projected content; meta alone never attests. */
const FACT_SURFACE_META = 'agent-team/thread-facts'

/** At most this many facts ride in one rejection; the rest are named as not shown. */
const REJECTION_FACT_LIMIT = 20

/** One rejection body beyond this is cut and marked, so an oversized change is never implied to be complete. */
const REJECTION_BODY_MAX_CHARACTERS = 8 * 1024

/** The whole rejection body budget, so a batch of long messages stays bounded. */
const REJECTION_TOTAL_BODY_MAX_CHARACTERS = 16 * 1024

const REJECTION_BODY_TRUNCATION_MARKER = '[Message body truncated; the full change is not shown here. Read the Thread.]'

interface RenderedMessageIdentity {
  readonly messageRef: string
  readonly bodyLength: number
}

/** The facts a rejection can show in full, and whether that is every fact it has to show. */
function rejectionFactSelection(facts: readonly RejectedFact[]): { readonly shown: readonly RejectedFact[]; readonly complete: boolean } {
  const shown: RejectedFact[] = []
  let bodyCharacters = 0
  let complete = true
  for (const fact of facts) {
    const body = fact.kind === 'message' ? fact.body ?? '' : ''
    if (shown.length >= REJECTION_FACT_LIMIT || bodyCharacters + Math.min(body.length, REJECTION_BODY_MAX_CHARACTERS) > REJECTION_TOTAL_BODY_MAX_CHARACTERS) {
      complete = false
      break
    }
    if (body.length > REJECTION_BODY_MAX_CHARACTERS) {
      shown.push({ ...fact, body: `${body.slice(0, REJECTION_BODY_MAX_CHARACTERS)}\n${REJECTION_BODY_TRUNCATION_MARKER}` })
      bodyCharacters += REJECTION_BODY_MAX_CHARACTERS
      complete = false
      continue
    }
    shown.push(fact)
    bodyCharacters += body.length
  }
  return { shown, complete: complete && shown.length === facts.length }
}

/** Identity of the Message bodies a tool result renders. Bodies stay in the content; meta carries only refs and lengths, so a pruned content cannot pass on meta alone. */
function renderedFactSurface(threadRef: string | undefined, identities: readonly RenderedMessageIdentity[]): Record<string, string> {
  return {
    surface: FACT_SURFACE_META,
    ...(threadRef === undefined ? {} : { threadRef }),
    messages: JSON.stringify(identities),
  }
}

/** The Message identities one facts array can bind: only message facts that carry both a ref and a body. */
function messageIdentities(facts: readonly RejectedFact[]): RenderedMessageIdentity[] {
  return facts.flatMap(fact => fact.kind === 'message' && fact.messageRef !== undefined && fact.body !== undefined
    ? [{ messageRef: fact.messageRef, bodyLength: fact.body.length }]
    : [])
}

/** The typed-rejection renderer shared by team_message and team_task: outcome, action-local recovery facts, the facts that gated the write, and either the next write token (only when every fact is shown in full) or the read route (when the batch or a body was cut). */
function rejectionLines(
  value: { readonly kind: string; readonly threadRef?: string; readonly taskRef?: string; readonly unreadCount?: number; readonly directCount?: number; readonly memberIds?: string[]; readonly revision?: number; readonly staleTokenKind?: 'unknown' | 'unrecognized'; readonly facts?: readonly RejectedFact[] },
): string[] {
  const identity = [
    value.threadRef === undefined ? '' : value.threadRef,
    value.taskRef === undefined ? '' : value.taskRef,
  ].filter(part => part !== '').join(' · ')
  if (value.kind === 'unread_required') {
    const facts = value.facts ?? []
    const selection = rejectionFactSelection(facts)
    const complete = selection.complete && facts.length === (value.unreadCount ?? facts.length)
    return [
      'Not committed — unread_required.',
      `${identity}${identity === '' ? '' : ' · '}${value.unreadCount ?? 0} unread, ${value.directCount ?? 0} direct`,
      ...rejectedFactLines(facts, selection),
      recoveryFor('unread_required').sentence({ threadRef: value.threadRef, taskRef: value.taskRef }),
      ...(complete && value.revision !== undefined ? [nextWriteLine(value.revision)] : []),
      ...(complete ? [] : ['No write token is provided because the changes above are not all shown; read the Thread first.']),
    ]
  }
  if (value.kind === 'stale_revision') {
    const facts = value.facts ?? []
    const selection = rejectionFactSelection(facts)
        // A token this Thread never reached is not a race (it was copied from another Thread or invented), so the way out and the headline say that instead of claiming the Thread changed and then saying nothing was inserted.
    const unrecognized = value.staleTokenKind === 'unrecognized'
    const complete = selection.complete
    return [
      ...(unrecognized ? ['Not committed — that write token was never a revision this Thread reached (stale_revision).']
        : ['Not committed — the Thread changed after your last read (stale_revision).']),
      identity,
      ...(unrecognized ? [] : rejectedFactLines(facts, selection)),
      recoveryFor(unrecognized ? 'stale_revision_token_unrecognized' : 'stale_revision')
        .sentence({ threadRef: value.threadRef, taskRef: value.taskRef }),
      ...(complete && value.revision !== undefined ? [nextWriteLine(value.revision)] : []),
      ...(complete ? [] : ['No write token is provided because the changes above are not all shown; read the Thread first.']),
    ]
  }
  return [
    `Not committed — ${value.kind}.`,
    identity === '' ? 'No message was added.' : `${identity} — no message was added.`,
  ]
}

/** The facts a rejection carries, rendered by the same `factLine` as a Thread read. Nothing to show stays silent, and the count states the span so a truncated batch never reads as the whole increment. */
function rejectedFactLines(facts: readonly RejectedFact[], selection: { readonly shown: readonly RejectedFact[]; readonly complete: boolean }): string[] {
  if (facts.length === 0) return []
  const header = selection.complete
    ? `${facts.length} new fact(s) since your last write, shown in full:`
    : `Only ${selection.shown.length} of ${facts.length} new fact(s) since your last write are shown here; the rest are not included:`
  return ['', header, ...selection.shown.map(fact => factLine(fact as FactView))]
}

