import { describe, expect, it } from 'vitest'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { AGENT_TEAM_PLUGIN_ID } from '../src/context-source.ts'
import { isFactOnSurface, NOTIFICATION_TRUNCATION_MARKER, visibleTeamSurface } from '../src/surface-visibility.ts'
import type { AgentTeamThreadReadFact, AgentTeamThreadRef } from '../src/types.ts'

interface FakeEvent {
  readonly type: 'user/message' | 'tool/result' | 'assistant/message'
  readonly data: Record<string, unknown>
}

const THREAD = 'thread:alpha' as AgentTeamThreadRef
const OTHER_THREAD = 'thread:beta' as AgentTeamThreadRef

function fakeAgent(events: readonly FakeEvent[]): Agent {
  const nodes = events.map((_, index) => index)
  return {
    session: {
      surface: { nodes },
      snapshotEvents: (from: unknown, to: unknown) => {
        const start = from as number
        const end = to as number
        return events.slice(start, end)
      },
      deriveEventMessage: (event: FakeEvent) => {
        if (event.type === 'user/message') return event.data
        if (event.type === 'tool/result') return event.data['message']
        if (event.type === 'assistant/message') return event.data['message']
        return null
      },
    },
  } as never
}

function noticeEvent(text: string, form = 'notice'): FakeEvent {
  return { type: 'user/message', data: { role: 'user', source: { kind: AGENT_TEAM_PLUGIN_ID, form }, content: [{ type: 'text', text }] } }
}

function toolEvent(text: string, meta: unknown): FakeEvent {
  return { type: 'tool/result', data: { message: { role: 'tool', source: { kind: 'tool', callId: 'call:1' }, content: [{ type: 'text', text }] }, meta } }
}

function factSurfaceMeta(threadRef: string, messages: readonly { readonly messageRef: string; readonly bodyLength: number }[]): Record<string, string> {
  return { surface: 'agent-team/thread-facts', threadRef, messages: JSON.stringify(messages) }
}

function factOf(body: string, messageRef = 'message:a', sequence = 12): AgentTeamThreadReadFact {
  return { fact: { kind: 'message', sequence, message: { messageRef, body } as never, mentions: [], occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: true } as never
}

function noticeOf(body: string, threadRef = THREAD, messageRef = 'message:a'): string {
  return ['Direct Team mention', 'Occurred at: 2026-10-14T00:00:00.000Z', 'From: reviewer', 'Project: project:alpha',
    `Thread: ${threadRef}`, `Message ref: ${messageRef}`, `Message: ${body}`].join('\n')
}

describe('the surface probe reads only this plugin own projected messages', () => {
  it('collects Team notices and Team tool results, ignoring other producers and forms', () => {
    const agent = fakeAgent([
      noticeEvent('Team notice body'),
      noticeEvent('relay body', 'relay'),
      { type: 'user/message', data: { role: 'user', source: { kind: 'plugin:someone-else' }, content: [{ type: 'text', text: 'foreign' }] } },
      toolEvent('tool body', factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 9 }])),
      toolEvent('foreign tool body', { anything: true }),
    ])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['tool body', 'Team notice body'])
  })

  it('reads the projected message, not the raw event content', () => {
    // A projection can rewrite the content a pruner owns while the raw event
    // still appears in the log.
    const event = { type: 'tool/result', data: { message: { role: 'tool', content: [{ type: 'text', text: '[pruned]' }] }, meta: factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 4 }]) } } as FakeEvent
    const agent = fakeAgent([event])
    expect(visibleTeamSurface(agent)[0]?.text).toBe('[pruned]')
    expect(isFactOnSurface(visibleTeamSurface(agent), factOf('body'), THREAD)).toBe(false)
  })

  it('ignores non-message events and non-text content parts', () => {
    const agent = fakeAgent([
      { type: 'tool/result', data: { message: { role: 'tool', content: [{ type: 'image' }] }, meta: factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 4 }]) } },
      noticeEvent(''),
    ])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['', ''])
  })

  it('reads newest first, so a later notice is examined before an older one', () => {
    const agent = fakeAgent([noticeEvent('older'), noticeEvent('newer')])
    expect(visibleTeamSurface(agent).map(entry => entry.text)).toEqual(['newer', 'older'])
  })
})

describe('the probe answers true only for a body bound to this Thread and Message, seen in full', () => {
  it('matches a direct mention notice that names the Thread and Message and carries the body verbatim', () => {
    expect(isFactOnSurface(visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))])), factOf('please review this'), THREAD)).toBe(true)
  })

  it('never matches the same short body under another Thread or Message ref', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('ok', OTHER_THREAD, 'message:b'))]))
    expect(isFactOnSurface(entries, factOf('ok'), THREAD)).toBe(false)
    expect(isFactOnSurface(entries, factOf('ok', 'message:a'), OTHER_THREAD)).toBe(false)
  })

  it('never matches a plain body without the identity lines', () => {
    const text = 'Message: please review this'
    expect(isFactOnSurface([{ kind: 'notice', text }], factOf('please review this'), THREAD)).toBe(false)
  })

  it('never matches a truncation prefix or a body cut after it', () => {
    const long = 'y'.repeat(12 * 1024)
    const truncated = `Direct Team mention\nThread: ${THREAD}\nMessage ref: message:a\nMessage: ${long.slice(0, 8 * 1024)}\n${NOTIFICATION_TRUNCATION_MARKER}`
    expect(isFactOnSurface([{ kind: 'notice', text: truncated }], factOf(long), THREAD)).toBe(false)
  })

  it('never matches a body that is only a prefix of the rendered body', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))]))
    expect(isFactOnSurface(entries, factOf('please'), THREAD)).toBe(false)
  })

  it('never matches a body that differs in any character', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('please review this'))]))
    expect(isFactOnSurface(entries, factOf('please review this '), THREAD)).toBe(false)
    expect(isFactOnSurface(entries, factOf('please review THIS'), THREAD)).toBe(false)
  })

  it('never matches an empty body, an activity fact, or an empty surface', () => {
    const entries = visibleTeamSurface(fakeAgent([noticeEvent(noticeOf('ok'))]))
    expect(isFactOnSurface(entries, factOf(''), THREAD)).toBe(false)
    const activity = { fact: { kind: 'activity', sequence: 12, activity: { kind: 'claim-changed' }, occurredAt: '2026-10-14T00:00:00.000Z' }, unread: true, direct: false } as never
    expect(isFactOnSurface(entries, activity, THREAD)).toBe(false)
    expect(isFactOnSurface([], factOf('ok'), THREAD)).toBe(false)
  })
})

describe('a tool result attests only when meta names the fact and the projected content keeps the body', () => {
  it('matches a tool result whose meta binds the Thread and Message and whose content carries the body', () => {
    const text = ['Facts', '12 [reviewer] please review this', '13 [reviewer] another change'].join('\n')
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [
      { messageRef: 'message:a', bodyLength: 'please review this'.length },
      { messageRef: 'message:b', bodyLength: 'another change'.length },
    ]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(true)
  })

  it('does not accept retained meta when the projected content no longer carries the body', () => {
    const entries = visibleTeamSurface(fakeAgent([toolEvent('[tool result pruned]', factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 'please review this'.length }]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })

  it('does not accept a matching body without the fact identity in meta', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([
      toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:other', bodyLength: 'please review this'.length }])),
      toolEvent(text, factSurfaceMeta(OTHER_THREAD, [{ messageRef: 'message:a', bodyLength: 'please review this'.length }])),
      toolEvent(text, { surface: 'agent-team/thread-facts', messages: '[]' }),
    ]))
    expect(entries).toHaveLength(2)
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })

  it('does not accept a body that is only a prefix of a longer rendered body', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 'please'.length }]))]))
    expect(isFactOnSurface(entries, factOf('please'), THREAD)).toBe(false)
  })

  it('does not accept a body length that does not match the fact', () => {
    const text = '12 [reviewer] please review this'
    const entries = visibleTeamSurface(fakeAgent([toolEvent(text, factSurfaceMeta(THREAD, [{ messageRef: 'message:a', bodyLength: 1 }]))]))
    expect(isFactOnSurface(entries, factOf('please review this'), THREAD)).toBe(false)
  })
})

