/**
 * Registry of every model-facing recovery line the Team renders: one entry per situation, built from the values the rejection holds so the line names the refused value. It lives in the Host because both tools and the ledger reject, and tools import the Host, never the reverse. `assertRecoveryCoverage` refuses entries no situation reaches; `forbidHandWrittenRecovery` scans model-facing sources for route sentences outside the registry.
 */

/** What a rejection hands the registry: the values the sentence should name. */
export interface RecoveryContext {
  /** The value the model passed that was refused, echoed so the line is concrete. */
  readonly refused?: string | undefined
  /** The Thread the rejected action was aimed at, when there is one. */
  readonly threadRef?: string | undefined
  /** The Task the rejected action was aimed at, when there is one. */
  readonly taskRef?: string | undefined
  /** The Project the rejected action was aimed at, when there is one. */
  readonly projectRef?: string | undefined
  /** The tool action whose parameter shape was wrong, when the fault is a shape. */
  readonly action?: string | undefined
  /** The parameter that belongs to another action, when the fault is that one. */
  readonly parameter?: string | undefined
  /** The action that parameter does belong to, when the fault is that one. */
  readonly owner?: string | undefined
}

/** One registered way out: the situation it answers, and its words. */
export interface RecoveryEntry {
  /** The rejection kind this entry answers, exactly as the rejecting code spells it. */
  readonly kind: string
  /** The sentence, built from the context so it can name real values. */
  readonly sentence: (context: RecoveryContext) => string
}

/** One entry per model-facing fault, naming the next action and its value. Lookup is by exact kind so a new kind cannot inherit a neighbour's sentence. */
export const RECOVERY_REGISTRY: readonly RecoveryEntry[] = Object.freeze([
  {
    kind: 'unread_required',
    sentence: ({ threadRef, taskRef }: RecoveryContext) => [
      'Reconsider the pending updates above; if any change is missing or truncated, read them with team_thread read before writing.',
      ...(threadRef === undefined ? [] : [threadRef]),
      ...(taskRef === undefined ? [] : [taskRef]),
    ].join(' '),
  },
  {
    kind: 'main_unread_required',
    sentence: ({ projectRef }: RecoveryContext) => `Read the pending Main stream updates with team_thread read and projectRef${projectRef === undefined ? '' : ` ${projectRef}`} before reconsidering this post.`,
  },
  {
    kind: 'project_owner_required',
    sentence: ({ projectRef }: RecoveryContext) => `Only a Project owner starts or promotes a Thread — use team_message post to speak in ${projectRef === undefined ? 'the Project' : projectRef}'s Main stream, and mention an owner when the work needs one.`,
  },
  {
    kind: 'accountable_owner_required',
    sentence: ({ taskRef }: RecoveryContext) => `Only the Task's accountable owner or the Human does this${taskRef === undefined ? '' : ` (${taskRef})`} — ask them in the Thread, or, when you are the accountable, use team_task transfer first.`,
  },
  {
    kind: 'self_acceptance_forbidden',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent who held any Claim on${taskRef === undefined ? ' this Task' : ` ${taskRef}`} cannot accept it — if you are the accountable owner, use team_task transfer to give an uninvolved owner responsibility for acceptance; otherwise ask the accountable owner or the Human in the Thread to arrange verification.`,
  },
  {
    kind: 'accountable_target_invalid',
    sentence: ({ taskRef }: RecoveryContext) => `The accountable must be an enabled Project owner here or the Human${taskRef === undefined ? '' : ` (${taskRef})`} — choose a current owner with team_view as the accountable and retry; only the Human may transfer a finished Task.`,
  },
  {
    kind: 'accept_requires_in_review',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent accepts only an in_review Task${taskRef === undefined ? '' : ` (${taskRef})`} — mark your Claim done with team_task done to hand it to review, or ask the Human to accept early.`,
  },
  {
    kind: 'not_project_member',
    sentence: ({ projectRef }: RecoveryContext) => `Only Project members take part in ${projectRef === undefined ? 'a Project' : projectRef} — choose a Project listed by team_view, or ask the Human or a Project owner to mention you there.`,
  },
  {
    kind: 'main_stream_addressing',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'threadRef and projectRef'} address different things — pass threadRef to read a Thread, or projectRef to read a Project's Main stream, and retry with one of them.`,
  },
  {
    kind: 'unread_remaining',
    sentence: () => 'call team_thread read again.',
  },
  {
    kind: 'stale_revision',
    sentence: () => 'Reconsider the new facts above; if any change is missing or truncated, read the Thread with team_thread read before retrying with the token that read returns.',
  },
  {
    // Same refusal as `stale_revision` with a different cause: the token was never a revision this Thread reached. The race sentence would send the model hunting for a nonexistent insertion. A distinct kind keeps exact-kind lookup reachable.
    kind: 'stale_revision_token_unrecognized',
    sentence: ({ threadRef }: RecoveryContext) => [
      'That write token is not a revision this Thread reached — nobody inserted anything, so there is nothing to go and re-read.',
      `Take a current token from ${threadRef === undefined ? 'the Thread' : threadRef} with team_thread read, or reuse the one your own last committed mutation rendered.`,
    ].join(' '),
  },
  {
    kind: 'missing_thread_identity',
    sentence: () => 'Copy a threadRef (or a taskRef on a Taskful Thread) from team_inbox or team_view, then retry.',
  },
  {
    kind: 'missing_message_ref',
    sentence: ({ refused }: RecoveryContext) => `Copy the messageRef you were shown${refused === undefined ? '' : ` (${refused})`}, then retry.`,
  },
  {
    kind: 'history_only_arguments',
    // Only `message` reaches this now: a read ignores a page size, because its batch is bounded by design and its footer already names what remains.
    sentence: ({ action }: RecoveryContext) => `${action ?? 'message'} reads one Message back and cannot page — drop beforeSequence and limit, or call action: history to page older facts.`,
  },
  {
    kind: 'action_only_arguments',
    // Named by parameter: `messageRef` belongs to `message` alone and would otherwise be dropped silently.
    sentence: ({ action, parameter, owner }: RecoveryContext) => `${action ?? 'read'} does not accept ${parameter ?? 'that parameter'} — drop it, or call action: ${owner ?? 'message'} where it belongs.`,
  },
  {
    kind: 'missing_write_token',
    sentence: () => 'Drain the Thread with team_thread read and copy the next-write token it renders, or reuse the one your own last committed mutation rendered.',
  },
  {
    kind: 'start_requires_project',
    sentence: () => 'start opens a new Thread: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'post_requires_project',
    sentence: () => 'post speaks in a Project\'s Main stream: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'dm_requires_member',
    sentence: () => 'Copy the memberRef of an enabled Agent from team_view; a DM is a private note, so shared work belongs in a Thread reply.',
  },
  {
    kind: 'claim_requires_direction',
    sentence: () => 'claim opens a new Claim with your one-sentence direction — drop claimRef, or use done/release to change an existing one.',
  },
  {
    kind: 'claim_close_requires_ref',
    sentence: ({ action }: RecoveryContext) => `Copy the claimRef of your own Claim from team_task list or the Thread read; you can only ${action ?? 'close'} a Claim you own.`,
  },
  {
    kind: 'promote_requires_thread',
    sentence: () => 'promote needs the threadRef of the discussion Thread to turn into a Task — copy it from team_thread read or the Main stream card.',
  },
  {
    kind: 'task_action_requires_task',
    sentence: ({ action }: RecoveryContext) => `${action ?? 'This action'} needs a taskRef — copy one from team_task board or the Task's Thread read.`,
  },
  {
    kind: 'list_takes_task_only',
    sentence: () => 'Drop baseRevision, direction, claimRef, and threadRef — list takes only taskRef.',
  },
  {
    kind: 'board_takes_no_task',
    sentence: () => 'board reads the whole board — drop taskRef, threadRef, baseRevision, direction, and claimRef; to reach one Task, copy its taskRef from the board and use list.',
  },
  {
    kind: 'promote_takes_thread',
    sentence: () => 'promote works on a discussion Thread — drop taskRef, direction, and claimRef, and pass threadRef with the Thread’s current write token.',
  },
  {
    kind: 'claim_owned_by_another',
    sentence: ({ refused }: RecoveryContext) => `Claim ${refused ?? ''} belongs to another Member or another Task — list this Task's Claims with team_task list and close one of your own.`,
  },
  {
    kind: 'reply_target_unknown',
    sentence: ({ refused }: RecoveryContext) => `Reply target ${refused ?? ''} is not a recorded Message — copy a messageRef rendered by team_thread read, team_view, or an inbox notice.`,
  },
  {
    kind: 'message_read_unknown',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} is not a recorded Message — copy a messageRef rendered by team_thread read, team_view, or an inbox notice.`,
  },
  {
    kind: 'message_read_foreign',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} belongs to another Thread — read that Thread first, or copy a messageRef from this Thread's own read.`,
  },
  {
    kind: 'message_read_foreign_project',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} belongs to another Project — read that Project's Main stream, or copy a messageRef from this Project's own Main stream read.`,
  },
  {
    kind: 'attachment_path_rejected',
    sentence: ({ refused }: RecoveryContext) => `Attachment ${refused ?? ''} was refused — attachments are absolute paths to one existing non-empty file within the byte limit; fix the path or drop the attachment.`,
  },
  {

import { describe, expect, it } from 'vitest'
import { occurrences, renderText, teamTools } from './render-text.ts'

/**
 * Discriminating render tests for Project C: a rejected write renders the new
 * facts and the next write token in the SAME tool result, so the model never
 * pays a separate `team_thread read` round-trip to learn what changed.
 *
 * These lock the presence AND absence of exactly the fields the next decision
 * needs. The old contract — "a rejection carries no changed facts, so it never
 * renders a numeric revision or a next-write token" — is what this file
 * overturns, so the former `.not.toContain('8394')` assertions are gone here on
 * purpose and live inverted in `team-tools-render.spec.ts`.
 *
 * Absence assertions still target labels, never bare numbers: fact sequences,
 * read-through watermarks, and cursors legitimately render everywhere.
 */

const THREAD = 'thread:d78400e4-4925-4065-87b1-3f81b4a4b5fb'
const TASK = 'task:3245ad40-43fd-4191-a416-7dcaf3a340f2'
const CLAIM = 'claim:326f0b21-a41c-4c47-be18-ad0d4ecfc139'
const MEMBER = 'member:6e8a5b10-df16-4ec0-943a-63738010953f'

/** One unread message fact, shaped exactly as `read` returns it. */
function messageFact(sequence: number, body: string, options: { direct?: boolean; sender?: string } = {}) {
  return { sequence, kind: 'message', body, sender: options.sender ?? 'human', mentions: [],
    unread: true, direct: options.direct ?? false }
}

describe('unread_required renders the facts it is gating on', () => {
  it('renders every unread fact body, keeps the counts, and hands back the current revision', () => {
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8000, body: 'x' }, {
      kind: 'unread_required', threadRef: THREAD, taskRef: TASK, revision: 8394, unreadCount: 2, directCount: 1,
      facts: [messageFact(8393, 'First unread message'), messageFact(8394, 'The direct mention', { direct: true })],
    })
    // Outcome first, then the identity line that still carries the counts.
    expect(text).toContain('Not committed — unread_required.')
    expect(text).toContain(`${THREAD} · ${TASK} · 2 unread, 1 direct`)
    // The bodies arrive in the same result: this is the round-trip being removed.
    expect(text).toContain('First unread message')
    expect(text).toContain('The direct mention')
    // Unread/direct markers sit on the fact line itself, same as a read.
    expect(text).toContain('8394 [human] [direct] The direct mention')
    expect(text).toContain('8393 [human] [unread] First unread message')
    // And the current revision is written back as the next write token.
    expect(text).toContain('Next write — baseRevision: 8394')
    // Exactly one token: a second one would make the hand-off ambiguous.
    expect(occurrences(text, 'Next write — baseRevision:')).toBe(1)
  })

  it('renders activity facts, not just messages', () => {
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8000, body: 'x' }, {
      kind: 'unread_required', threadRef: THREAD, revision: 8400, unreadCount: 1, directCount: 0,
      facts: [{ sequence: 8400, kind: 'activity', activity: 'claim', actor: 'builder', taskRef: TASK,
        claimRef: CLAIM, unread: true, direct: false }],
    })
    expect(text).toContain('8400 builder claim')
    expect(text).toContain(`Task ${TASK}`)
    expect(text).toContain(`Claim ${CLAIM}`)
    expect(text).toContain('Next write — baseRevision: 8400')
  })

  it('a rejection carrying no facts still renders the token and the read route', () => {
    // A legacy or degenerate payload must not silently lose the hand-off: with
    // no bodies to show, the revision and the recovery route are all the model
    // has, so both must survive.
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8000, body: 'x' }, {
      kind: 'unread_required', threadRef: THREAD, revision: 8394, unreadCount: 0, directCount: 0, facts: [],
    })
    expect(text).toContain('Not committed — unread_required.')
    expect(text).toContain('Next write — baseRevision: 8394')
    expect(text).toContain('team_thread read')
  })
})

describe('stale_revision renders the increment it rejected against', () => {
  it('renders the facts added since the stale baseRevision and the current revision', () => {
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8387, body: 'x' }, {
      kind: 'stale_revision', threadRef: THREAD, expectedRevision: 8387, revision: 8394,
      facts: [messageFact(8394, 'A teammate replied while you were writing')],
    })
    expect(text).toContain('Not committed — the Thread changed after your last read (stale_revision).')
    expect(text).toContain('A teammate replied while you were writing')
    // The revision the model actually needs next is the CURRENT one, not the
    // obsolete token it just tried — naming the stale value would invite a
    // second rejection.
    expect(text).toContain('Next write — baseRevision: 8394')
    expect(occurrences(text, 'Next write — baseRevision:')).toBe(1)
  })

  it('names the increment window so the model knows what the span covers', () => {
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8387, body: 'x' }, {
      kind: 'stale_revision', threadRef: THREAD, expectedRevision: 8387, revision: 8394,
      facts: [messageFact(8388, 'first'), messageFact(8389, 'second'), messageFact(8394, 'third')],
    })
    expect(text).toContain('3')
    expect(text).toContain('third')
    expect(text).toContain('Next write — baseRevision: 8394')
  })

  it('an empty increment still hands back the current revision', () => {
    // Nothing new to show, but the token must still move forward — otherwise
    // the retry repeats the same rejection forever.
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8387, body: 'x' }, {
      kind: 'stale_revision', threadRef: THREAD, expectedRevision: 8387, revision: 8394, facts: [],
    })
    expect(text).toContain('Next write — baseRevision: 8394')
  })
})

describe('the claim mutation shares the same rejection shape', () => {
  it('unread_required on team_task renders the bodies and the token too', () => {
    const text = renderText(teamTools().get('team_task')!, { action: 'claim', taskRef: TASK, baseRevision: 8000, direction: 'd' }, {
      kind: 'unread_required', taskRef: TASK, threadRef: THREAD, revision: 8394, unreadCount: 1, directCount: 0,
      facts: [messageFact(8394, 'Discussion to read first')],
    })
    expect(text).toContain('Not committed — unread_required.')
    expect(text).toContain('Discussion to read first')
    expect(text).toContain('Next write — baseRevision: 8394')
  })

  it('stale_revision on team_task renders the increment and the token', () => {
    const text = renderText(teamTools().get('team_task')!, { action: 'done', taskRef: TASK, baseRevision: 8387, claimRef: CLAIM }, {
      kind: 'stale_revision', taskRef: TASK, threadRef: THREAD, expectedRevision: 8387, revision: 8394,
      facts: [messageFact(8394, 'New fact in the way')],
    })
    expect(text).toContain('New fact in the way')
    expect(text).toContain('Next write — baseRevision: 8394')
  })
})

describe('the rejection render never invents a second write token', () => {
  it('the recovery sentence stays a route to read, and does not repeat the token', () => {
    const text = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8000, body: 'x' }, {
      kind: 'unread_required', threadRef: THREAD, revision: 8394, unreadCount: 1, directCount: 1,
      facts: [messageFact(8394, 'the mention', { direct: true, sender: MEMBER })],
    })
    // The old recovery sentence told the model to go read; it must still name
    // the tool that drains the queue, because the facts here are the gate, not
    // a replacement for acknowledging them.
    expect(text).toContain('team_thread read')
    // One token only, and it is the current revision.
    expect(occurrences(text, 'Next write — baseRevision:')).toBe(1)
    expect(text).toContain('Next write — baseRevision: 8394')
  })
})

  expect(parameters.required).toContain('body')
})

it('typed rejections begin Not committed, keep refs/counts/recovery, and hand back the current revision', () => {
  const unread = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8000, body: 'x' }, {
    kind: 'unread_required', threadRef: THREAD, taskRef: TASK, revision: 8394, unreadCount: 2, directCount: 1,
    facts: [{ sequence: 8394, kind: 'message', body: 'the gated fact', sender: 'human', mentions: [], unread: true, direct: true },
      { sequence: 8395, kind: 'message', body: 'another update', sender: 'human', mentions: [], unread: true, direct: false }],
  })
  expect(unread).toContain('Not committed — unread_required.')
  expect(unread).toContain(`${THREAD} · ${TASK} · 2 unread, 1 direct`)
  expect(unread).toContain('team_thread read')
  // Project C: the gated facts render in the rejection itself, and the
  // current revision comes back as the next write token. This inverted the
  // old contract, which held that a rejection carried no facts and no token.
  expect(unread).toContain('the gated fact')
  expect(unread).toContain('Next write — baseRevision: 8394')

  const stale = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8387, body: 'x' }, {
    kind: 'stale_revision', threadRef: THREAD, expectedRevision: 8387, revision: 8394,
    facts: [{ sequence: 8394, kind: 'message', body: 'the increment', sender: 'human', mentions: [], unread: true, direct: false }],
  })
  expect(stale).toContain('Not committed — the Thread changed after your last read (stale_revision).')
  expect(stale).toContain('Reconsider the new facts above')
  expect(stale).toContain('the increment')
  expect(stale).toContain('Next write — baseRevision: 8394')

  // A token this Thread never reached is not a race. The ordinary sentence
  // would send a model re-reading to find an insertion that never happened,
  // so the refusal names the copying mistake and drops the increment lines,
  // which would otherwise present facts as missed when none were.
  const copied = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 4711, body: 'x' }, {
    kind: 'stale_revision', threadRef: THREAD, expectedRevision: 4711, revision: 8394, staleTokenKind: 'unrecognized',
    facts: [{ sequence: 8394, kind: 'message', body: 'the increment', sender: 'human', mentions: [], unread: true, direct: false }],
  })
  expect(copied).toContain('Not committed — that write token was never a revision this Thread reached (stale_revision).')
  expect(copied).toContain('not a revision this Thread reached')
  // The headline must not contradict the way out: the first line can no
  // longer claim the Thread changed, and the race sentence is gone with it.
  expect(copied).not.toContain('the Thread changed')
  expect(copied).not.toContain('Reconsider the new facts above')
  expect(copied).not.toContain('the increment')
  expect(copied).toContain('Next write — baseRevision: 8394')

  // member_not_following is a version-1 result the Host can no longer produce
  // for a tool call: the fallback render names the kind and the Thread without
  // inventing a recovery route for a state that cannot occur.
  const legacyNotFollowing = renderText(teamTools().get('team_message')!, { action: 'reply', threadRef: THREAD, baseRevision: 8394, body: 'x' }, {
    kind: 'member_not_following', memberIds: ['member:6d5ac10d-3ef6-4466-a1f7-d105ca1b6da5'], threadRef: THREAD, revision: 8394,

      expect(occurrences(text, 'claim:')).toBe(1)
      expect(text).not.toContain('Active Claims')
    }
  })

  it('claim rejections share the outcome-first form and hand back the current revision', () => {
    const unread = renderText(teamTools().get('team_task')!, { action: 'claim', taskRef: TASK, baseRevision: 8000, direction: 'd' }, {
      kind: 'unread_required', taskRef: TASK, threadRef: THREAD, revision: 8394, status: 'in_progress', unreadCount: 2, directCount: 1,
      claims: [{ claimRef: CLAIM, direction: 'Audit the render recovery paths', state: 'active', owner: 'member:owner' }],
      facts: [{ sequence: 8394, kind: 'message', body: 'the gated fact', sender: 'human', mentions: [], unread: true, direct: true },
        { sequence: 8395, kind: 'message', body: 'another update', sender: 'human', mentions: [], unread: true, direct: false }],
    })
    expect(unread).toContain('Not committed — unread_required.')
    expect(unread).toContain(`${THREAD} · ${TASK} · 2 unread, 1 direct`)
    expect(unread).toContain('team_thread read')
    expect(unread).toContain('the gated fact')
    expect(unread).toContain('Next write — baseRevision: 8394')
    // The Claim archive still never rides along with a rejection: the affected
    // Claim and the facts are the decision surface, not the whole history.
    expect(unread).not.toContain('Active Claims')

    const stale = renderText(teamTools().get('team_task')!, { action: 'done', taskRef: TASK, baseRevision: 8387, claimRef: CLAIM }, {
      kind: 'stale_revision', taskRef: TASK, threadRef: THREAD, expectedRevision: 8387, revision: 8394, status: 'in_progress',
      claims: [{ claimRef: CLAIM, direction: 'Audit the render recovery paths', state: 'active', owner: 'member:owner' }],
      facts: [{ sequence: 8394, kind: 'message', body: 'the increment', sender: 'human', mentions: [], unread: true, direct: false }],
    })
    expect(stale).toContain('Not committed — the Thread changed after your last read (stale_revision).')
    expect(stale).toContain('the increment')
    expect(stale).toContain('Next write — baseRevision: 8394')

    // The copied-token refusal on the Claim side, because the Claim tool
    // renders its own rejections: a member that closes a Claim with a token
    // from another Thread gets the same correction, not the race sentence.
    const copied = renderText(teamTools().get('team_task')!, { action: 'done', taskRef: TASK, baseRevision: 4711, claimRef: CLAIM }, {
