import { createHash } from 'node:crypto'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { isAgentTeamSource } from './context-source.ts'
import type { AgentTeamMemberId, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types.ts'

export const NOTIFICATION_TRUNCATION_MARKER = '[Message body truncated; use team_thread read for the full Message.]'
export const NOTIFICATION_BODY_MAX_CHARACTERS = 8 * 1024

export type ThreadMessageSurface = {
  readonly textDigest: string
  readonly messages: readonly { readonly threadRef: string; readonly messageRef: string; readonly bodyDigest: string }[]
}

export interface RenderedThreadMessage {
  readonly threadRef: string
  readonly messageRef: string
  readonly body: string
}

const digest = (text: string): string => createHash('sha256').update(text).digest('hex')

/** Bind only messages the producer rendered in full, to the exact text it emitted. */
export function threadMessageSurface(text: string, messages: readonly RenderedThreadMessage[]) {
  return { textDigest: digest(text), messages: messages.map(message => ({
    threadRef: message.threadRef, messageRef: message.messageRef, bodyDigest: digest(message.body),
  })) }
}

/** A live projection, not a read receipt. Cropped text cannot attest through retained metadata. */
export function visibleTeamSurface(agent: Pick<Agent, 'session'>): readonly ThreadMessageSurface[] {
  const entries: ThreadMessageSurface[] = []
  for (const sequence of agent.session.surface.nodes) {
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event === undefined) continue
    const message = agent.session.deriveEventMessage(event)
    if (message === null) continue
    let binding: unknown
    if (event.type === 'user/message' && message.role === 'user' && isAgentTeamSource(message.source) && message.source.form === 'notice') {
      binding = message.source.threadFacts
    } else if (event.type === 'tool/result' && message.role === 'tool' && !message.isError) {
      const ownCall = event.sourceEventSeqs?.some(sequence => {
        const call = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
        return call?.type === 'tool/call' && call.data.callId === message.toolCallId
          && (call.data.name === 'team_thread' || call.data.name === 'team_message' || call.data.name === 'team_task')
      })
      if (!ownCall) continue
      const meta = event.data.meta
      if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) continue
      binding = meta['threadFacts']
    }
    const surface = surfaceOf(binding)
    if (surface === undefined || message.content.some(part => part.type !== 'text')) continue
    const text = message.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n')
    if (digest(text) === surface.textDigest) entries.push(surface)
  }
  return entries
}

function surfaceOf(value: unknown): ThreadMessageSurface | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const surface = value as Partial<ThreadMessageSurface>
  if (typeof surface.textDigest !== 'string' || !Array.isArray(surface.messages)) return undefined
  if (!surface.messages.every(message => message !== null && typeof message === 'object'
    && typeof message.threadRef === 'string' && typeof message.messageRef === 'string' && typeof message.bodyDigest === 'string')) return undefined
  return surface as ThreadMessageSurface
}

export function isFactOnSurface(entries: readonly ThreadMessageSurface[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
  if (fact.fact.kind !== 'message' || fact.fact.message.body === '') return false
  const { messageRef, body } = fact.fact.message
  const bodyDigest = digest(body)
  return entries.some(entry => entry.messages.some(message => message.threadRef === threadRef
    && message.messageRef === messageRef && message.bodyDigest === bodyDigest))
}

export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
  return (memberId: AgentTeamMemberId, facts: readonly AgentTeamThreadReadFact[], threadRef: AgentTeamThreadRef): boolean => {
    const agent = agentFor(memberId)
    if (agent === undefined) return false
    const entries = visibleTeamSurface(agent)
    return facts.every(fact => isFactOnSurface(entries, fact, threadRef))
  }
}

/** Task standing inline on a Thread identity line; absent on taskless Threads. Accountability rides along whenever the result carries it, because who is responsible for the Task changes what the reader may do next. */
function taskStanding(value: { taskRef?: string; status?: string; resolution?: string; taskNumber?: number; accountable?: string }): string {
  if (value.taskRef === undefined) return ''
  return `${value.taskRef}${value.taskNumber === undefined ? '' : ` (#${value.taskNumber})`}${value.status === undefined ? '' : `, ${value.status}${value.resolution === undefined ? '' : `/${value.resolution}`}`}${value.accountable === undefined ? '' : ` · accountable ${value.accountable}`}`
}

/** One Task a discussion spawned, as the card its Thread renders at the creation point: current state, never a fact, never unread. */
interface TaskCardView {
  readonly taskRef: string
  readonly taskNumber: number
  readonly threadRef: string
  readonly sequence: number
  readonly occurredAt: string
  readonly subject: string
  readonly status: string
  readonly resolution: string
  readonly accountable: string
}

const TASK_CARD_SCHEMA = {
  type: 'object', additionalProperties: false, properties: {
    taskRef: { type: 'string', required: true }, taskNumber: { type: 'number', required: true }, threadRef: { type: 'string', required: true },
    sequence: { type: 'number', required: true }, occurredAt: { type: 'string', required: true }, subject: { type: 'string', required: true },
    status: { type: 'string', required: true }, resolution: { type: 'string', required: true }, accountable: { type: 'string', required: true },
  },
} as const

function taskCardView(entry: AgentTeamThreadTaskCard): TaskCardView {
  // Flattened from the shared card: the model-facing view keeps its own stable field set, so the Host projection can
  // grow without changing what a tool result declares.
  const card = entry.card
  return { taskRef: card.task.taskRef, taskNumber: card.task.taskNumber, threadRef: card.threadRef, sequence: entry.sequence,
    occurredAt: card.anchor.occurredAt, subject: card.anchor.preview, status: card.task.status, resolution: card.task.resolution,
    accountable: card.task.accountable }
}

/** One card line, marked as a projection so it never reads as a fact: where the Task was created, its current state, and the Thread to open it on. */
function taskCardLine(card: TaskCardView): string {
  return `${card.sequence} ${formatTeamTimestamp(card.occurredAt)} [task card] Task ${card.taskRef} (#${card.taskNumber}), ${card.status}/${card.resolution} · accountable ${card.accountable} — ${card.subject} · ${card.threadRef}`
}

/** Facts and the cards their discussion spawned in one chronological order: a card sits at its creation sequence and breaks a fact run, the way the Client timeline draws it. */
function factTimelineLines(facts: readonly FactView[], cards: readonly TaskCardView[]): string[] {
  const lines: string[] = []
  let next = 0
  for (const fact of facts) {
    while (next < cards.length && cards[next]!.sequence < fact.sequence) lines.push(taskCardLine(cards[next++]!))
    lines.push(factLine(fact))
  }
  while (next < cards.length) lines.push(taskCardLine(cards[next++]!))
  return lines
}

/** The one model-facing schema for a Thread fact, shared by the read result and by the facts a rejected write carries back. */
const FACT_SCHEMA = {
  type: 'object', additionalProperties: false, properties: {
    sequence: { type: 'number', required: true }, kind: { type: 'string', required: true }, messageRef: { type: 'string' }, body: { type: 'string' }, sender: { type: 'string' }, occurredAt: { type: 'string' }, mentions: { type: 'array', items: { type: 'string' } }, replyToMessageRef: { type: 'string' }, replyTo: { type: 'object', additionalProperties: false, properties: { sender: { type: 'string', required: true }, excerpt: { type: 'string', required: true } } }, activity: { type: 'string' }, actor: { type: 'string' }, taskRef: { type: 'string' }, claimRef: { type: 'string' }, claimRefs: { type: 'array', items: { type: 'string' } }, completedClaimRefs: { type: 'array', items: { type: 'string' } }, acceptedClaimRefs: { type: 'array', items: { type: 'string' } }, releasedClaimRefs: { type: 'array', items: { type: 'string' } }, unread: { type: 'boolean' }, direct: { type: 'boolean' },
  },
} as const

function requestId(agentId: string, callId: string): AgentTeamRequestId {
  return `agent-team:tool:${agentId}:${callId}` as AgentTeamRequestId
}

/**
 * Some models fill every optional parameter slot with `""` (or a zero count) instead
 * of omitting it, and every guard below asks `!== undefined`. Normalizing blanks to
 * "not passed" at the entry keeps those guards honest and the address parameters
 * resolvable, without weakening the guards for genuinely malformed values. Only
 * address/selection parameters are normalized — `body` is content, where an empty
 * string is a real error the tool must report, not a missing field. An empty
 * collection names nothing to honor, exactly as an empty address names no target.
 */
function blankToAbsent<T extends { readonly [key: string]: unknown }>(args: T, keys: readonly string[]): T {
  const copy: Record<string, unknown> = { ...args }
  for (const key of keys) {
    const value = copy[key]
    if (value === '' || value === 0 || value === false || (Array.isArray(value) && value.length === 0)) delete copy[key]
  }
  return copy as T

