    const fullAnchor = value.kind === 'history' ? args.beforeSequence === undefined : facts.some(fact => fact.unread === false)
    if (value.kind !== 'message' && !anchorInFacts && fullAnchor && value.anchor !== undefined) {
      facts.push({ ...value.anchor, kind: 'message' })
    }
    return { threadFacts: threadMessageSurface(text, messageIdentities(value.threadRef, facts)) }
