import { describe, expect, it } from 'vitest'
import { renderText, teamTools } from './render-text.ts'

const ACCEPT_FACT = {
  sequence: 8190,
  kind: 'activity',
  activity: 'accept',
  actor: 'human',
  taskRef: 'task:205a8ba6-f3c6-4fbc-95b7-c3448191f730',
  completedClaimRefs: ['claim:7ad04d38-3889-4414-ac0c-23f73c0b962a'],
  acceptedClaimRefs: ['claim:7ad04d38-3889-4414-ac0c-23f73c0b962a'],
  unread: true,
  direct: false,
}

describe('team_thread renders Task accountability with the Task standing', () => {
  it('a read of a Taskful Thread names its accountable owner on the identity line', () => {
    const text = renderText(teamTools().get('team_thread')!, { action: 'read', threadRef: 'thread:x' }, {
      workspaceId: 'workspace:alpha', projectRef: 'project:046dd831-c679-4279-b6aa-7813476cf12e',
      kind: 'read', threadRef: 'thread:x', taskRef: 'task:205a8ba6-f3c6-4fbc-95b7-c3448191f730', taskNumber: 7,
      revision: 100, status: 'in_review', resolution: 'open', accountable: 'member:6e8a5b10-df16-4ec0-943a-63738010953f', following: true,
      anchor: { messageRef: 'message:anchor', sender: 'human', body: 'anchor', sequence: 1 },
      claims: [], facts: [], readThroughSequence: 100, remainingUnreadCount: 0,
    })
    expect(text.split('\n')[2]).toBe('thread:x · task:205a8ba6-f3c6-4fbc-95b7-c3448191f730 (#7), in_review/open · accountable member:6e8a5b10-df16-4ec0-943a-63738010953f · following')
  })

  it('a taskless Thread renders no accountability, because there is no Task to be responsible for', () => {
    const text = renderText(teamTools().get('team_thread')!, { action: 'read', threadRef: 'thread:x' }, {
      workspaceId: 'workspace:alpha', projectRef: 'project:046dd831-c679-4279-b6aa-7813476cf12e',
      kind: 'read', threadRef: 'thread:x', revision: 100, following: false,
      anchor: { messageRef: 'message:anchor', sender: 'human', body: 'anchor', sequence: 1 },
      claims: [], facts: [], readThroughSequence: 100, remainingUnreadCount: 0,
    })
    expect(text).not.toContain('accountable')
  })
})

describe('team_thread renders the model-facing decision surface', () => {
  it('an accept activity renders actor, Task ref, and the Claims it concluded — not a bare kind', () => {
    const text = renderText(teamTools().get('team_thread')!, {}, {
      workspaceId: 'workspace:alpha', projectRef: 'project:046dd831-c679-4279-b6aa-7813476cf12e',
      kind: 'read', threadRef: 'thread:cb7e5eca-9a73-4fa6-9fdf-260996597e7d',
      taskRef: 'task:205a8ba6-f3c6-4fbc-95b7-c3448191f730',
      revision: 8190, status: 'done', resolution: 'accepted', following: true,
      anchor: { messageRef: 'message:anchor', sender: 'human', body: 'anchor', sequence: 1 },
      claims: [{ claimRef: 'claim:7ad04d38-3889-4414-ac0c-23f73c0b962a', direction: 'ship it', state: 'done', owner: 'member:6e8a5b10-df16-4ec0-943a-63738010953f' }],
      facts: [ACCEPT_FACT],
      readThroughSequence: 8190, remainingUnreadCount: 0,
    })
    // The outcome line names the Thread, and the context line carries the
    // Task's standing — never just the Thread revision.

threadHistory(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: AgentTeamThreadHistoryRequest): AgentTeamThreadHistory {
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  const { task, thread } = this.threadContextForActor(authorized, request.workspaceId, request)
  const limit = request.limit ?? 20
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) throw new Error('history limit must be an integer between 1 and 100')
  const before = request.beforeSequence ?? this.currentTail(thread.threadRef) + 1
  if (!Number.isInteger(before) || before < 1) throw new Error('beforeSequence must be a positive integer')
  const all = this.threadFacts(thread.threadRef).filter(fact => fact.sequence < before)
  const facts = all.slice(-limit)
  const anchor = this.threadAnchor(thread.threadRef)
  return Object.freeze({ ...(task === undefined ? {} : { task }), thread, anchor, anchorMentions: this.state.mentionsByMessage.get(anchor.messageRef) ?? [],
    claims: task === undefined ? Object.freeze([]) : this.claimsForTask(task.taskRef), facts: Object.freeze(facts),
    ...(task === undefined ? { taskCards: this.derivedTaskCards(thread.threadRef) } : {}),
    cursor: facts.length === 0 ? before : facts[0]!.sequence, hasMore: all.length > facts.length })
}

/**
 * The Tasks this discussion spawned, as the cards the Thread renders at their creation points. Each card is the Main
 * stream's own `mainThreadCard` projection of the Task's Thread, so the two faces cannot drift apart.
 */
private derivedTaskCards(threadRef: AgentTeamThreadRef): readonly AgentTeamThreadTaskCard[] {
  const cards: AgentTeamThreadTaskCard[] = []
  for (const task of this.state.tasks.values()) {
    if (!task.sourceThreadRefs.includes(threadRef)) continue
    const anchor = this.state.anchorByThread.get(task.threadRef)
    if (anchor === undefined) continue
    const card = this.mainThreadCard(task.threadRef)
    // The Task's own Thread always carries its taskRef, so the facet is present; the guard is what tells the type so.
    if (card.task === undefined) continue
    cards.push(Object.freeze({ sequence: anchor.sequence, card: { ...card, task: card.task } }))
  }
  return Object.freeze(cards.sort((left, right) => left.sequence - right.sequence
    || left.card.task.taskRef.localeCompare(right.card.task.taskRef)))
}

listClaims(actor: AgentTeamHumanActor | AgentTeamMemberActor, request: { workspaceId: WorkspaceId; taskRef: AgentTeamTaskRef }): AgentTeamClaimList {
  const authorized = this.assertActorForWorkspace(actor, request.workspaceId)
  const { task, thread } = this.threadForActor(authorized, request.workspaceId, request.taskRef)
  return Object.freeze({ task, thread, claims: this.claimsForTask(task.taskRef) })
}

getTask(taskRef: AgentTeamTaskRef): AgentTeamTask | undefined {
  return this.state.tasks.get(taskRef)
}

