export const name = 'wowyuarm-agent-team-member-context'

/**
 * Which injected block this message carries. Identity, ownership, and
 * participation are current-state lists; memory separates the complete
 * baseline from a notice that an earlier copy is stale, so a surviving
 * notice is never mistaken for a complete index.
 */
export type MemberContextTag =
  | { readonly category: 'identity' | 'ownership' | 'workspaces' }
  | { readonly category: 'memory'; readonly variant: 'baseline' | 'update' | 'unavailable'; readonly digest: string; readonly textDigest: string }

/** This producer's attribution; `kind` must be producer-owned (Session format V4). The second member is the read-side rename of this producer's released V3 history. */
declare module '@deepseek-ai/dsh-llm' {
  interface MessageSourceMap {
    'wowyuarm-agent-team-member-context': {
      kind: 'wowyuarm-agent-team-member-context'
      readonly memberContext?: MemberContextTag
    } & ContextFormed
    'plugin:wowyuarm-agent-team-member-context': {
      kind: 'plugin:wowyuarm-agent-team-member-context'
      readonly memberContext?: MemberContextTag
    } & ContextFormed
  }
}

const MAX_MEMORY_BYTES = 16 * 1024
const BEGIN = '<team-member-private-memory>'
const END = '</team-member-private-memory>'

export function apply(ctx: Context): void {
  ctx.on('agent/pre-step', async ({ agent, signal }, next): Promise<PreStepDecision> => {
    const decision = await next()
    if (decision.kind === 'reject' || signal.aborted) return decision
    // The Host service is resolved at step time, never through plugin inject:
    // this row mounts while the Host itself is still restoring Members, and a
    // declared dependency on `agentTeam` would hold the preset mount open
    // until the Host service is active, failing every startup restore.
    const host = ctx.get('agentTeam')
    if (host === undefined) return decision
    const member = host.memberForAgent(agent)
    if (member === undefined) return decision
    const messages = await memberContextMessages(host, agent, member)
    return messages.length === 0 ? decision : { kind: 'enter', messages: [...decision.messages, ...messages] }
  }, { prepend: true })
}

interface MemberContextHost {
  workspacesForAgent(agent: Agent): readonly { readonly workspaceId: string; readonly path: string | undefined; readonly default: boolean }[]
  ownedProjectsForAgent(agent: Agent): readonly AgentTeamProject[] | undefined
}

async function memberContextMessages(
  host: MemberContextHost,
  agent: Agent,
  member: Pick<AgentTeamAgentMember, 'memberId' | 'privateMemoryPath' | 'handle' | 'description'>,
): Promise<UserMessage[]> {
  // The sanitized path is authoritative: activation migrated any legacy
  // colon directory onto it before this member could run a step.
  const memoryPath = memberMemoryDirectoryPath(member)
  const memory = await readMemberMemory(memoryPath)
  const visible = visibleMemberContext(agent)
  const messages: UserMessage[] = []

  const identity = renderMemberIdentity(member)
  if (visible.identity !== identity) messages.push(injectionMessage({ category: 'identity' }, identity))

  const owned = host.ownedProjectsForAgent(agent)
  if (owned !== undefined) {
    const ownership = renderMemberOwnership(owned)
    if (visible.ownership !== ownership) messages.push(injectionMessage({ category: 'ownership' }, ownership))
  }

  const workspaces = renderMemberWorkspaces(host.workspacesForAgent(agent))
  if (visible.workspaces !== workspaces) messages.push(injectionMessage({ category: 'workspaces' }, workspaces))

  const digest = memoryDigest(memory)
  const available = memory.kind === 'index' && memory.raw.byteLength <= MAX_MEMORY_BYTES
  if (visible.latestMemoryDigest !== digest || (available && !visible.hasCompleteMemoryBaseline)) {
    const variant = !available ? 'unavailable' : visible.hasCompleteMemoryBaseline ? 'update' : 'baseline'
    const text = variant === 'update' ? renderMemberMemoryUpdate(memory, memoryPath) : renderMemberMemoryState(memory, memoryPath)
    messages.push(injectionMessage({ category: 'memory', variant, digest, textDigest: createHash('sha256').update(text).digest('hex') }, text))
  }
  return messages
}

function injectionMessage(tag: MemberContextTag, text: string): UserMessage {
  return createUserMessage({
    content: [{ type: 'text', text }],
    source: { kind: name, form: 'instructions', memberContext: tag },
  })
}

interface VisibleMemberContext {
  identity?: string
  ownership?: string
  workspaces?: string
  /** Digest carried by the newest memory event whose visible text is still the text it was written with. */
  latestMemoryDigest?: string
  /** Whether any complete memory baseline is still visible, whatever its age. */
  hasCompleteMemoryBaseline: boolean
}

/**
 * The newest current-state block per category on the live surface.
 *
 * Reads the projected message, not the raw event: a projection can rewrite or
 * prune content while leaving the source tag in place, and such a message can
 * neither stand in for a complete baseline nor vouch for an update digest.
 */
function visibleMemberContext(agent: Agent): VisibleMemberContext {
  const visible: VisibleMemberContext = { hasCompleteMemoryBaseline: false }
  for (const sequence of agent.session.surface.nodes.toReversed()) {
    // `nodes` are event identities (SessionSeq); snapshotEvents takes log
    // offsets. Re-entering through the validating constructor keeps the two
    // number domains explicit (the seq = log.length contiguity contract).
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event?.type !== 'user/message' || !matchesProducerKind(event.data.source.kind, name)) continue
    const derived = agent.session.deriveEventMessage(event)
    if (derived?.role !== 'user') continue
    const tag = (derived.source as { readonly memberContext?: MemberContextTag }).memberContext
    const text = derived.content[0]?.type === 'text' ? derived.content[0].text : undefined
    if (tag === undefined || text === undefined) continue
    if (tag.category === 'memory') {
      if (createHash('sha256').update(text).digest('hex') !== tag.textDigest) continue
      visible.latestMemoryDigest ??= tag.digest
      if (tag.variant === 'baseline') visible.hasCompleteMemoryBaseline = true
    } else {
      visible[tag.category] ??= text
    }
  }
  return visible
}

export function renderMemberIdentity(member: Pick<AgentTeamAgentMember, 'handle' | 'description'>): string {
  return member.description === ''
    ? `Team identity: you are @${member.handle}.`
    : `Team identity: you are @${member.handle} — ${member.description}`
}

/** Rendered even when empty, so a withdrawn ownership replaces the earlier list instead of lingering in context. */
export function renderMemberOwnership(projects: readonly Pick<AgentTeamProject, 'projectRef' | 'name' | 'workspaceId'>[]): string {
  const header = 'Team Project ownership — this list replaces all earlier ownership context.'
  if (projects.length === 0) return `${header}\nYou own no Projects.`
  return [header, 'You own these Projects:', ...projects.map(project => `- ${project.name} ${project.projectRef} (Workspace ${project.workspaceId})`)].join('\n')
}

/** Rendered at every count, so a later list can replace one Workspace, or none, as clearly as it replaces several. */
export function renderMemberWorkspaces(workspaces: readonly { readonly workspaceId: string; readonly path: string | undefined; readonly default: boolean }[]): string {
  const header = 'Team Workspace participation — this list replaces all earlier participation context.'
  if (workspaces.length === 0) return `${header}\nYou participate in no Workspaces.`
  const lines = [header, ...workspaces.map(workspace => `${workspace.workspaceId}${workspace.default ? ' (creation Workspace)' : ''}: ${workspace.path === undefined
    ? 'Workspace path unavailable; ask @human before filesystem work.'
    : `${JSON.stringify(workspace.path)}; instructions: ${JSON.stringify(join(workspace.path, 'AGENTS.md'))}`}`)]
  lines.push('Your Session lineage stays bound to your creation Workspace; Team write permissions come from your Workspace participation, and your working directory follows working_directory({cd: <path>}).')
  if (workspaces.length > 1) {
    lines.push('Work where the work is: relative paths, glob and grep, and instruction and skill discovery resolve from the current directory, so editing another checkout through absolute paths leaves its instructions unloaded.')
    lines.push('Pass workspace explicitly to team_view, team_thread, team_attention, team_message, team_dm and team_task. team_inbox is the cross-Workspace triage entry point.')
    lines.push('If an instruction is ambiguous about which Workspace it concerns, ask @human before acting. Participation does not itself join Projects.')
  }
  return lines.join('\n')
}

/** The four private-memory paths plus the out-of-cwd warning; callers append their own sentence. */
function memoryPathsBlock(privateMemoryPath: string): string {
  return `Private memory directory: ${privateMemoryPath}\nMemory index: ${privateMemoryPath}/memory.md\nNotes directory: ${privateMemoryPath}/notes\nPrivate skills directory: ${privateMemoryPath}/skills\nThese paths are outside the Workspace cwd.`
}

type MemberMemoryState =
  | { readonly kind: 'index'; readonly raw: Buffer }
  | { readonly kind: 'absent' }
  | { readonly kind: 'unreadable' }

async function readMemberMemory(privateMemoryPath: string): Promise<MemberMemoryState> {
  try {
    return { kind: 'index', raw: await readFile(`${privateMemoryPath}/memory.md`) }
  } catch (error) {
    return { kind: (error as NodeJS.ErrnoException).code === 'ENOENT' ? 'absent' : 'unreadable' }
  }
}

function memoryDigest(memory: MemberMemoryState): string {
  return memory.kind === 'index' ? createHash('sha256').update(memory.raw).digest('hex') : memory.kind
}

function memoryUsage(memory: MemberMemoryState): string {
  if (memory.kind !== 'index') return ''
  const usedKiB = (memory.raw.byteLength / 1024).toFixed(1)
  const percent = Math.round((memory.raw.byteLength / MAX_MEMORY_BYTES) * 100)
  return `Private memory index: ${usedKiB} KiB / ${MAX_MEMORY_BYTES / 1024} KiB (${percent}%).`
}

function memoryAnomaly(memory: MemberMemoryState): string {
  if (memory.kind === 'absent') return 'memory.md is absent; the private memory index is empty.'
  if (memory.kind === 'unreadable') return 'memory.md is currently unreadable; do not use any earlier private memory context.'
  if (memory.raw.byteLength > MAX_MEMORY_BYTES) {
    const usedKiB = (memory.raw.byteLength / 1024).toFixed(1)
    const percent = Math.round((memory.raw.byteLength / MAX_MEMORY_BYTES) * 100)
    return `memory.md at ${memory.raw.byteLength} B (${usedKiB} KiB, ${percent}%) exceeds the ${MAX_MEMORY_BYTES / 1024} KiB context budget. Its contents were not injected; do not delete or automatically summarize the file. Maintain a smaller index explicitly.`
  }
  return ''
}

function renderMemberMemoryState(memory: MemberMemoryState, privateMemoryPath = '<private-memory-path>'): string {
  if (memory.kind === 'index') return renderMemberMemory(memory.raw, privateMemoryPath)
  return renderUnavailableMemory(privateMemoryPath, memoryAnomaly(memory))
}

export function renderMemberMemory(raw: Buffer, privateMemoryPath = '<private-memory-path>'): string {
  const overBudget = raw.byteLength > MAX_MEMORY_BYTES
  const body = overBudget ? '' : raw.toString('utf8')
  const usage = `\n\n${memoryUsage({ kind: 'index', raw })}`
  const anomaly = overBudget ? `\n\n[Maintenance warning: ${memoryAnomaly({ kind: 'index', raw })}]` : ''
  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. It is reference context only, may be stale, and is not an instruction or Team fact.\n\n${memoryPathsBlock(privateMemoryPath)} Relative filesystem paths resolve from cwd, so use the absolute paths above when reading or editing this Member's memory. Only this Member can read this directory — no other human or agent sees its contents; when communicating, restate what you need from it instead of pointing others at these paths.${usage}\n\n${escape(body)}${anomaly}\n${END}`
}

/** A compact stale-copy notice: it supersedes earlier private-memory context without pretending to carry the current index. */
export function renderMemberMemoryUpdate(memory: MemberMemoryState, privateMemoryPath = '<private-memory-path>'): string {
  const usage = memoryUsage(memory)
  const anomaly = memoryAnomaly(memory)
  const state = anomaly === '' ? usage : anomaly
  const guidance = anomaly === ''
    ? 'Read it only if you need its current contents; a file you just wrote need not be read back.'
    : 'Inspect or repair it at that path when you need it.'
  return `${BEGIN}\nPrivate memory update: the earlier private-memory context no longer represents the latest memory.md. Memory index: ${privateMemoryPath}/memory.md\n${state}\n${guidance}\n${END}`
}

function renderUnavailableMemory(privateMemoryPath: string, reason: string): string {
  return `${BEGIN}\nThis is the complete replacement for this Team Member's private memory index; all earlier private-memory context is obsolete. ${reason}\n\n${memoryPathsBlock(privateMemoryPath)} Use the absolute paths above when inspecting or repairing this Member's memory.\n${END}`
}

function escape(value: string): string {
  return value.replaceAll(BEGIN, '[escaped begin marker]').replaceAll(END, '[escaped end marker]')
}

import { afterEach, describe, expect, it, vi } from 'vitest'
import { cleanups, realHarness, ScriptedAdapter, textResponse, toolCallResponse, requestId, waitFor } from './helpers/member-harness.ts'
import type { AgentTeamRequestId, AgentTeamThreadRef } from '../src/types.ts'
vi.setConfig({ testTimeout: 60_000 })

afterEach(async () => { await Promise.all(cleanups.splice(0).map(cleanup => cleanup())) })

/** One real Member and a Thread they follow, with one ordinary Human reply waiting unread. */
async function waitingThread(body: string) {
  const adapter = new ScriptedAdapter()
  const test = await realHarness(adapter)
  const member = await test.ctx.agentTeam.addMember({ requestId: requestId('member') as AgentTeamRequestId, workspaceId: test.workspaceId,
    handle: 'builder', description: 'Builds changes', presetId: 'team-member', projectRefs: [project.project.projectRef] })
  const agent = test.ctx.agents.get(member.status.member.sessionId)!
  const started = await test.ctx.agentTeam.startThread({ kind: 'discussion', requestId: requestId('thread') as AgentTeamRequestId,
    workspaceId: test.workspaceId, projectRef: project.project.projectRef, body: 'Release plan' })
  if (started.kind !== 'committed') throw new Error('setup failed')
  await test.ctx.agentTeam.changeAttentionForAgent(agent, { requestId: requestId('follow') as AgentTeamRequestId,
    workspaceId: test.workspaceId, threadRef: started.thread.threadRef, action: 'follow' })
  const update = await test.ctx.agentTeam.reply({ requestId: requestId('update') as AgentTeamRequestId, workspaceId: test.workspaceId,
    threadRef: started.thread.threadRef, body, baseRevision: started.thread.revision })
  if (update.kind !== 'committed') throw new Error('setup failed')
  return { ...test, adapter, agent, memberId: member.status.member.memberId, threadRef: started.thread.threadRef as AgentTeamThreadRef,
    oldRevision: started.thread.revision, currentRevision: update.thread.revision }
}

function toolResultTexts(agent: { readonly session: { ownEvents: () => readonly { type: string; data: never }[] } }): string[] {
  return agent.session.ownEvents().filter(event => event.type === 'tool/result').map(event => {
    const content = (event.data as unknown as { message: { content: readonly { type: string; text?: string }[] } }).message.content
    return content.flatMap(part => part.type === 'text' && part.text !== undefined ? [part.text] : []).join('\n')
  })
}

describe('a complete rejection lets the writer reconsider without re-reading', () => {
  it('shows the whole change and current token, then commits the modified reply without a read', async () => {
    const change = 'Windows install failed — hold the release until it is reproduced.'
    const { ctx, adapter, agent, memberId, threadRef, oldRevision, currentRevision } = await waitingThread(change)

    adapter.enqueue(toolCallResponse('old-token', 'team_message', { action: 'reply', threadRef, body: 'Publish it', baseRevision: oldRevision }))
    adapter.enqueue(toolCallResponse('new-token', 'team_message', { action: 'reply', threadRef,
      body: 'Paused the release; reproducing the Windows install failure.', baseRevision: currentRevision }))
    adapter.enqueue(textResponse('Paused and investigating.'))

    await waitFor(() => adapter.requests.length === 3 ? true : undefined)
    await agent.whenIdle()

    const results = toolResultTexts(agent)
    expect(results).toHaveLength(2)
    // 1. The old token is refused, but nothing is hidden: the complete change
    // and the current revision arrive in the same tool result.
    expect(results[0]).toContain('Not committed — unread_required.')
    expect(results[0]).toContain(change)
    expect(results[0]).toContain(`Next write — baseRevision: ${currentRevision}`)
    // 2. The next model step sees that result as ordinary context.
    expect(JSON.stringify(adapter.requests[1]!.messages)).toContain(change)
    expect(JSON.stringify(adapter.requests[1]!.messages)).toContain('Next write — baseRevision')
    // 3. The modified reply commits even though the change was never read and
    // remains unread: the exemption is the surface, not a durable read.
    expect(results[1]).toContain('Committed — reply added.')
    expect(results[1]).not.toContain('unread_required')

    const unread = ctx.agentTeam['ledger']!.notificationFacts(memberId).flatMap(entry => entry.facts)
    expect(unread.some(entry => entry.fact.kind === 'message' && entry.fact.message.body === change)).toBe(true)
  })
})

describe('an incomplete rejection never implies a direct write', () => {
  it('bounds an oversized change and keeps the next write refused until the Thread is read', async () => {
    const change = 'Windows install failed. '.repeat(500)
    const { ctx, adapter, agent, memberId, threadRef, oldRevision, currentRevision } = await waitingThread(change)

    adapter.enqueue(toolCallResponse('old-token', 'team_message', { action: 'reply', threadRef, body: 'Publish it', baseRevision: oldRevision }))
    adapter.enqueue(toolCallResponse('current-token', 'team_message', { action: 'reply', threadRef,
      body: 'Publish after the failure', baseRevision: currentRevision }))
    adapter.enqueue(textResponse('Reading the Thread instead.'))

    await waitFor(() => adapter.requests.length === 3 ? true : undefined)
    await agent.whenIdle()

    const results = toolResultTexts(agent)
    expect(results[0]).toContain('Not committed — unread_required.')
    expect(results[0]).toContain('Only 1 of 1 new fact(s)')
    expect(results[0]).toContain('the full change is not shown')
    expect(results[0]).not.toContain('Next write — baseRevision')
    expect(results[0]).toContain('No write token is provided')
    // The current token alone does not pass: the body is still not fully on the
    // surface, so the gate refuses again.
    expect(results[1]).toContain('Not committed — unread_required.')

    const unread = ctx.agentTeam['ledger']!.notificationFacts(memberId).flatMap(entry => entry.facts)
    // Two refusals wrote no read state: the gated change is still durable unread.
    expect(unread.some(entry => entry.fact.kind === 'message')).toBe(true)
  })
})

import assert from 'node:assert/strict'
import { execFileSync } from 'node:child_process'
import { mkdtemp, mkdir, rm, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { pathToFileURL } from 'node:url'
import { Context } from '@deepseek-ai/cordis'
import { agentEvents, type Agent } from '@deepseek-ai/dsh-agent'
import { createUserMessage } from '@deepseek-ai/dsh-llm'
import { Session, SessionId, SessionSeq } from '@deepseek-ai/dsh-session'
import * as current from '../../../../packages/agent-team/src/member-context.ts'

const root = resolve(import.meta.dirname, '../../../..')
const local = join(root, '.scratch/local/agent-context-implementation')
await mkdir(local, { recursive: true })
const priorPath = join(local, 'member-context-before.mts')
const priorSource = execFileSync('git', ['show', 'deaa671:packages/agent-team/src/member-context.ts'], { cwd: root, encoding: 'utf8' })
await writeFile(priorPath, priorSource.replace(/from '(\.\/[^']+)'/g,
  (_match, specifier: string) => `from '${pathToFileURL(resolve(root, 'packages/agent-team/src', specifier)).href}'`))
const prior = await import(pathToFileURL(priorPath).href) as typeof current
const memory = await mkdtemp(join(tmpdir(), 'team-context-scenario-'))
const indexV1 = 'Synthetic index v1\n' + 'Reference: notes/install.md\n'.repeat(250)
const indexV2 = indexV1.replace('index v1', 'index v2')

async function run(plugin: typeof current) {
  const ctx = new Context()
  const session = Session.create(SessionId('session:context-scenario'))
  const agent = { id: session.id, ctx, session, status: 'idle' } as Agent
  let owned: { projectRef: string; name: string; workspaceId: string }[] = []
  const rows: { stage: string; messages: number; emittedCharacters: number; indexCopies: number; surfaceCharacters: number }[] = []
  ctx.provide('agentTeam', {
    memberForAgent: (subject: Agent) => subject === agent
      ? { memberId: 'member:fixture', privateMemoryPath: memory, handle: 'Fixture', description: 'synthetic Member' }
      : undefined,
    ownedProjectsForAgent: () => owned,
    workspacesForAgent: () => [{ workspaceId: 'workspace:fixture', path: '/synthetic/workspace', default: true }],
  } as never)
  plugin.apply(ctx)
  async function step(stage: string) {
    const decision = await agentEvents(ctx, agent).waterfall('agent/pre-step', {
      messages: [], turn: 1, step: rows.length + 1, signal: new AbortController().signal,
    }, async () => ({ kind: 'enter' as const, messages: [] }))
    assert.equal(decision.kind, 'enter')
    if (decision.kind !== 'enter') throw new Error('unexpected rejected step')
    const texts = decision.messages.flatMap(message => message.content.flatMap(block => block.type === 'text' ? [block.text] : []))
    for (const message of decision.messages) session.append('user/message', message, { surfaceOp: 'append' })
    const surfaceText = session.deriveMessages().flatMap(message => message.content.flatMap(block => block.type === 'text' ? [block.text] : [])).join('')
    rows.push({ stage, messages: decision.messages.length, emittedCharacters: texts.join('').length,
      indexCopies: texts.filter(text => text.includes('Reference: notes/install.md\n'.repeat(250))).length,
      surfaceCharacters: surfaceText.length })
  }
  try {
    await writeFile(join(memory, 'memory.md'), indexV1)
    await step('start')
    await step('unchanged')
    await writeFile(join(memory, 'memory.md'), indexV2)
    await step('memory-update')
    await step('unchanged-after-update')
    owned = [{ projectRef: 'project:fixture', name: 'Fixture', workspaceId: 'workspace:fixture' }]
    await step('ownership-grant')
    const nodes = session.surface.nodes
    session.append('user/message', createUserMessage({ content: [{ type: 'text', text: 'Synthetic compaction summary.' }], source: { kind: 'human' } }), {
      surfaceOp: { op: 'replace', startSeq: SessionSeq(nodes[0]!), endSeq: SessionSeq(nodes.at(-1)!) },
      sourceEventSeqs: [...nodes],
    })
    await step('compaction-recovery')
    await step('unchanged-after-recovery')
    return rows
  } finally {
    await ctx.fiber.dispose()
  }
}

try {
  const before = await run(prior)
  const after = await run(current)
  assert.deepEqual(after.map(row => row.messages), [4, 0, 1, 0, 1, 4, 0])
  assert.deepEqual(after.map(row => row.indexCopies), [1, 0, 0, 0, 0, 1, 0])
  assert.deepEqual(before.map(row => row.indexCopies), [1, 0, 1, 0, 1, 1, 0])
  console.log(JSON.stringify({ fixtureMemoryBytes: Buffer.byteLength(indexV1), baseline: 'deaa671', before, after,
    note: 'One synthetic Session per implementation. Characters are UTF-16 code units, not tokens or cost; surface excludes fixed prompt and tools.' }, null, 2))
} finally {
  await rm(memory, { recursive: true, force: true })
  await rm(priorPath)
}

import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { isAgentTeamSource } from './context-source.ts'
import type { AgentTeamMemberId, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types.ts'

/**
 * Whether one unread Thread Message is already on its Member's model-visible surface, in full.
 *
 * The write gate refuses writes while unread work exists, but a complete notification or a complete tool result delivers the Message; refusing only costs a round-trip. The probe is narrow because a false positive lets through a write the model was never ready to make: it binds the exact Thread and Message refs, then requires the body itself to be present. Count-only notices, summaries, model-authored text, same text from another Thread, and bodies kept only in `meta` after the content was pruned never match. Reads a live Session only; no ledger state.
 */

/** The notice's own truncation marker, which means the body was cut. */
export const NOTIFICATION_TRUNCATION_MARKER = '[Message body truncated; use team_thread read for the full Message.]'

/** Body budget of one notice before it is cut and marked; the writer and the full-delivery check must agree on it and on the mark. */
export const NOTIFICATION_BODY_MAX_CHARACTERS = 8 * 1024

/** The private `tool/result` meta field that binds a rendered result to the Thread facts it shows. Written by the Team tools only; content still has to carry the body. */
const FACT_SURFACE_META = 'agent-team/thread-facts'

/** One model-visible surface entry that can attest a Thread Message. */
type VisibleTeamSurfaceEntry =
  | { readonly kind: 'notice'; readonly text: string }
  | { readonly kind: 'tool-result'; readonly text: string; readonly surface: RenderedFactSurface }

/** One Message identity a Team tool result claims to have rendered. */
interface RenderedMessageIdentity {
  readonly messageRef: string
  readonly bodyLength: number
}

interface RenderedFactSurface {
  readonly threadRef: string
  readonly messages: readonly RenderedMessageIdentity[]
}

/**
 * The projected text of every Team-authored notice and every Team tool result on this agent's surface, newest first.
 *
 * `surface.nodes` holds SessionSeq values while `snapshotEvents` takes SessionLogOffsets; they line up only through the seq = log.length contiguity contract, so the conversion goes through the validating constructor. The content comes from `deriveEventMessage`, which applies message projections (compaction and pruning); reading the raw event would miss a rewrite that removed the body.
 */
export function visibleTeamSurface(agent: Agent): readonly VisibleTeamSurfaceEntry[] {
  const entries: VisibleTeamSurfaceEntry[] = []
  for (const sequence of agent.session.surface.nodes.toReversed()) {
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event === undefined) continue
    const message = agent.session.deriveEventMessage(event)
    if (message === null) continue
    if (event.type === 'user/message') {
      const source = message.source
      if (!isAgentTeamSource(source)) continue
      if (source.form !== 'notice') continue
      entries.push({ kind: 'notice', text: textOf(message.content) })
      continue
    }
    if (event.type !== 'tool/result') continue
    const surface = renderedFactSurfaceOf((event.data as { readonly meta?: unknown }).meta)
    if (surface === undefined) continue
    entries.push({ kind: 'tool-result', text: textOf(message.content), surface })
  }
  return entries
}

/** The text blocks of one message, in order; a rendered body always lives inside one block. */
function textOf(content: readonly { readonly type: string; readonly text?: string }[]): string {
  return content.flatMap(part => part.type === 'text' && part.text !== undefined ? [part.text] : []).join('\n')
}

/**
 * Whether one unread fact's body is on the surface in full, bound to this Thread and Message.
 *
 * Notification text carries explicit `Thread:` and `Message ref:` lines beside the body. A Team tool result carries the same identity in its private meta, while the body must still be in the projected content; that is what separates a complete result from one whose content a pruner replaced while leaving meta intact.
 */
export function isFactOnSurface(entries: readonly VisibleTeamSurfaceEntry[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
  if (fact.fact.kind !== 'message') return false
  const body = fact.fact.message.body
  if (body === '') return false
  const messageRef = fact.fact.message.messageRef
  return entries.some(entry => entry.kind === 'notice'
    ? noticeAttests(entry.text, threadRef, messageRef, body)
    : toolResultAttests(entry.text, entry.surface, threadRef, messageRef, body))
}

/** Whether one direct-mention block names both refs and then carries the body at its own `Message:` position, uncut. */
function noticeAttests(text: string, threadRef: string, messageRef: string, body: string): boolean {
  const marker = 'Direct Team mention\n'
  for (let start = text.indexOf(marker); start !== -1; start = text.indexOf(marker, start + 1)) {
    const headerEnd = text.indexOf('\nMessage: ', start)
    if (headerEnd === -1) continue
    const header = text.slice(start, headerEnd)
    if (!hasLine(header, 'Thread', threadRef) || !hasLine(header, 'Message ref', messageRef)) continue
    const bodyStart = headerEnd + '\nMessage: '.length
    if (!text.startsWith(body, bodyStart)) continue
    const rest = text.slice(bodyStart + body.length)
    if (rest.startsWith(`\n${NOTIFICATION_TRUNCATION_MARKER}`)) continue
    if (rest !== '' && !rest.startsWith('\n')) continue
    return true
  }
  return false
}

function hasLine(block: string, label: string, value: string): boolean {
  return block.split('\n').includes(`${label}: ${value}`)
}

/** A tool result attests only when its meta names this Thread and Message and the projected content still carries the full body. */
function toolResultAttests(text: string, surface: RenderedFactSurface, threadRef: string, messageRef: string, body: string): boolean {
  if (surface.threadRef !== threadRef) return false
  const identity = surface.messages.find(message => message.messageRef === messageRef)
  if (identity === undefined || identity.bodyLength !== body.length) return false
  return bodyAtLineBoundary(text, body)
}

/** Whether the body is present as a whole rendered segment, not as a prefix of a longer body or a fragment inside one. */
function bodyAtLineBoundary(text: string, body: string): boolean {
  for (let at = text.indexOf(body); at !== -1; at = text.indexOf(body, at + 1)) {
    const before = at === 0 ? '\n' : text[at - 1]!
    const afterIndex = at + body.length
    const after = afterIndex === text.length ? '\n' : text[afterIndex]!
    if ((before === '\n' || before === ' ') && after === '\n') return true
  }
  return false
}

/** Parse and validate one tool result's private fact binding; malformed or foreign meta binds nothing. */
function renderedFactSurfaceOf(meta: unknown): RenderedFactSurface | undefined {
  if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) return undefined
  const record = meta as Record<string, unknown>
  if (record['surface'] !== FACT_SURFACE_META || typeof record['threadRef'] !== 'string' || typeof record['messages'] !== 'string') return undefined
  let parsed: unknown
  try {
    parsed = JSON.parse(record['messages'])
  } catch {
    return undefined
  }
  if (!Array.isArray(parsed)) return undefined
  const messages: RenderedMessageIdentity[] = []
  for (const entry of parsed) {
    if (typeof entry !== 'object' || entry === null) return undefined
    const message = entry as Record<string, unknown>
    if (typeof message['messageRef'] !== 'string' || typeof message['bodyLength'] !== 'number') return undefined
    messages.push({ messageRef: message['messageRef'], bodyLength: message['bodyLength'] })
  }
  return { threadRef: record['threadRef'], messages }
}

export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
  return (memberId: AgentTeamMemberId, fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean => {
    const agent = agentFor(memberId)
    if (agent === undefined) return false
    return isFactOnSurface(visibleTeamSurface(agent), fact, threadRef)
  }
}

