import { formatTeamTimestamp } from '@contexera/dsh-agent-team/time-format'
import type { AgentTeamMainStreamStanding, AgentTeamMainTimelineEntry } from '@contexera/dsh-agent-team/types'

/** Model-facing view of one Main stream entry: the Host's timeline entry with identities as plain strings. */
export interface MainEntryView {
  readonly sequence: number
  readonly kind: string
  readonly occurredAt: string
  readonly unread: boolean
  readonly direct: boolean
  readonly sender?: string
  readonly messageRef?: string
  readonly body?: string
  readonly mentions?: string[]
  readonly replyToMessageRef?: string
  readonly replyTo?: { readonly sender: string; readonly excerpt: string }
  readonly activity?: string
  readonly actor?: string
  readonly memberId?: string
  readonly threadRef?: string
  readonly preview?: string
  readonly taskRef?: string
  readonly taskNumber?: number
  readonly status?: string
  readonly resolution?: string
  readonly accountable?: string
  readonly replyCount?: number
  readonly participants?: string[]
  readonly liveClaimOwners?: string[]
}

export const MAIN_ENTRY_SCHEMA = {
  type: 'object', additionalProperties: false, properties: {
    sequence: { type: 'number', required: true }, kind: { type: 'string', required: true }, occurredAt: { type: 'string', required: true },
    unread: { type: 'boolean', required: true }, direct: { type: 'boolean', required: true },
    sender: { type: 'string' }, messageRef: { type: 'string' }, body: { type: 'string' }, mentions: { type: 'array', items: { type: 'string' } },
    replyToMessageRef: { type: 'string' },
    replyTo: { type: 'object', additionalProperties: false, properties: { sender: { type: 'string', required: true }, excerpt: { type: 'string', required: true } } },
    activity: { type: 'string' }, actor: { type: 'string' }, memberId: { type: 'string' },
    threadRef: { type: 'string' }, preview: { type: 'string' }, taskRef: { type: 'string' }, taskNumber: { type: 'number' },
    status: { type: 'string' }, resolution: { type: 'string' }, accountable: { type: 'string' }, replyCount: { type: 'number' },
    participants: { type: 'array', items: { type: 'string' } }, liveClaimOwners: { type: 'array', items: { type: 'string' } },
  },
} as const

export const MAIN_STANDING_SCHEMA = {
  type: 'object', additionalProperties: false, properties: {
    following: { type: 'boolean', required: true }, head: { type: 'number', required: true },
    unreadCount: { type: 'number', required: true }, directCount: { type: 'number', required: true },
  },
} as const

export function mainEntryView(entry: AgentTeamMainTimelineEntry): MainEntryView {
  const flags = { sequence: entry.sequence, occurredAt: entry.occurredAt, unread: entry.unread, direct: entry.direct }
  if (entry.kind === 'message') {
    const { message } = entry
    return { ...flags, kind: 'message', sender: message.sender, messageRef: message.messageRef, body: message.body, mentions: [...entry.mentions],
      ...(message.replyToMessageRef === undefined ? {} : { replyToMessageRef: message.replyToMessageRef }),
      ...(entry.replyTo === undefined ? {} : { replyTo: { sender: entry.replyTo.sender, excerpt: entry.replyTo.excerpt } }) }
  }
  if (entry.kind === 'activity') {
    return { ...flags, kind: 'activity', activity: entry.activity.kind, actor: entry.activity.actor, memberId: entry.activity.memberId }
  }
  const { card } = entry
  return { ...flags, kind: 'thread-card', threadRef: card.threadRef, preview: card.anchor.preview, sender: card.anchor.sender,
    replyCount: card.replyCount, participants: card.participants.map(actor => actor.name),
    ...(card.task === undefined ? {} : { taskRef: card.task.taskRef, taskNumber: card.task.taskNumber, status: card.task.status,
      resolution: card.task.resolution, accountable: card.task.accountable, liveClaimOwners: card.task.liveClaimOwners.map(actor => actor.name) }) }
}

export function standingView(standing: AgentTeamMainStreamStanding): { following: boolean; head: number; unreadCount: number; directCount: number } {
  return { following: standing.following, head: standing.head, unreadCount: standing.unreadCount, directCount: standing.directCount }
}

function markers(entry: MainEntryView): string {
  return entry.direct ? ' [direct]' : entry.unread ? ' [unread]' : ''
}

/** One rendered Main stream line; a Thread card names the Thread to read and its current state, never a transition. */
export function mainEntryLine(entry: MainEntryView): string {
  const at = ` ${formatTeamTimestamp(entry.occurredAt)}`
  if (entry.kind === 'message') {
    const replies = entry.replyToMessageRef === undefined ? ''
      : entry.replyTo === undefined ? ` (replies to ${entry.replyToMessageRef})` : ` (replies to @${entry.replyTo.sender} — "${entry.replyTo.excerpt}")`
    return `${entry.sequence}${at} [${entry.sender}]${markers(entry)}${replies} ${entry.messageRef} ${entry.body}`
  }
  if (entry.kind === 'activity') {
    return `${entry.sequence}${at} ${entry.actor} ${entry.activity === 'owner-added' ? 'made' : 'removed'} ${entry.memberId} ${entry.activity === 'owner-added' ? 'an owner' : 'as an owner'}${markers(entry)}`
  }
  const subject = entry.taskRef === undefined
    ? `Discussion ${entry.threadRef}`
    : `Task ${entry.taskRef} (#${entry.taskNumber}), ${entry.status}/${entry.resolution}${entry.accountable === undefined ? '' : `, accountable ${entry.accountable}`}${entry.liveClaimOwners === undefined || entry.liveClaimOwners.length === 0 ? '' : ` — working: ${entry.liveClaimOwners.join(', ')}`}`
  return `${entry.sequence}${at} [thread card]${markers(entry)} ${subject} — ${entry.preview} · ${entry.threadRef} · ${entry.replyCount} repl${entry.replyCount === 1 ? 'y' : 'ies'} · by ${(entry.participants ?? []).join(', ')}`
}

import { createHash } from 'node:crypto'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { isAgentTeamSource } from './context-source.ts'
import type { AgentTeamMemberId, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types.ts'

export const NOTIFICATION_TRUNCATION_MARKER = '[Message body truncated; use team_thread read for the full Message.]'
export const NOTIFICATION_BODY_MAX_CHARACTERS = 8 * 1024

export type ThreadMessageSurface = {
  readonly textDigest: string
  readonly messages: readonly { readonly threadRef: string; readonly messageRef: string; readonly bodyDigest: string }[]
}

export interface RenderedThreadMessage {
  readonly threadRef: string
  readonly messageRef: string
  readonly body: string
}

const digest = (text: string): string => createHash('sha256').update(text).digest('hex')

/** Bind only messages the producer rendered in full, to the exact text it emitted. */
export function threadMessageSurface(text: string, messages: readonly RenderedThreadMessage[]) {
  return { textDigest: digest(text), messages: messages.map(message => ({
    threadRef: message.threadRef, messageRef: message.messageRef, bodyDigest: digest(message.body),
  })) }
}

/** A live projection, not a read receipt. Cropped text cannot attest through retained metadata. */
export function visibleTeamSurface(agent: Pick<Agent, 'session'>): readonly ThreadMessageSurface[] {
  const entries: ThreadMessageSurface[] = []
  for (const sequence of agent.session.surface.nodes) {
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event === undefined) continue
    const message = agent.session.deriveEventMessage(event)
    if (message === null) continue
    let binding: unknown
    if (event.type === 'user/message' && message.role === 'user' && isAgentTeamSource(message.source) && message.source.form === 'notice') {
      binding = message.source.threadFacts
    } else if (event.type === 'tool/result' && message.role === 'tool' && !message.isError) {
      const ownCall = event.sourceEventSeqs?.some(sequence => {
        const call = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
        return call?.type === 'tool/call' && call.data.callId === message.toolCallId
          && (call.data.name === 'team_thread' || call.data.name === 'team_message' || call.data.name === 'team_task')
      })
      if (!ownCall) continue
      const meta = event.data.meta
      if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) continue
      binding = meta['threadFacts']
    }
    const surface = surfaceOf(binding)
    if (surface === undefined || message.content.some(part => part.type !== 'text')) continue
    const text = message.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n')
    if (digest(text) === surface.textDigest) entries.push(surface)
  }
  return entries
}

function surfaceOf(value: unknown): ThreadMessageSurface | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const surface = value as Partial<ThreadMessageSurface>
  if (typeof surface.textDigest !== 'string' || !Array.isArray(surface.messages)) return undefined
  if (!surface.messages.every(message => message !== null && typeof message === 'object'
    && typeof message.threadRef === 'string' && typeof message.messageRef === 'string' && typeof message.bodyDigest === 'string')) return undefined
  return surface as ThreadMessageSurface
}

export function isFactOnSurface(entries: readonly ThreadMessageSurface[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
  if (fact.fact.kind !== 'message' || fact.fact.message.body === '') return false
  const { messageRef, body } = fact.fact.message
  const bodyDigest = digest(body)
  return entries.some(entry => entry.messages.some(message => message.threadRef === threadRef
    && message.messageRef === messageRef && message.bodyDigest === bodyDigest))
}

export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
  return (memberId: AgentTeamMemberId, facts: readonly AgentTeamThreadReadFact[], threadRef: AgentTeamThreadRef): boolean => {
    const agent = agentFor(memberId)
    if (agent === undefined) return false
    const entries = visibleTeamSurface(agent)
    return facts.every(fact => isFactOnSurface(entries, fact, threadRef))
  }
}

/**
 * Producer-attributed message sources for Agent Team context management.
 *
 * Messages are ordinary `UserMessage`s under this plugin's producer kind with the `snapshot` context form, the shape Session format V4 admits. The handoff envelope and checkpoint correlation travel as named {@link ContextSnapshotSection}s. The validators here are the only place that recognizes these messages; callers never match on body text.
 * @module @contexera/dsh-agent-team/context-source
 */

import type { ContextFormed, ContextSnapshotSection, MessageSource, UserMessage } from '@deepseek-ai/dsh-llm'
import type { ThreadMessageSurface } from './surface-visibility.ts'

/** The producer kind attributing every Agent Team message source. */
export const AGENT_TEAM_PLUGIN_ID = '@wowyuarm/dsh-agent-team'

/** Kind the Harness's V4 read-time conversion gives this plugin's released V3 `plugin` sources: `plugin:` + producer id, payload fields preserved. */
export const AGENT_TEAM_V3_RENAMED_KIND = `plugin:${AGENT_TEAM_PLUGIN_ID}`

declare module '@deepseek-ai/dsh-llm' {
  interface MessageSourceMap {
    /** The kind this plugin writes now; V4 admission requires a producer-owned kind. */
    [AGENT_TEAM_PLUGIN_ID]: { kind: typeof AGENT_TEAM_PLUGIN_ID; readonly threadFacts?: ThreadMessageSurface } & ContextFormed
    /** The converted shape of this plugin's released V3 history; read-side only. */
    [AGENT_TEAM_V3_RENAMED_KIND]: { kind: typeof AGENT_TEAM_V3_RENAMED_KIND; readonly threadFacts?: ThreadMessageSurface } & ContextFormed
  }
}

/** The source shapes carrying this plugin's attribution: its current kind and the read-time conversion of its V3 history. */
export type AgentTeamMessageSource = Extract<MessageSource, { kind: typeof AGENT_TEAM_PLUGIN_ID | typeof AGENT_TEAM_V3_RENAMED_KIND }>

/** The kind the read-time conversion renames one producer's released V3 sources into. */
export const v3RenamedSourceKind = <const P extends string>(producer: P): `plugin:${P}` => `plugin:${producer}`

/** Whether a source kind is a producer's own, by exact equality on its current or V3-converted kind; a `plugin:` prefix test would claim third-party rows. */
export function matchesProducerKind(kind: string | undefined, producer: string): boolean {
  return kind === producer || kind === v3RenamedSourceKind(producer)
}

/** Whether one message source carries this plugin's own attribution. */
export function isAgentTeamSource(source: MessageSource): source is AgentTeamMessageSource {
  return matchesProducerKind(source.kind, AGENT_TEAM_PLUGIN_ID)
}

/** Handoff snapshot section name carrying the model-authored prose. */
export const HANDOFF_SECTION_NAME = 'HANDOFF'

/** Stable section name marking a checkpoint continuation and carrying its ref. */
export const CHECKPOINT_SECTION_NAME = 'Checkpoint'

/**
 * The rollover handoff envelope: the model-authored prose plus the verifiable
 * Host facts, all as named snapshot contributions.
 */
export interface AgentTeamContextHandoff {
  /** The Member's Session before this rollover. */
  readonly previousSessionId: string
  /** The rollover generation this handoff opened. */
  readonly newSessionId: string
  /** Why the rollover happened. */
  readonly trigger: 'model' | 'pressure'
  /** Seq of the retired rollover tool result in the previous Session log. */
  readonly handoffEventSeq: number
  /** The checkpoint a return was seeded from; absent on a fresh rollover. */
  readonly checkpointRef?: string
  /** Workspace paths the handoff called out as relevant. */
  readonly relatedFiles?: readonly string[]
  /** Named contributions, starting with the model-authored handoff prose. */
  readonly sections: readonly ContextSnapshotSection[]
}

/** This message's snapshot sections when it is this plugin's own snapshot, else `undefined`. */
function ownSections(message: UserMessage): readonly ContextSnapshotSection[] | undefined {
  const source = message.source
  if (!isAgentTeamSource(source)) return undefined
  if (source.form !== 'snapshot') return undefined
  return source.sections
}

/** The text of one named section, or undefined when it is absent. */
function sectionText(sections: readonly ContextSnapshotSection[], name: string): string | undefined {
  return sections.find(section => section.name === name)?.text
}

/** Decodes the `Related files` section: a JSON path array (safe for paths containing commas), falling back to the legacy `', '`-joined split for older generations. */
function parseRelatedFiles(text: string): readonly string[] {
  try {
    const parsed: unknown = JSON.parse(text)
    if (Array.isArray(parsed) && parsed.every(path => typeof path === 'string' && path.length > 0)) {
      return parsed as readonly string[]
    }
  } catch {
    // Not JSON: the section predates the JSON encoding.
  }
  return text.split(', ').filter(path => path.length > 0)
}

/** The rollover handoff a message carries, or `undefined`. */
export function handoffOf(message: UserMessage): AgentTeamContextHandoff | undefined {
  const sections = ownSections(message)
  if (sections === undefined) return undefined
  const handoff = sectionText(sections, HANDOFF_SECTION_NAME)
  if (handoff === undefined) return undefined
  const previousSessionId = sectionText(sections, HANDOFF_PREVIOUS_SESSION)
  const newSessionId = sectionText(sections, HANDOFF_NEW_SESSION)
  const trigger = sectionText(sections, HANDOFF_TRIGGER)
  const handoffEventSeq = sectionText(sections, HANDOFF_EVENT_SEQ)
  if (previousSessionId === undefined || newSessionId === undefined) return undefined
  if (trigger !== 'model' && trigger !== 'pressure') return undefined
  const seq = Number(handoffEventSeq)
  if (handoffEventSeq === undefined || !Number.isSafeInteger(seq)) return undefined
  const checkpointRef = sectionText(sections, HANDOFF_CHECKPOINT)
  const relatedFiles = sectionText(sections, HANDOFF_RELATED_FILES)
  return {
    previousSessionId,
    newSessionId,
    trigger,
    handoffEventSeq: seq,
    ...(checkpointRef === undefined ? {} : { checkpointRef }),
    ...(relatedFiles === undefined ? {} : { relatedFiles: parseRelatedFiles(relatedFiles) }),
    sections,
  }
}

export function continuationCheckpointRefOf(message: UserMessage): string | undefined {
  const sections = ownSections(message)
  if (sections === undefined || sections.length !== 1) return undefined
  const ref = sectionText(sections, CHECKPOINT_SECTION_NAME)
  return ref === undefined || ref.length === 0 ? undefined : ref
}

/** Whether one user message is a rollover handoff snapshot. */
export function isHandoffMessage(message: UserMessage): boolean {
  return handoffOf(message) !== undefined
}

/** Whether one user message is a checkpoint continuation, optionally for one checkpoint. */
export function isCheckpointContinuationMessage(message: UserMessage, checkpointRef?: string): boolean {
  const ref = continuationCheckpointRefOf(message)
  return ref !== undefined && (checkpointRef === undefined || ref === checkpointRef)
}

export function isAgentTeamContextSource(message: UserMessage): boolean {
  return isHandoffMessage(message) || isCheckpointContinuationMessage(message)
}

/** Envelope section names; stable because they are read back from the log. */
export const HANDOFF_PREVIOUS_SESSION = 'Previous session'
export const HANDOFF_NEW_SESSION = 'New session'
export const HANDOFF_TRIGGER = 'Trigger'
export const HANDOFF_EVENT_SEQ = 'Handoff event seq'
export const HANDOFF_CHECKPOINT = 'Continued from checkpoint'
export const HANDOFF_RELATED_FILES = 'Related files'

