async changeTaskForAgent(agent: Agent, request: AgentTeamTaskRequest): Promise<AgentTeamTaskResult> {
  const actor = this.memberCall(agent, request.workspaceId)
  const result = await this.requireLedger().changeTask({ ...request, actor })
  this.emitCommittedOutcome(result)
  return result.value
}

/** Agent-only accountability transfer to another Project owner or the Human. */
async transferTaskForAgent(agent: Agent, request: AgentTeamTransferTaskRequest): Promise<AgentTeamTransferTaskResult> {
  const actor = this.memberCall(agent, request.workspaceId)
  const result = await this.requireLedger().transferTask({ ...request, actor })
  this.emitCommittedOutcome(result)
  return result.value
}

taskBoardForAgent(agent: Agent, request: Omit<AgentTeamTaskBoardRequest, 'workspaceId'> & { readonly workspaceId?: WorkspaceId }): AgentTeamTaskBoard {
  const actor = this.memberActor(agent)
  if (request.workspaceId === undefined) return this.requireLedger().memberTaskBoard(actor, request)
  this.requireAgentWorkspace(actor, request.workspaceId)
  return this.requireLedger().taskBoard(actor, { ...request, workspaceId: request.workspaceId })
}

inboxForAgent(agent: Agent, request: { readonly workspaceId?: WorkspaceId; readonly limit?: number }): AgentTeamInbox {
  this.scheduleTaskReminderEvaluation()
  const actor = this.memberActor(agent)
  if (request.workspaceId === undefined) return this.requireLedger().memberInbox(actor, request)
  this.requireAgentWorkspace(actor, request.workspaceId)
  return this.requireLedger().inbox(actor, { ...request, workspaceId: request.workspaceId })
}

async readThreadForAgent(agent: Agent, request: AgentTeamThreadReadRequest): Promise<AgentTeamThreadReadResult & { readonly visibleMessageRefs: readonly AgentTeamMessageRef[] }> {
  const actor = this.memberCall(agent, request.workspaceId)
  const result = await this.requireLedger().readThread({ ...request, actor })
  const surface = visibleTeamSurface(agent)
  // A read that made no progress commits no operation and carries no receipt.
  const receipt = result.committed ? result.value.receipt : undefined
  if (receipt !== undefined) this.emitCommitted(receipt)
  const snapshot = result.value
  const unread = snapshot.facts.filter(entry => entry.unread)
  const history = this.requireLedger().threadHistory(actor, { ...request,
    beforeSequence: unread[0]?.fact.sequence ?? snapshot.thread.revision + 1, limit: 4 })
  const anchor = { fact: { kind: 'message' as const, sequence: snapshot.anchor.sequence, message: snapshot.anchor,
    mentions: snapshot.anchorMentions, occurredAt: snapshot.anchor.occurredAt }, unread: false, direct: false }
  const background = [anchor, ...history.facts.filter(fact => fact.kind === 'message')
    .map(fact => ({ fact, unread: false, direct: false }))]
    .filter((entry, index, entries) => !unread.some(item => item.fact.sequence === entry.fact.sequence)
      && entries.findIndex(item => item.fact.sequence === entry.fact.sequence) === index
      && !isFactOnSurface(surface, entry, snapshot.thread.threadRef))
  const facts = [...background, ...unread].sort((left, right) => left.fact.sequence - right.fact.sequence)
  const read = this.withReplyContexts({ ...snapshot, facts }, request.workspaceId)
  if (receipt !== undefined) this.afterAcceptanceRead(agent, actor.memberId, read)
  const visibleMessageRefs = unread.flatMap(entry => entry.fact.kind === 'message'
    && isFactOnSurface(surface, entry, read.thread.threadRef) ? [entry.fact.message.messageRef] : [])
  return { ...read, visibleMessageRefs }
}

/**
 * A read that acknowledged the acceptance of work this Member contributed to hands the reader one reminder to write down what is durable,
 * and, above the acceptance budget, one compaction once the Agent settles. Priced from the committed read, never persisted, never reverses it.
 */
private afterAcceptanceRead(agent: Agent, memberId: AgentTeamMemberId, read: AgentTeamThreadReadResult): void {
  // A retiring Agent is about to be disposed; a reminder injected into its
  // Session would be discarded unread.
  if (this.retiringAgents.has(agent)) return
  const task = read.task
  if (task === undefined || task.resolution !== 'accepted' || task.status !== 'done') return
  if (!this.acceptedOwnWork(read, memberId)) return
  // One boundary per turn: several accepted reads in one turn must not queue
  // several identical reminders or race two compactions.
  if (this.acceptanceBoundaries.has(agent)) return
  this.acceptanceBoundaries.add(agent)
  const engine = this.compactionEngineFor(agent)
  const plan = planAcceptanceContext({ usageTokens: this.measureContext(agent), canCompact: engine !== undefined })
  try {
    agent.followup(createAcceptanceReminder(plan.action))
  } catch (error) {
    this.ctx.logger.warn(`agent-team: could not deliver the acceptance reminder to ${this.memberScope(memberId, agent.id)}: ${failureDetail(error)}`)

 * Threads that can hold unread facts for one reader, from the per-reader
 * derived indexes: Attention follows plus direct and activity markers.
 * Every unread source is covered — ordinary unread requires Attention, and
 * marker unread requires a marker — so no full Thread scan is needed.
 */
private inboxCandidateThreads(memberId: AgentTeamMemberId): Iterable<AgentTeamThreadRef> {
  const refs = new Set<AgentTeamThreadRef>()
  for (const source of [this.state.attentionThreadsByMember.get(memberId), this.state.directMarkersByMember.get(memberId), this.state.activityMarkersByMember.get(memberId), this.state.reminderMarkersByMember.get(memberId)]) {
    for (const threadRef of source?.keys() ?? []) refs.add(threadRef)
  }
  return refs
}

/** Model-visible notification material derived from the recipient's current durable unread state. */
notificationFacts(memberId: AgentTeamMemberId, request?: AgentTeamInboxRequest): readonly {
  readonly item: AgentTeamInboxItem
  readonly facts: readonly AgentTeamThreadReadFact[]
  readonly reminders: readonly import('./types/requests-results.ts').AgentTeamInboxReminder[]
}[] {
  const member = this.requireMember(memberId)
  if (request !== undefined && !this.participatesIn(memberId, request.workspaceId)) throw new Error('Member cannot inspect another Workspace')
  const actor = { kind: 'member' as const, memberId, handle: member.handle }
  const previous = this.notificationReadSet
  const readSet = { memberId, facts: new Map<AgentTeamThreadRef, readonly AgentTeamThreadReadFact[]>() }
  this.notificationReadSet = readSet
  try {
    const inbox = request === undefined ? this.memberInbox(actor, {}) : this.inbox(actor, request)
    return Object.freeze(inbox.items.map(item => Object.freeze({ item,
      facts: readSet.facts.get(item.thread.threadRef) ?? this.unreadFor(memberId, item.thread.threadRef), reminders: item.reminders })))
  } finally {
    this.notificationReadSet = previous
  }
}

/**
 * Answer what a read would return right now without committing or
 * acknowledging anything. The Host uses this to see the bounded batch it can
 * deliver before deciding which prefix it actually did deliver.
 */
previewThreadRead(request: AgentTeamAuthorizedThreadReadRequest): AgentTeamThreadReadResult {
  const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
  return this.readPicture(this.prepareRead(actor.memberId, request.workspaceId, request))
}

readThread(request: AgentTeamAuthorizedThreadReadRequest): Promise<AgentTeamThreadReadOutcome> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameThreadRead(existing, request)
      const current = this.prepareRead(existing.data.memberId, existing.data.workspaceId, request)
      return Object.freeze({ value: Object.freeze({ receipt: this.receipt(existing), ...this.readPicture(current) }), committed: false })
    }
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    const prepared = this.prepareRead(actor.memberId, request.workspaceId, request)
    // A read whose Inbox delta is empty writes nothing: the watermark does
    // not advance and no marker is consumed. It answers with the same picture
    // and no receipt, so the caller learns "no operation" from the result's
    // committed flag, never from a sequence this read did not write.
    if (isEmptyInboxDelta(prepared.inbox)) return Object.freeze({ value: this.readPicture(prepared), committed: false })
    // The record carries progress, not the picture: the Thread, its facts,
    // the anchor and the reader's Attention are projection state every replay
    // already holds.
    const data: AgentTeamThreadReadReceipt = Object.freeze({ workspaceId: request.workspaceId, memberId: actor.memberId,
      threadRef: prepared.thread.threadRef, ...(prepared.task === undefined ? {} : { taskRef: prepared.task.taskRef }),
      readThroughSequence: prepared.readThroughSequence,
      ...(prepared.selectedThroughSequence === undefined ? {} : { selectedThroughSequence: prepared.selectedThroughSequence }),

function repliesToClause(replyToMessageRef: string | undefined, replyTo: ReplyContextView | undefined): string {
  if (replyToMessageRef === undefined) return ''
  return replyTo === undefined
    ? ` (replies to ${replyToMessageRef})`
    : ` (replies to @${replyTo.sender} — "${replyTo.excerpt}")`
}

/** The one Host-read-fact → view projection, shared by a Thread read and by the facts a rejected write carries back, so the two surfaces cannot drift. */
function readFactView(entry: {
  readonly fact: AgentTeamThreadFact
  readonly unread: boolean
  readonly direct: boolean
}, bodyOmitted = false): FactView {
  return entry.fact.kind === 'message'
    ? { sequence: entry.fact.sequence, kind: 'message', messageRef: entry.fact.message.messageRef, body: entry.fact.message.body, sender: entry.fact.message.sender,
      ...(bodyOmitted ? { bodyOmitted: true } : {}),
      mentions: [...entry.fact.mentions],
      ...(entry.fact.message.replyToMessageRef === undefined ? {} : { replyToMessageRef: entry.fact.message.replyToMessageRef }),
      ...(entry.fact.replyTo === undefined ? {} : { replyTo: entry.fact.replyTo }),
      unread: entry.unread, direct: entry.direct, occurredAt: entry.fact.occurredAt }
    : activityFactView(entry.fact.sequence, entry.fact.activity, { unread: entry.unread, direct: entry.direct }, entry.fact.occurredAt)
}

/** One rendered fact line; markers are inline, never a separate ellipsis line. */
function factLine(fact: FactView): string {
  const at = fact.occurredAt === undefined ? '' : ` ${formatTeamTimestamp(fact.occurredAt)}`
  return fact.kind === 'message'
    ? `${fact.sequence}${at} [${fact.sender ?? 'unknown sender'}]${factMarkers(fact)}${repliesToClause(fact.replyToMessageRef, fact.replyTo)} ${fact.bodyOmitted ? `${fact.messageRef} — body already in current context; omitted.` : fact.body}`
    : `${activityLine(fact)}${at}${factMarkers(fact)}`
}

/** One collision-surface Claim line, shared by read and history-free listing. */
function claimLine(claim: { claimRef: string; owner: string; direction: string }): string {
  return `${claim.claimRef} — ${claim.owner}: ${claim.direction}`
}

function threadResult(
  kind: 'read' | 'history' | 'message',
  workspaceId: string,
  snapshot: Awaited<ReturnType<AgentTeam['readThreadForAgent']>> | ReturnType<AgentTeam['threadHistoryForAgent']>,
  attention: Awaited<ReturnType<AgentTeam['readThreadForAgent']>>['attention'],
  facts: FactView[],
  extra: { cursor?: number; hasMore?: boolean; readThroughSequence?: number; remainingUnreadCount?: number; earlierFactCount?: number; taskNumber?: number; taskCards?: TaskCardView[]; reminders?: AgentTeamInboxReminder[]; message?: { messageRef: string; sender: string; sequence: number; occurredAt?: string; body: string } } = {},
): { workspaceId: string; projectRef: string; anchor: { messageRef: string; sender: string; body: string; sequence: number; occurredAt?: string; replyToMessageRef?: string; replyTo?: ReplyContextView }; message?: { messageRef: string; sender: string; sequence: number; occurredAt?: string; body: string }; threadRef: string; revision: number; kind: string; following: boolean; taskRef?: string; status?: string; resolution?: string; taskNumber?: number; accountable?: string; readThroughSequence?: number; remainingUnreadCount?: number; earlierFactCount?: number; cursor?: number; hasMore?: boolean; taskCards?: TaskCardView[]; reminders?: AgentTeamInboxReminder[]; claims: ClaimView[]; facts: FactView[] } {
  return {
    workspaceId, projectRef: snapshot.anchor.projectRef,
    kind, threadRef: snapshot.thread.threadRef, revision: snapshot.thread.revision,
    ...(snapshot.task === undefined ? {} : { taskRef: snapshot.task.taskRef, status: snapshot.task.status, resolution: snapshot.task.resolution, accountable: snapshot.task.accountable }),
    ...(extra.taskNumber === undefined ? {} : { taskNumber: extra.taskNumber }),
    following: attention !== undefined,
    ...extra,
    ...(attention === undefined || extra.readThroughSequence !== undefined ? {} : { readThroughSequence: attention.readThroughSequence }),
    anchor: { messageRef: snapshot.anchor.messageRef, sender: snapshot.anchor.sender, body: snapshot.anchor.body, sequence: snapshot.anchor.sequence, occurredAt: snapshot.anchor.occurredAt, ...(snapshot.anchor.replyToMessageRef === undefined ? {} : { replyToMessageRef: snapshot.anchor.replyToMessageRef }), ...(snapshot.anchor.replyTo === undefined ? {} : { replyTo: snapshot.anchor.replyTo }) },
    claims: snapshot.claims.map(claimView),
    facts,
  }
}

/** A direct message is not a Thread fact: `dm` takes a Member ref and a body only (no Thread, Task, write token, or attachments). Sharing a pocket with `reply` would let a model hand a `threadRef` to a call with no Thread to address. A DM is a private note; shared work belongs in a Thread reply. */
const teamDm = defineTool({
  name: 'team_dm',
  description: 'Send one private direct message to a single enabled Agent Member in your Workspace. It takes a memberRef and a body and nothing else: no Thread, no Task, no write token, and no attachments, because a DM addresses a person rather than a conversation. Use it for quick clarifications and status syncs — never for task work, decisions, or anything that needs team visibility or traceability, which belongs in a Thread reply. If an exchange with the same Member runs past about three messages, move it to a Thread: every DM costs the recipient a full agent turn. A DM is recorded whether or not the recipient session could be woken, and the result says which happened; there is no automatic redelivery, so never blindly send a duplicate. The Human cannot be DMed.',
  parameters: {
    memberRef: { type: 'string', required: true, description: "Full branded Member ref exactly as returned by Team tools, including the 'member:' prefix. An unambiguous abbreviation of the first 6+ UUID hex characters also resolves. The Member must be an enabled Agent in your Workspace (the Human cannot be DMed)." },
    body: { type: 'string', required: true, description: "Markdown body. Lead with the conclusion or state. Mention the Human only when they must know or decide; when a decision is owed, say plainly what needs deciding and what happens by default if nobody answers — no fixed template. Keep it the shortest useful message for the recipient; mechanical detail follows below. Cite Team refs exactly as returned, as bare text with one colon (e.g. task:0f0a…) — never a double colon, never inside backticks or quotes. Unambiguous UUID abbreviations (first 6+ hex chars) also resolve." },

