const prepareBudget = async (proposed: LlmCallConfig, offered: readonly Message[], signal: AbortSignal): Promise<LlmCallConfig> => {
  signal.throwIfAborted()
  if (retiring()) throw new Error('agent-team: cannot prepare a request for a retiring Member')
  const request = { ...proposed }
  if (loggedClamp !== undefined && request.maxTokens === loggedClamp.applied) {
    if (loggedClamp.requested === undefined) delete request.maxTokens
    else request.maxTokens = loggedClamp.requested
  }
  preparedClamp = undefined
  const settings = config()
  if (!settings.enabled) return request
  const llm = ctx.get('llm')
  if (llm === undefined) throw new Error('agent-team: LLM runtime unavailable')
  let info: LlmResolvedModelInfo | undefined
  try {
    info = await llm.resolveModelInfo(request.provider, request.model, signal)
  } catch (error) {
    if (!(error instanceof LlmError) || error.code !== 'NO_ADAPTER') throw error
  }
  signal.throwIfAborted()
  const window = info?.context?.contextWindow
  const threshold = memberCompactionThreshold(settings.tokens, window)
  // A window that cannot hold the fixed reserve leaves this policy no room to
  // act; the Agent's own upstream limits still apply to the request.
  if (threshold === undefined) return request
  const measure = (): number => measureMemberInput(ctx, agent, request, offered, assembly)
  let inputTokens = measure()
  if (inputTokens >= threshold) {
    const engine = engineFor()
    if (engine === undefined) throw new Error('agent-team: Member reached its context budget without a compaction engine')
    const prune = (ctx.get('agentPresets')?.serviceFor(agent, 'toolResultPruner') as ToolResultPruner | undefined)
      ?? ctx.get('toolResultPruner')
    if (prune !== undefined) {
      try {
        prune.pruneSession(agent.session)
        inputTokens = measure()
      } catch {
        // Pruning is an optional saving, not a prerequisite: a failure must not
        // cost the step when the engine can still reduce the context itself.
      }
    }
    if (inputTokens >= threshold) {
      await engine.compactIfNeeded(agent, 'context-overflow', signal)
      signal.throwIfAborted()
      inputTokens = measure()
    }
    if (inputTokens >= threshold) {
      throw new Error(`agent-team: context still exceeds the Member budget after compaction (${inputTokens} >= ${threshold}); shorten the input or increase memberCompaction.tokens`)
    }
  }

import type { Context } from '@deepseek-ai/cordis'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { createSystemMessage, LlmError, type LlmCallConfig, type LlmResolvedModelInfo, type Message, type UserMessage } from '@deepseek-ai/dsh-llm'
import type { CompactionEngine } from '@deepseek-ai/dsh-compaction'
import type ToolResultPruner from '@deepseek-ai/dsh-compaction-tool-result-pruner'
import { renderPrompt, type PromptAssembly } from '@deepseek-ai/dsh-system-prompt'

export interface MemberCompactionConfig {
  readonly enabled: boolean
  readonly tokens: number
}

export const MEMBER_COMPACT_TOKENS = 256_000
const MEMBER_WINDOW_RATIO = 0.8
const MEMBER_CONTEXT_RESERVE = 16_384
const MEMBER_OUTPUT_RESERVE = 4_096
export const MEMBER_SUMMARY_TOKENS = 16_384

export const DEFAULT_MEMBER_COMPACTION: MemberCompactionConfig = Object.freeze({
  enabled: true,
  tokens: MEMBER_COMPACT_TOKENS,
})

export function memberCompactionThreshold(tokens: number, contextWindow: number | undefined): number | undefined {
  if (contextWindow === undefined) return tokens
  // A window this small cannot hold the fixed context reserve plus a minimal
  // output allowance: the trigger would fire on every request while no request
  // could fit, so the route is left to the Agent's own limits instead.
  if (contextWindow < MEMBER_CONTEXT_RESERVE + MEMBER_OUTPUT_RESERVE) return undefined
  return Math.floor(Math.min(tokens, contextWindow * MEMBER_WINDOW_RATIO, contextWindow - MEMBER_CONTEXT_RESERVE))
}

export function memberOutputTokens(inputTokens: number, contextWindow: number, requestedTokens: number | undefined): number {
  const available = Math.floor(contextWindow - inputTokens - MEMBER_OUTPUT_RESERVE)
  if (available < 1) throw new Error('agent-team: context leaves no safe output space after compaction')
  return Math.min(requestedTokens ?? available, available)
}

export function measureMemberInput(ctx: Context, agent: Agent, config: LlmCallConfig, pending: readonly Message[], assembly?: PromptAssembly): number {
  const meter = ctx.get('tokenMeter')
  if (meter === undefined) throw new Error('agent-team: token meter unavailable')
  const header = agent.session.requestHeader()
  const measurement = meter.measure(agent.session, {
    ...header,
    config,
    ...assembly === undefined ? {} : { tools: [...assembly.tools] },
  })
  let inputTokens = measurement.totalTokens + pending.reduce((sum, message) => sum + meter.estimateMessage(message), 0)
  if (assembly !== undefined) {
    const head = agent.session.surface.nodes[0]
    const event = head === undefined ? undefined : agent.session.eventAt(head)
    const previous = event?.type === 'system/message' ? meter.estimateMessage(event.data.message) : 0
    inputTokens += Math.max(0, meter.estimateMessage(createSystemMessage(renderPrompt(assembly))) - previous)
  }
  return inputTokens
}

export function installMemberCompaction(

    kind: 'session-reference',
    form: 'recall',
    version: 1,
    references: rendered.map((source, index) => ({
      sessionId: source.data.sessionId,
      label: source.data.label,
      capturedFormatVersion: source.capturedFormatVersion,
      capturedThroughSeq: source.data.capturedThroughSeq,
      ...source.stats,
      inputIndex: index,
    })),
  }
  const additionalContext: UserMessage = createUserMessage({
    source,
    content: [{ type: 'text', text: prompt }],
  })
  return { content: acceptedContent, additionalContext }
}

private async referenceBudget(agent: Agent, signal: AbortSignal | undefined): Promise<number> {
  if (this.config.maxReferenceBytes !== undefined) return this.config.maxReferenceBytes
  // Options seed direct preparation; an assembled route owns model-step preparation.
  const { provider, model } = this.assembledRoutes.get(agent) ?? agent.options
  const llm = this.ctx.get('llm')
  if (provider === undefined || model === undefined || llm === undefined) return DEFAULT_MAX_REFERENCE_BYTES
  let info: LlmResolvedModelInfo
  try {
    info = await settleWithCancellation(llm.resolveModelInfo(provider, model, signal), signal)
  } catch (error: unknown) {
    // Stream middleware can serve routes without a registered adapter.
    if (!(error instanceof LlmError) || error.code !== 'NO_ADAPTER') throw error
    return DEFAULT_MAX_REFERENCE_BYTES
  }
  if (info.context === undefined) return DEFAULT_MAX_REFERENCE_BYTES
  // Context capacity is in tokens; four bytes/token is a sizing heuristic, not token counting.
  return Math.max(DEFAULT_MAX_REFERENCE_BYTES, Math.floor(info.context.contextWindow * 4 * this.config.referenceContextFraction))
}

private renderSources(sources: readonly PreparedSource[], maxReferenceBytes: number): RenderedSource[] {
  const rendered: RenderedSource[] = []
  for (const source of sources) {
    const retained = retainReferencedSession(source.snapshot, source.input.label, maxReferenceBytes)
    if (retained === undefined) {
      throw new SessionReferenceError(
        'referenced session snapshot cannot fit the configured byte budget',
        'SESSION_REFERENCE_BUDGET_EXCEEDED',
      )

  return this.readPicture(this.prepareRead(actor.memberId, request.workspaceId, request))
}

readThread(request: AgentTeamAuthorizedThreadReadRequest, select?: (preview: AgentTeamThreadReadResult) => number): Promise<AgentTeamThreadReadOutcome> {
  return this.enqueue(async () => {
    const existing = this.state.byRequest.get(request.requestId)
    if (existing !== undefined) {
      this.assertSameThreadRead(existing, request)
      const current = this.prepareRead(existing.data.memberId, existing.data.workspaceId, request)
      return Object.freeze({ value: Object.freeze({ receipt: this.receipt(existing), ...this.readPicture(current) }), committed: false })
    }
    const actor = this.assertActorForWorkspace(request.actor, request.workspaceId)
    // Selection runs inside the queue against the state this write will
    // actually see, so a fact queued ahead of it is never skipped.
    const selectedThroughSequence = select === undefined
      ? request.selectedThroughSequence
      : select(this.previewThreadRead({ ...request, actor }))
    const prepared = this.prepareRead(actor.memberId, request.workspaceId, { ...request, selectedThroughSequence })
    // A read whose Inbox delta is empty writes nothing: the watermark does
    // not advance and no marker is consumed. It answers with the same picture
    // and no receipt, so the caller learns "no operation" from the result's
    // committed flag, never from a sequence this read did not write.
    if (isEmptyInboxDelta(prepared.inbox)) return Object.freeze({ value: this.readPicture(prepared), committed: false })
    // The record carries progress, not the picture: the Thread, its facts,
    // the anchor and the reader's Attention are projection state every replay
    // already holds.
    const data: AgentTeamThreadReadReceipt = Object.freeze({ workspaceId: request.workspaceId, memberId: actor.memberId,
      threadRef: prepared.thread.threadRef, ...(prepared.task === undefined ? {} : { taskRef: prepared.task.taskRef }),
      readThroughSequence: prepared.readThroughSequence,
      ...(prepared.selectedThroughSequence === undefined ? {} : { selectedThroughSequence: prepared.selectedThroughSequence }),

  })
  await expect(harness(storedPool(movedSelection))).rejects.toThrow(/invalid Thread read receipt/)
})

it('rejects a selection outside the Thread revision or not a non-negative integer', async () => {
  const { ledger, reader, sent, revision } = await seededReaderThread()
  expect(() => ledger.previewThreadRead({ requestId: requestId('too-far'), workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor, selectedThroughSequence: revision + 1 }))
    .toThrow(/selectedThroughSequence/)
  await expect(ledger.readThread({ requestId: requestId('negative'), workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor, selectedThroughSequence: -1 }))
    .rejects.toThrow(/selectedThroughSequence/)
  await expect(ledger.readThread({ requestId: requestId('fractional'), workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor, selectedThroughSequence: 1.5 }))
    .rejects.toThrow(/selectedThroughSequence/)
})

it('binds a request id to an explicit selection but not one computed inside the queue', async () => {
  const { ledger, reader, sent, replies } = await seededReaderThread()
  const sequences = replies.map(reply => reply.sequence)
  const id = requestId('once')
  let selectCalls = 0
  const first = await ledger.readThread({ requestId: id, workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor }, () => {
    selectCalls += 1
    return sequences[1]!
  })
  expect(first.committed).toBe(true)
  expect(selectCalls).toBe(1)

  // A stored request retry neither reruns the selection nor compares the
  // computed bound it persisted.
  const retry = await ledger.readThread({ requestId: id, workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor })
  expect(retry.committed).toBe(false)
  expect(retry.value.receipt?.requestId).toBe(id)
  expect(selectCalls).toBe(1)

  // An explicit request selection is still part of the payload comparison.
  await expect(ledger.readThread({ requestId: id, workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor, selectedThroughSequence: sequences[2]! }))
    .rejects.toThrow(/was reused with a different operation or payload/)
  const sameExplicit = await ledger.readThread({ requestId: id, workspaceId: alpha,
    taskRef: sent.task.taskRef, actor: reader.actor, selectedThroughSequence: sequences[1]! })
  expect(sameExplicit.committed).toBe(false)
})

