import { createHash } from 'node:crypto'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { activityFact, activityFactDigest, activityIdentity, activityText, type ActivityFact, type ActivityIdentity } from './activity-facts.ts'
