import { afterEach, describe, expect, it } from 'vitest'
import { createUserMessage } from '@deepseek-ai/dsh-llm'
import { SessionSeq } from '@deepseek-ai/dsh-session'
import { cleanups, realHarness, ScriptedAdapter, textResponse, toolCallResponse, requestId, waitFor } from './helpers/member-harness.ts'

afterEach(async () => { await Promise.all(cleanups.splice(0).map(cleanup => cleanup())) })

async function mainStream() {
  const adapter = new ScriptedAdapter()
  const test = await realHarness(adapter)
  const project = await test.ctx.agentTeam.createProject({ requestId: requestId('project'), workspaceId: test.workspaceId,
    name: 'Install checks', description: 'Verify the signed installer' })
  const projectRef = project.project.projectRef
  const member = await test.ctx.agentTeam.addMember({ requestId: requestId('member'), workspaceId: test.workspaceId,
    handle: 'builder', description: 'Checks installation', presetId: 'team-member', projectRefs: [projectRef] })
  const agent = test.ctx.agents.get(member.status.member.sessionId)!
  await test.ctx.agentTeam.changeAttentionForAgent(agent, { requestId: requestId('follow'), workspaceId: test.workspaceId, projectRef, action: 'follow' })
  async function post(body: string) {
    await test.ctx.agentTeam.readMainStream({ requestId: requestId(`human-read-${adapter.requests.length}`), workspaceId: test.workspaceId, projectRef })
    const before = adapter.requests.length
    adapter.enqueue(textResponse('Noted.'))
    const result = await test.ctx.agentTeam.postMainMessage({ requestId: requestId(`post-${before}`), workspaceId: test.workspaceId, projectRef, body })
    if (result.kind !== 'committed') throw new Error('setup post failed')
    await waitFor(() => adapter.requests.length > before ? true : undefined)
    await agent.whenIdle()
    return result.message
  }
  async function call(action: 'read' | 'message' | 'post', messageRef?: string) {
    const before = adapter.requests.length
    adapter.enqueue(toolCallResponse(`call-${before}`, action === 'post' ? 'team_message' : 'team_thread', { action, projectRef,
      ...(action === 'post' ? { body: 'I will verify the signed installer in a path with spaces.' } : {}),
      ...(messageRef === undefined ? {} : { messageRef }) }))
    adapter.enqueue(textResponse('Context checked.'))
    agent.followup(createUserMessage({ content: [{ type: 'text', text: 'Check the Project Main stream.' }], source: { kind: 'user' } }))
    await waitFor(() => adapter.requests.length === before + 2 ? true : undefined)
    await agent.whenIdle()
    const last = agent.session.deriveMessages().filter(message => message.role === 'tool').at(-1)!
    return last.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n')
  }
  return { ...test, adapter, agent, projectRef, post, call }
}

describe('Main read uses the current Session context', () => {
  it('reconsiders a complete Main rejection but stops for a new missing Message', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    await post('Ordinary change not included in the automatic notice.')
    const rejected = await call('post')
    expect(rejected).toContain('Not committed — main_unread_required')
    expect(rejected).toContain('Reconsider')
    expect(rejected).not.toContain('baseRevision')
    expect(await call('post')).toContain('Committed — Main stream message posted.')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(1)
    await post('A new ordinary update needs another review.')
    expect(await call('post')).toContain('Not committed — main_unread_required')
    const read = await call('read')
    expect(read).toContain('acknowledged 2 unread update(s)')
  })

  it('bounds a long Main rejection and keeps the Message unread until explicitly read', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    await post('Very long pending Main content. '.repeat(2000))
    const result = await call('post')
    expect(result.length).toBeLessThanOrEqual(16 * 1024)
    expect(result).toContain('truncated')
    expect(await call('post')).toContain('Not committed — main_unread_required')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(1)
  })

  it('posts after a complete direct notice without acknowledging it, then reads to confirm', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    const direct = await post('@builder verify the signed installer in a path with spaces.')
    expect(await call('post')).toContain('Committed — Main stream message posted.')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing).toMatchObject({ unreadCount: 1, directCount: 1 })
    const read = await call('read')
    expect(read).toContain('acknowledged 1 unread update(s)')
    expect(read).not.toContain(direct.body)
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(0)
  })

  it('stops without acknowledging when a Message exceeds the available context capacity', async () => {
    const { ctx, adapter, agent, workspaceId, projectRef, post, call } = await mainStream()
    adapter.resolveModelWindow = () => 32_000
    const long = await post('模型容量不足🙂'.repeat(12000))
    const result = await call('read')
    expect(result).toContain('Message exceeds the reading capacity')
    expect(result).toContain(long.messageRef)
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(1)
  })

  it('continues Main Messages in order and leaves a queried long Message unread until read', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    const long = await post('主线消息🙂不能提前确认。'.repeat(4200) + '全文结束。')
    const first = await call('message', long.messageRef)
    expect(first.length).toBeLessThanOrEqual(32 * 1024)
    expect(first).toContain('Message part')
    const second = await call('message', long.messageRef)
    expect(second).toContain('全文结束。')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(1)
    const acknowledged = await call('read')
    expect(acknowledged).toContain('acknowledged 1 unread update(s)')
    expect(acknowledged).not.toContain('主线消息')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(0)
    const next = await post('第二条长消息🙂'.repeat(6500) + '第二条结束。')
    const later = await post('This update stays behind the incomplete Message.')
    const page = await call('read')
    expect(page.length).toBeLessThanOrEqual(32 * 1024)
    expect(page).toContain('not acknowledged')
    expect(page).not.toContain(later.body)
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(2)
    for (let index = 0; index < 5 && ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount > 0; index += 1) {
      expect((await call('read')).length).toBeLessThanOrEqual(32 * 1024)
    }
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(0)
    expect(next.body).toContain('第二条结束。')
  })

  it('restores missing recent Messages after compaction without repeating them on the next read', async () => {
    const { ctx, agent, post, call } = await mainStream()
    const message = await post('Release checks need the signed package and a Windows path with spaces.')
    await call('read')
    const operationCount = ctx.agentTeam.status().operationCount
    const nodes = agent.session.surface.nodes.slice(1)
    agent.session.append('user/message', createUserMessage({ content: [{ type: 'text', text: 'Summary: continue release checks.' }], source: { kind: 'user' } }), {
      surfaceOp: { op: 'replace', startSeq: SessionSeq(nodes[0]!), endSeq: SessionSeq(nodes.at(-1)!) }, sourceEventSeqs: [...nodes],
    })
    const restored = await call('read')
    expect(restored).toContain('Background — not newly acknowledged')
    expect(restored).toContain(message.body)
    expect(ctx.agentTeam.status().operationCount).toBe(operationCount)
    const repeated = await call('read')
    expect(repeated).not.toContain(message.body)
    expect(repeated).not.toContain('Background — not newly acknowledged')
    expect(repeated).not.toContain('Main stream is empty')
    expect(ctx.agentTeam.status().operationCount).toBe(operationCount)
  })

  it('does not skip an unread Message hidden behind more than a page of Task cards', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    const unread = await post('Unread original before task cards. '.repeat(2000))
    for (let index = 0; index < 25; index += 1) await ctx.agentTeam.startThread({ requestId: requestId(`card-${index}`),
      workspaceId, projectRef, kind: 'task', body: `Task ${index}` })
    const result = await call('read')
    expect(result).toContain(unread.messageRef)
    expect(result).toContain('not acknowledged')
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(1)
  })

  it('acknowledges a complete direct notice without repeating its body', async () => {
    const { post, call } = await mainStream()
    const direct = await post('@builder verify the signed installer before approving release.')
    const result = await call('read')
    expect(result).toContain('acknowledged 1 unread update(s)')
    expect(result).not.toContain(direct.body)
    expect(result).toContain(direct.messageRef)
    expect(result).toContain('body already in current context; omitted')
  })

  it('acknowledges a queried Message without repeating its body and supplies the next Message', async () => {
    const { ctx, agent, workspaceId, projectRef, post, call } = await mainStream()
    const first = await post('Verify the Windows installer in a path containing spaces.')
    expect(await call('message', first.messageRef)).toContain(first.body)
    const second = await post('The signed package is ready for that verification.')
    const read = await call('read')
    expect(read).toContain('acknowledged 2 unread update(s)')
    expect(read).not.toContain(first.body)
    expect(read).toContain(first.messageRef)
    expect(read).toContain('body already in current context; omitted')
    expect(read).toContain(second.body)
    expect(ctx.agentTeam.mainStreamHistoryForAgent(agent, { workspaceId, projectRef }).standing.unreadCount).toBe(0)
  })
})

/**
 * Registry of every model-facing recovery line the Team renders: one entry per situation, built from the values the rejection holds so the line names the refused value. It lives in the Host because both tools and the ledger reject, and tools import the Host, never the reverse. `assertRecoveryCoverage` refuses entries no situation reaches; `forbidHandWrittenRecovery` scans model-facing sources for route sentences outside the registry.
 */

/** What a rejection hands the registry: the values the sentence should name. */
export interface RecoveryContext {
  /** The value the model passed that was refused, echoed so the line is concrete. */
  readonly refused?: string | undefined
  /** The Thread the rejected action was aimed at, when there is one. */
  readonly threadRef?: string | undefined
  /** The Task the rejected action was aimed at, when there is one. */
  readonly taskRef?: string | undefined
  /** The Project the rejected action was aimed at, when there is one. */
  readonly projectRef?: string | undefined
  /** The tool action whose parameter shape was wrong, when the fault is a shape. */
  readonly action?: string | undefined
  /** The parameter that belongs to another action, when the fault is that one. */
  readonly parameter?: string | undefined
  /** The action that parameter does belong to, when the fault is that one. */
  readonly owner?: string | undefined
  readonly completeFacts?: boolean | undefined
}

/** One registered way out: the situation it answers, and its words. */
export interface RecoveryEntry {
  /** The rejection kind this entry answers, exactly as the rejecting code spells it. */
  readonly kind: string
  /** The sentence, built from the context so it can name real values. */
  readonly sentence: (context: RecoveryContext) => string
}

/** One entry per model-facing fault, naming the next action and its value. Lookup is by exact kind so a new kind cannot inherit a neighbour's sentence. */
export const RECOVERY_REGISTRY: readonly RecoveryEntry[] = Object.freeze([
  {
    kind: 'unread_required',
    sentence: ({ threadRef, taskRef, completeFacts }: RecoveryContext) => [
      completeFacts
        ? 'Reconsider the pending updates above before writing; this did not mark them read. Use team_thread read if earlier context is missing. New updates, permissions and Task state are checked again.'
        : 'Read the pending updates with team_thread read before reconsidering this write.',
      ...(threadRef === undefined ? [] : [threadRef]),
      ...(taskRef === undefined ? [] : [taskRef]),
    ].join(' '),
  },
  {
    kind: 'main_unread_required',
    sentence: ({ projectRef, completeFacts }: RecoveryContext) => completeFacts
      ? 'Reconsider the complete Main stream updates above before posting; this did not mark them read. New updates, permissions and Project state are checked again.'
      : `Read the pending Main stream updates with team_thread read and projectRef${projectRef === undefined ? '' : ` ${projectRef}`} before reconsidering this post.`,
  },
  {
    kind: 'project_owner_required',
    sentence: ({ projectRef }: RecoveryContext) => `Only a Project owner starts or promotes a Thread — use team_message post to speak in ${projectRef === undefined ? 'the Project' : projectRef}'s Main stream, and mention an owner when the work needs one.`,
  },
  {
    kind: 'accountable_owner_required',
    sentence: ({ taskRef }: RecoveryContext) => `Only the Task's accountable owner or the Human does this${taskRef === undefined ? '' : ` (${taskRef})`} — ask them in the Thread, or, when you are the accountable, use team_task transfer first.`,
  },
  {
    kind: 'self_acceptance_forbidden',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent who held any Claim on${taskRef === undefined ? ' this Task' : ` ${taskRef}`} cannot accept it — if you are the accountable owner, use team_task transfer to give an uninvolved owner responsibility for acceptance; otherwise ask the accountable owner or the Human in the Thread to arrange verification.`,
  },
  {
    kind: 'accountable_target_invalid',
    sentence: ({ taskRef }: RecoveryContext) => `The accountable must be an enabled Project owner here or the Human${taskRef === undefined ? '' : ` (${taskRef})`} — choose a current owner with team_view as the accountable and retry; only the Human may transfer a finished Task.`,
  },
  {
    kind: 'accept_requires_in_review',
    sentence: ({ taskRef }: RecoveryContext) => `An Agent accepts only an in_review Task${taskRef === undefined ? '' : ` (${taskRef})`} — mark your Claim done with team_task done to hand it to review, or ask the Human to accept early.`,
  },
  {
    kind: 'not_project_member',
    sentence: ({ projectRef }: RecoveryContext) => `Only Project members take part in ${projectRef === undefined ? 'a Project' : projectRef} — choose a Project listed by team_view, or ask the Human or a Project owner to mention you there.`,
  },
  {
    kind: 'main_stream_addressing',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'threadRef and projectRef'} address different things — pass threadRef to read a Thread, or projectRef to read a Project's Main stream, and retry with one of them.`,
  },
  {
    kind: 'unread_remaining',
    sentence: () => 'call team_thread read again.',
  },
  {
    kind: 'stale_revision',
    sentence: ({ threadRef, completeFacts }: RecoveryContext) => completeFacts
      ? 'Reconsider the new facts above before using the current token; this did not mark them read. Use team_thread read if earlier context is missing. The next write is checked again.'
      : `Read ${threadRef ?? 'the Thread'} with team_thread read to obtain the required context and current token before reconsidering this write.`,
  },
  {
    // Same refusal as `stale_revision` with a different cause: the token was never a revision this Thread reached. The race sentence would send the model hunting for a nonexistent insertion. A distinct kind keeps exact-kind lookup reachable.
    kind: 'stale_revision_token_unrecognized',
    sentence: ({ threadRef }: RecoveryContext) => [
      'That write token is not a revision this Thread reached; this does not establish what context you have seen.',
      `Read ${threadRef ?? 'the Thread'} with team_thread read for context and a current token.`,
    ].join(' '),
  },
  {
    kind: 'missing_thread_identity',
    sentence: () => 'Copy a threadRef (or a taskRef on a Taskful Thread) from team_inbox or team_view, then retry.',
  },
  {
    kind: 'missing_message_ref',
    sentence: ({ refused }: RecoveryContext) => `Copy the messageRef you were shown${refused === undefined ? '' : ` (${refused})`}, then retry.`,
  },
  {
    kind: 'history_only_arguments',
    // Only `message` reaches this now: a read ignores a page size, because its batch is bounded by design and its footer already names what remains.
    sentence: ({ action }: RecoveryContext) => `${action ?? 'message'} reads one Message back and cannot page — drop beforeSequence and limit, or call action: history to page older facts.`,
  },
  {
    kind: 'action_only_arguments',
    // Named by parameter: `messageRef` belongs to `message` alone and would otherwise be dropped silently.
    sentence: ({ action, parameter, owner }: RecoveryContext) => `${action ?? 'read'} does not accept ${parameter ?? 'that parameter'} — drop it, or call action: ${owner ?? 'message'} where it belongs.`,
  },
  {
    kind: 'missing_write_token',
    sentence: () => 'Copy a next-write token from a fully drained team_thread read, your own last committed mutation, or a complete Thread rejection that explicitly provides one; reconsider the facts before writing.',
  },
  {
    kind: 'start_requires_project',
    sentence: () => 'start opens a new Thread: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'post_requires_project',
    sentence: () => 'post speaks in a Project\'s Main stream: copy a projectRef from team_view, and use reply instead when you already hold a threadRef.',
  },
  {
    kind: 'dm_requires_member',
    sentence: () => 'Copy the memberRef of an enabled Agent from team_view; a DM is a private note, so shared work belongs in a Thread reply.',
  },
  {
    kind: 'claim_requires_direction',
    sentence: () => 'claim opens a new Claim with your one-sentence direction — drop claimRef, or use done/release to change an existing one.',
  },
  {
    kind: 'claim_close_requires_ref',
    sentence: ({ action }: RecoveryContext) => `Copy the claimRef of your own Claim from team_task list or the Thread read; you can only ${action ?? 'close'} a Claim you own.`,
  },
  {
    kind: 'promote_requires_thread',
    sentence: () => 'promote needs the threadRef of the discussion Thread to turn into a Task — copy it from team_thread read or the Main stream card.',
  },
  {
    kind: 'task_action_requires_task',
    sentence: ({ action }: RecoveryContext) => `${action ?? 'This action'} needs a taskRef — copy one from team_task board or the Task's Thread read.`,
  },
  {
    kind: 'list_takes_task_only',
    sentence: () => 'Drop baseRevision, direction, claimRef, and threadRef — list takes only taskRef.',
  },
  {
    kind: 'board_takes_no_task',
    sentence: () => 'board reads the whole board — drop taskRef, threadRef, baseRevision, direction, and claimRef; to reach one Task, copy its taskRef from the board and use list.',
  },
  {
    kind: 'promote_takes_thread',
    sentence: () => 'promote works on a discussion Thread — drop taskRef, direction, and claimRef, and pass threadRef with the Thread’s current write token.',
  },
  {
    kind: 'claim_owned_by_another',
    sentence: ({ refused }: RecoveryContext) => `Claim ${refused ?? ''} belongs to another Member or another Task — list this Task's Claims with team_task list and close one of your own.`,
  },
  {
    kind: 'reply_target_unknown',
    sentence: ({ refused }: RecoveryContext) => `Reply target ${refused ?? ''} is not a recorded Message — copy a messageRef rendered by team_thread read, team_view, or an inbox notice.`,
  },
  {
    kind: 'message_read_unknown',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} is not a recorded Message — copy a messageRef rendered by team_thread read, team_view, or an inbox notice.`,
  },
  {
    kind: 'message_read_foreign',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} belongs to another Thread — read that Thread first, or copy a messageRef from this Thread's own read.`,
  },
  {
    kind: 'message_read_foreign_project',
    sentence: ({ refused }: RecoveryContext) => `Message ${refused ?? ''} belongs to another Project — read that Project's Main stream, or copy a messageRef from this Project's own Main stream read.`,
  },
  {
    kind: 'attachment_path_rejected',
    sentence: ({ refused }: RecoveryContext) => `Attachment ${refused ?? ''} was refused — attachments are absolute paths to one existing non-empty file within the byte limit; fix the path or drop the attachment.`,
  },
  {
    kind: 'unknown_ref',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'That ref'} does not name anything this workspace holds — reuse the full ref exactly as returned by Team tools, or list the candidates with team_view.`,
  },
  {
    kind: 'ambiguous_ref',
    sentence: ({ refused }: RecoveryContext) => `${refused ?? 'That ref'} matches several entries — reuse a longer prefix, or the full ref exactly as returned by Team tools.`,
  },
  {
    kind: 'workspace_required',
    sentence: ({ refused }: RecoveryContext) => `workspace is required when you participate in multiple Workspaces — choose one of: ${refused ?? ''}.`,
  },
  {
    kind: 'workspace_ambiguous',
    // `refused` already reads "workspace:X matches '…001', '…002'", so this
    // sentence supplies the verdict and the route and never a second verb.
    sentence: ({ refused }: RecoveryContext) => `${refused ?? ''} — that prefix is ambiguous: reuse a longer prefix, or the full Workspace id exactly as listed.`,
  },
  {
    kind: 'workspace_not_participating',
    sentence: ({ refused }: RecoveryContext) => `Not participating in Workspace ${refused ?? ''} — copy a full id from team_view, or a unique prefix of at least 6 hex characters.`,
  },
])

/** Every kind the registry answers, for the coverage check below. */
export const RECOVERY_KINDS: readonly string[] = Object.freeze(RECOVERY_REGISTRY.map(entry => entry.kind))

/** Look one entry up by exact kind; an unregistered kind is a bug, never a silent fallback. */
export function recoveryFor(kind: string): RecoveryEntry {
  const entry = RECOVERY_REGISTRY.find(candidate => candidate.kind === kind)
  if (entry === undefined) throw new Error(`no registered recovery for '${kind}'; add an entry to RECOVERY_REGISTRY`)
  return entry
}

/** Refuses a registry entry no produced situation reaches, and a produced situation with no entry. */
export function assertRecoveryCoverage(producedKinds: readonly string[]): void {
  const produced = new Set(producedKinds)
  for (const entry of RECOVERY_REGISTRY) {
    if (!produced.has(entry.kind)) {
      throw new Error(`recovery entry '${entry.kind}' matches no situation the Team produces`)
    }
  }
  for (const kind of produced) {
    if (!RECOVERY_KINDS.includes(kind)) throw new Error(`situation '${kind}' has no registered recovery`)
  }
}

/** Refuses a hand-written recovery sentence in model-facing source. Comments are stripped before the scan, so only what a model would read is checked. */
export function forbidHandWrittenRecovery(source: string, fileName: string): void {
  if (fileName.endsWith('recovery-hints.ts')) return
  const withoutComments = stripComments(source)
  // Imperative route shapes only: a bare `retry` also names variables and policies.
  const routePatterns = [
    /\b(then )?retry (this|it|the|with|again|without|after|a)\b/i,
    /\bcopy (a|an|the) [a-zA-Z]+ (from|rendered by|you were shown)/i,
    /\buse (action|reply|done|release)\b/i,
    /\bcall (team_|action:)/i,
    /\bdrop (them|it|beforeSequence|baseRevision|claimRef|direction)\b/i,
  ]
  for (const pattern of routePatterns) {
    const match = pattern.exec(withoutComments)
    if (match !== null) {
      const line = withoutComments.slice(0, match.index).split('\n').length
      throw new Error(`${fileName}:${line} spells a recovery route by hand; register it in recovery-hints.ts instead`)
    }
  }
}

/** Drop comments and their contents, preserving line numbering so a hit points at real code. */
function stripComments(source: string): string {
  return source.replaceAll(/\/\*[\s\S]*?\*\//gu, match => match.replaceAll(/[^\n]/gu, ' '))
    .replaceAll(/(^|[^:])\/\/[^\n]*/gu, (match, lead: string) => `${lead}${' '.repeat(match.length - lead.length)}`)
}

import { createHash } from 'node:crypto'
import type {
  AgentTeamActivity,
  AgentTeamActivityRef,
  AgentTeamClaimRef,
  AgentTeamMainActivity,
  AgentTeamMemberId,
  AgentTeamProjectRef,
  AgentTeamTaskRef,
  AgentTeamThreadRef,
} from './types.ts'

/** One Thread Activity projected from its ledger fact alone. Absent arrays have already become empty. */
export interface ThreadActivityFact {
  readonly scope: 'thread'
  readonly activityRef: AgentTeamActivityRef
  readonly sequence: number
  readonly kind: AgentTeamActivity['kind']
  readonly actor: AgentTeamMemberId
  readonly taskRef: AgentTeamTaskRef
  readonly threadRef: AgentTeamThreadRef
  readonly claimRef: AgentTeamClaimRef | null
  readonly claimRefs: readonly AgentTeamClaimRef[]
  readonly completedClaimRefs: readonly AgentTeamClaimRef[]
  readonly acceptedClaimRefs: readonly AgentTeamClaimRef[]
  readonly releasedClaimRefs: readonly AgentTeamClaimRef[]
  readonly from: AgentTeamMemberId | null
  readonly to: AgentTeamMemberId | null
  readonly refollowedMembers: readonly AgentTeamMemberId[]
}

/** One Main stream Activity projected from its ledger fact alone. */
export interface MainActivityFact {
  readonly scope: 'main'
  readonly activityRef: AgentTeamActivityRef
  readonly sequence: number
  readonly kind: AgentTeamMainActivity['kind']
  readonly actor: AgentTeamMemberId
  readonly projectRef: AgentTeamProjectRef
  readonly memberId: AgentTeamMemberId
}

export type ActivityFact = ThreadActivityFact | MainActivityFact

/** What a surface must match before a fact digest is even considered. */
export type ActivityIdentity =
  | {
    readonly scope: 'thread'
    readonly activityRef: AgentTeamActivityRef
    readonly threadRef: AgentTeamThreadRef
  }
  | {
    readonly scope: 'main'
    readonly activityRef: AgentTeamActivityRef
    readonly projectRef: AgentTeamProjectRef
  }

export function activityFact(activity: AgentTeamActivity): ThreadActivityFact
export function activityFact(activity: AgentTeamMainActivity): MainActivityFact
export function activityFact(activity: AgentTeamActivity | AgentTeamMainActivity): ActivityFact
export function activityFact(activity: AgentTeamActivity | AgentTeamMainActivity): ActivityFact {
  if ('threadRef' in activity) {
    return {
      scope: 'thread',
      activityRef: activity.activityRef,
      sequence: activity.sequence,
      kind: activity.kind,
      actor: activity.actor,
      taskRef: activity.taskRef,
      threadRef: activity.threadRef,
      claimRef: 'claimRef' in activity ? activity.claimRef : null,
      claimRefs: 'claimRefs' in activity ? [...activity.claimRefs] : [],
      completedClaimRefs: 'completedClaimRefs' in activity ? [...(activity.completedClaimRefs ?? [])] : [],
      acceptedClaimRefs: 'acceptedClaimRefs' in activity ? [...(activity.acceptedClaimRefs ?? [])] : [],
      releasedClaimRefs: 'releasedClaimRefs' in activity ? [...(activity.releasedClaimRefs ?? [])] : [],
      from: 'from' in activity ? activity.from ?? null : null,
      to: 'to' in activity ? activity.to ?? null : null,
      refollowedMembers: 'refollowedMembers' in activity ? [...(activity.refollowedMembers ?? [])] : [],
    }
  }
  return {
    scope: 'main',
    activityRef: activity.activityRef,
    sequence: activity.sequence,
    kind: activity.kind,
    actor: activity.actor,
    projectRef: activity.projectRef,
    memberId: activity.memberId,
  }
}

export function activityIdentity(fact: ActivityFact): ActivityIdentity {
  return fact.scope === 'thread'
    ? { scope: 'thread', activityRef: fact.activityRef, threadRef: fact.threadRef }
    : { scope: 'main', activityRef: fact.activityRef, projectRef: fact.projectRef }
}

/** Complete immutable event fields, without current Task/Claim state or empty optional lists. */
export function activityText(fact: ActivityFact): string {
  if (fact.scope === 'main') return `${fact.sequence} ${fact.actor} ${fact.kind} Member ${fact.memberId} · Project ${fact.projectRef} · ${fact.activityRef}`
  const fields = [`${fact.sequence} ${fact.actor} ${fact.kind} Task ${fact.taskRef} · Thread ${fact.threadRef} · ${fact.activityRef}`]
  if (fact.claimRef !== null) fields.push(`Claim ${fact.claimRef}`)
  if (fact.claimRefs.length > 0) fields.push(`claims released ${fact.claimRefs.join(', ')}`)
  if (fact.completedClaimRefs.length > 0) fields.push(`completed claims ${fact.completedClaimRefs.join(', ')}`)
  if (fact.acceptedClaimRefs.length > 0) fields.push(`accepted claims ${fact.acceptedClaimRefs.join(', ')}`)
  if (fact.releasedClaimRefs.length > 0) fields.push(`released claims ${fact.releasedClaimRefs.join(', ')}`)
  if (fact.from !== null) fields.push(`from ${fact.from}`)
  if (fact.to !== null) fields.push(`to ${fact.to}`)
  if (fact.refollowedMembers.length > 0) fields.push(`following restored for ${fact.refollowedMembers.join(', ')}`)
  return fields.join(' · ')
}

/** Explicit field order, so a JSON round trip's property order cannot change the digest. */
function canonicalActivityFact(fact: ActivityFact): string {
  if (fact.scope === 'main') {
    return JSON.stringify([fact.scope, fact.activityRef, fact.sequence, fact.kind, fact.actor, fact.projectRef, fact.memberId])
  }
  return JSON.stringify([
    fact.scope, fact.activityRef, fact.sequence, fact.kind, fact.actor, fact.taskRef, fact.threadRef,
    fact.claimRef, fact.claimRefs, fact.completedClaimRefs, fact.acceptedClaimRefs, fact.releasedClaimRefs,
    fact.from, fact.to, fact.refollowedMembers,
  ])
}

export function activityFactDigest(fact: ActivityFact): string {
  return createHash('sha256').update(canonicalActivityFact(fact)).digest('hex')
}

import { createHash } from 'node:crypto'
import type { Agent } from '@deepseek-ai/dsh-agent'
import { SessionLogOffset } from '@deepseek-ai/dsh-session'
import { activityFact, activityFactDigest, activityIdentity, type ActivityFact, type ActivityIdentity } from './activity-facts.ts'
import { isAgentTeamSource } from './context-source.ts'
import type { AgentTeamMainTimelineEntry, AgentTeamMemberId, AgentTeamProjectRef, AgentTeamThreadReadFact, AgentTeamThreadRef } from './types.ts'

export const NOTIFICATION_TRUNCATION_MARKER = '[Message body truncated; use team_thread read for the full Message.]'
export const NOTIFICATION_BODY_MAX_CHARACTERS = 8 * 1024

export type SurfaceActivityBinding = ActivityIdentity & { readonly factDigest: string }

export type TeamMessageSurface = {
  readonly textDigest: string
  readonly messages: readonly (MessageAddress & { readonly messageRef: string; readonly bodyDigest: string; readonly start?: number; readonly end?: number; readonly total?: number })[]
  readonly activities: readonly SurfaceActivityBinding[]
}

type MessageAddress = { readonly threadRef: string; readonly projectRef?: never }
  | { readonly projectRef: string; readonly threadRef?: never }

export type RenderedTeamMessage = MessageAddress & {
  readonly messageRef: string
  readonly body: string
  readonly part?: { readonly start: number; readonly end: number }
}

const digest = (text: string): string => createHash('sha256').update(text).digest('hex')

/** Bind rendered bodies or exact parts to the producer's complete output text. */
export function teamMessageSurface(text: string, messages: readonly RenderedTeamMessage[], activities: readonly ActivityFact[] = []) {
  const boundActivities = activities.map(fact => ({ ...activityIdentity(fact), factDigest: activityFactDigest(fact) }))
  return { textDigest: digest(text), messages: messages.map(message => ({
    ...(message.threadRef === undefined ? { projectRef: message.projectRef } : { threadRef: message.threadRef }),
    messageRef: message.messageRef, bodyDigest: digest(message.body),
    ...(message.part === undefined ? {} : { ...message.part, total: message.body.length }),
  })), activities: boundActivities }
}

/** A live projection, not a read receipt. Cropped text cannot attest through retained metadata. */
export function visibleTeamSurface(agent: Pick<Agent, 'session'>): readonly TeamMessageSurface[] {
  const entries: TeamMessageSurface[] = []
  for (const sequence of agent.session.surface.nodes) {
    const event = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
    if (event === undefined) continue
    const message = agent.session.deriveEventMessage(event)
    if (message === null) continue
    let binding: unknown
    if (event.type === 'user/message' && message.role === 'user' && isAgentTeamSource(message.source) && message.source.form === 'notice') {
      binding = message.source.teamFacts
    } else if (event.type === 'tool/result' && message.role === 'tool' && !message.isError) {
      const ownCall = event.sourceEventSeqs?.some(sequence => {
        const call = agent.session.snapshotEvents(SessionLogOffset(sequence), SessionLogOffset(sequence + 1))[0]
        return call?.type === 'tool/call' && call.data.callId === message.toolCallId
          && (call.data.name === 'team_thread' || call.data.name === 'team_message' || call.data.name === 'team_task')
      })
      if (!ownCall) continue
      const meta = event.data.meta
      if (typeof meta !== 'object' || meta === null || Array.isArray(meta)) continue
      binding = meta['teamFacts']
    }
    const surface = surfaceOf(binding)
    if (surface === undefined || message.content.some(part => part.type !== 'text')) continue
    const text = message.content.flatMap(part => part.type === 'text' ? [part.text] : []).join('\n')
    if (digest(text) === surface.textDigest) entries.push(surface)
  }
  return entries
}

function surfaceOf(value: unknown): TeamMessageSurface | undefined {
  if (typeof value !== 'object' || value === null) return undefined
  const surface = value as Partial<TeamMessageSurface> & { readonly activities?: unknown }
  if (typeof surface.textDigest !== 'string' || !Array.isArray(surface.messages)) return undefined
  if (!surface.messages.every(message => message !== null && typeof message === 'object'
    && ((typeof message.threadRef === 'string' && message.projectRef === undefined)
      || (typeof message.projectRef === 'string' && message.threadRef === undefined))
    && typeof message.messageRef === 'string' && typeof message.bodyDigest === 'string')) return undefined
  const activities = surface.activities
  if (activities !== undefined && (!Array.isArray(activities) || !activities.every(isSurfaceActivityBinding))) return undefined
  return { ...(surface as TeamMessageSurface), activities: (activities ?? []) as readonly SurfaceActivityBinding[] }
}

function isSurfaceActivityBinding(value: unknown): value is SurfaceActivityBinding {
  if (typeof value !== 'object' || value === null) return false
  const item = value as { readonly scope?: unknown; readonly activityRef?: unknown; readonly threadRef?: unknown; readonly projectRef?: unknown; readonly factDigest?: unknown }
  if (typeof item.activityRef !== 'string' || typeof item.factDigest !== 'string') return false
  return (item.scope === 'thread' && typeof item.threadRef === 'string' && item.projectRef === undefined)
    || (item.scope === 'main' && typeof item.projectRef === 'string' && item.threadRef === undefined)
}

export function isFactOnSurface(entries: readonly TeamMessageSurface[], fact: AgentTeamThreadReadFact, threadRef: AgentTeamThreadRef): boolean {
  if (fact.fact.kind === 'activity') {
    return fact.fact.activity.threadRef === threadRef && isActivityOnSurface(entries, activityFact(fact.fact.activity))
  }
  if (fact.fact.kind !== 'message' || fact.fact.message.body === '') return false
  const { messageRef, body } = fact.fact.message
  return missingMessageRange(entries, { threadRef, messageRef, body }) === undefined
}

export function isMainEntryOnSurface(entries: readonly TeamMessageSurface[], entry: AgentTeamMainTimelineEntry, projectRef: AgentTeamProjectRef): boolean {
  if (entry.kind === 'activity') {
    return entry.activity.projectRef === projectRef && isActivityOnSurface(entries, activityFact(entry.activity))
  }
  if (entry.kind !== 'message' || entry.message.body === '') return false
  return missingMessageRange(entries, { projectRef, messageRef: entry.message.messageRef, body: entry.message.body }) === undefined
}

/** A Command or Remote projection is not a Session output: only the bound activity text attests. */
export function isActivityOnSurface(entries: readonly TeamMessageSurface[], fact: ActivityFact): boolean {
  const identity = activityIdentity(fact)
  const factDigest = activityFactDigest(fact)
  return entries.some(entry => entry.activities.some(activity => activity.factDigest === factDigest
    && activity.activityRef === identity.activityRef
    && (identity.scope === 'thread'
      ? activity.scope === 'thread' && activity.threadRef === identity.threadRef
      : activity.scope === 'main' && activity.projectRef === identity.projectRef)))
}

export function missingMessageRange(entries: readonly TeamMessageSurface[], target: RenderedTeamMessage): { start: number; end: number } | undefined {
  const bodyDigest = digest(target.body)
  const ranges = entries.flatMap(entry => entry.messages.filter(message => message.threadRef === target.threadRef
    && message.projectRef === target.projectRef && message.messageRef === target.messageRef && message.bodyDigest === bodyDigest)
    .flatMap(message => message.start === undefined && message.end === undefined && message.total === undefined
      ? [{ start: 0, end: target.body.length }]
      : Number.isInteger(message.start) && Number.isInteger(message.end) && message.total === target.body.length
        && message.start! >= 0 && message.end! > message.start! && message.end! <= target.body.length
        ? [{ start: message.start!, end: message.end! }] : []))
    .sort((left, right) => left.start - right.start)
  let start = 0
  for (const range of ranges) {
    if (range.start > start) return { start, end: range.start }
    start = Math.max(start, range.end)
  }
  return start >= target.body.length ? undefined : { start, end: target.body.length }
}

export function surfaceVisibilityProbe(agentFor: (memberId: AgentTeamMemberId) => Agent | undefined) {
  return (memberId: AgentTeamMemberId, facts: readonly AgentTeamThreadReadFact[], threadRef: AgentTeamThreadRef): boolean => {
    const agent = agentFor(memberId)
    if (agent === undefined) return false
    const entries = visibleTeamSurface(agent)
    return facts.every(fact => isFactOnSurface(entries, fact, threadRef))
  }
}

