from pathlib import Path
import subprocess


def once(text, old, new):
    assert text.count(old) == 1, old[:100]
    return text.replace(old, new, 1)


host = 'packages/agent-team/src/index.ts'
text = Path(host).read_text()
text = once(text, 'this.notificationText(notifications, member.memberId, mainNotifications, plan)', 'this.notificationText(notifications, member.memberId, mainNotifications)')
text = once(text, ' = [], deliveryPlan?: InboxDeliveryPlan):', ' = []):')
text = once(text, 'const plan = deliveryPlan ?? (readerId === undefined ? undefined : this.inboxDeliveryPlan(notifications, main))', 'const plan = readerId === undefined ? undefined : this.inboxDeliveryPlan(notifications, main)')
text = once(text, '''    // A running edge often follows the commit wake synchronously. Once the
    // commit has recorded coverage, rereading the same durable facts adds no
    // delivery decision; an empty coverage still falls through for retry.
    const delivery = this.inboxNoticeDeliveries.get(member.memberId)
    if (cause.kind === 'running' && delivery?.covered !== undefined && delivery.covered !== '') {
      this.ctx.logger.debug(`agent-team: Team Inbox notice not attempted for ${this.memberScope(member.memberId, agent.id)} cause ${this.notificationCauseText(cause)}: the same unread facts already have a delivery attempt`)
      return
    }
''', '')

ledger = 'packages/agent-team/src/ledger.ts'
ledger_text = Path(ledger).read_text()
ledger_text = once(ledger_text, '''  /** A one-call read set lets notificationFacts reuse the facts memberInbox already derived. */
  private notificationReadSet: { readonly memberId: AgentTeamMemberId; readonly facts: Map<AgentTeamThreadRef, readonly AgentTeamThreadReadFact[]> } | undefined
''', '')
ledger_text = once(ledger_text, '''    const previous = this.notificationReadSet
    const readSet = { memberId, facts: new Map<AgentTeamThreadRef, readonly AgentTeamThreadReadFact[]>() }
    this.notificationReadSet = readSet
    try {
      const inbox = request === undefined ? this.memberInbox(actor, {}) : this.inbox(actor, request)
      return Object.freeze(inbox.items.map(item => Object.freeze({ item,
        facts: readSet.facts.get(item.thread.threadRef) ?? this.unreadFor(memberId, item.thread.threadRef), reminders: item.reminders })))
    } finally {
      this.notificationReadSet = previous
    }
''', '''    const inbox = request === undefined ? this.memberInbox(actor, {}) : this.inbox(actor, request)
    return Object.freeze(inbox.items.map(item => Object.freeze({ item,
      facts: this.unreadFor(memberId, item.thread.threadRef), reminders: item.reminders })))
''')
ledger_text = once(ledger_text, '''    const readSet = this.notificationReadSet
    if (readSet?.memberId === memberId && readSet.facts.has(threadRef)) return readSet.facts.get(threadRef)!
    const facts = this.unreadForFrom(this.state, memberId, threadRef)
    if (readSet?.memberId === memberId) readSet.facts.set(threadRef, facts)
    return facts
''', '''    return this.unreadForFrom(this.state, memberId, threadRef)
''')

for path, content in [(host, text), (ledger, ledger_text)]:
    oid = subprocess.check_output(['git', 'hash-object', '-w', '--stdin'], input=content.encode()).decode().strip()
    subprocess.run(['git', 'update-index', '--cacheinfo', f'100644,{oid},{path}'], check=True)
    print('Staged only Activity/Main changes:', path)

