import { describe, expect, it, vi } from 'vitest'
import type { ToolDefinition } from '@deepseek-ai/dsh-tools'
import { Session, SessionId } from '@deepseek-ai/dsh-session'
import { teamTools } from './render-text.ts'

/**
 * Execution-level tests for Team addressing: a call addresses either a Thread
 * (threadRef, or taskRef when that Thread has a Task) or a Project's Main
 * stream (projectRef), never both; two Thread refs may coexist when they name
 * the same Thread. `message` is the one Thread action that requires threadRef
 * and does not accept taskRef.
 */

const THREAD = 'thread:d78400e4-4925-4065-87b1-3f81b4a4b5fb'
const TASK = 'task:3245ad40-43fd-4191-a416-7dcaf3a340f2'
const PROJECT = 'project:046dd831-c679-4279-b6aa-7813476cf12e'
const MEMBER = 'member:6e8a5b10-df16-4ec0-943a-63738010953f'
const MESSAGE = 'message:4bf83cfd-2a1b-4c3d-9e4f-5a6b7c8d9e0f'
const WORKSPACE = 'workspace:alpha'

const READ = {
  thread: { threadRef: THREAD, revision: 20 },
  anchor: { messageRef: 'message:anchor', sender: MEMBER, body: 'subject', sequence: 1, occurredAt: '2026-10-29T00:00:00.000Z', projectRef: PROJECT },
  anchorMentions: [], claims: [], facts: [], readThroughSequence: 1, remainingUnreadCount: 0,
  consumedDirectMarkers: [], reminders: [], visibleMessageRefs: [], visibleActivityRefs: [],
}
const HISTORY = { thread: READ.thread, anchor: READ.anchor, anchorMentions: [], claims: [], facts: [], cursor: 1, hasMore: false, taskCards: [] }

function host(overrides: Record<string, unknown> = {}): Record<string, unknown> {
  return {
    workspacesForAgent: () => [{ workspaceId: WORKSPACE, path: undefined, default: true }],
    humanHandle: () => 'human',
    members: () => [],
    resolveTaskRefs: () => ({ resolved: [] }),
    attentionStatusForAgent: vi.fn(() => ({ attention: { source: 'self' } })),
    changeAttentionForAgent: vi.fn(async () => ({ thread: { threadRef: THREAD, revision: 21 }, attention: { source: 'self' } })),
    threadHistoryForAgent: vi.fn(() => HISTORY),
    readThreadForAgent: vi.fn(async () => READ),
    readMessageForAgent: vi.fn(() => ({ messageRef: MESSAGE, sender: MEMBER, sequence: 3, body: 'text' })),
    ...overrides,
  }
}

async function call(tool: ToolDefinition, args: Record<string, unknown>, fakeHost: Record<string, unknown>): Promise<unknown> {
  const agent = { id: 'agent:addressing', options: {}, session: Session.create(SessionId('session:addressing')),
    ctx: { get: (name: string) => name === 'agentTeam' ? fakeHost : undefined } }
  return tool.execute(args, { agent, callId: 'call:1', signal: new AbortController().signal } as never)
}

