    expect(fake.threadHistoryForAgent).toHaveBeenCalledWith(expect.anything(), expect.objectContaining({ threadRef: THREAD, taskRef: TASK }))
  })

  it('surfaces the Host refusal when the two Thread refs name different Threads', async () => {
    const fake = host({ attentionStatusForAgent: vi.fn(() => { throw new Error(`Task '${TASK}' does not belong to Thread '${THREAD}'`) }) })
    await expect(call(teamTools().get('team_attention')!, { action: 'status', threadRef: THREAD, taskRef: TASK }, fake))
      .rejects.toThrow(/does not belong/)
  })

