    const fake = host()
    await call(teamTools().get('team_thread')!, { action: 'read', threadRef: THREAD, taskRef: TASK }, fake)
    expect(fake.readThreadForAgent).toHaveBeenCalledWith(expect.anything(), expect.objectContaining({ threadRef: THREAD, taskRef: TASK }), expect.any(Function))

    await expect(call(teamTools().get('team_thread')!, { action: 'message', taskRef: TASK, messageRef: MESSAGE }, fake))
      .rejects.toThrow(/does not accept taskRef/)
    await expect(call(teamTools().get('team_thread')!, { action: 'message', threadRef: THREAD, taskRef: TASK, messageRef: MESSAGE }, fake))
      .rejects.toThrow(/does not accept taskRef/)
    expect(fake.readMessageForAgent).not.toHaveBeenCalled()
  })

  it('team_thread message still reads a Main stream Message with projectRef', async () => {
    const fake = host()
    await call(teamTools().get('team_thread')!, { action: 'message', projectRef: PROJECT, messageRef: MESSAGE }, fake)
    expect(fake.readMessageForAgent).toHaveBeenCalledWith(expect.anything(), expect.objectContaining({ projectRef: PROJECT, messageRef: MESSAGE }))
  })

  it('refuses a Thread and the Main stream in one call', async () => {
    const fake = host()
    await expect(call(teamTools().get('team_attention')!, { action: 'status', threadRef: THREAD, projectRef: PROJECT }, fake))
      .rejects.toThrow(/never both/)
    await expect(call(teamTools().get('team_thread')!, { action: 'read', threadRef: THREAD, projectRef: PROJECT }, fake))
      .rejects.toThrow(/Thread ref and projectRef/)
    expect(fake.readThreadForAgent).not.toHaveBeenCalled()
  })
})

describe('active Claim blocks unfollow', () => {
  it('surfaces the Host refusal instead of reporting an Attention change', async () => {
    const fake = host({ changeAttentionForAgent: vi.fn(async () => {
      throw new Error(`Member cannot unfollow Thread '${THREAD}' while owning an active Claim on Task '${TASK}'; finish the work or release the Claim first`)
    }) })
    await expect(call(teamTools().get('team_attention')!, { action: 'unfollow', threadRef: THREAD }, fake))
